repomix.files:
This section contains the contents of the repository's files./*
 * Hub repetidor / star coupler para topologia en estrella o arbol.
 *
 * Un microcontrolador con un transceptor CAN por ramal. Cada ramal es un bus
 * lineal propio terminado con 120 ohm en sus dos extremos; el hub los une
 * reenviando tramas entre ramales (con anti-bucle por huella de trama) y,
 * en modo LEARNED, enrutando los comandos dirigidos solo hacia la rama que
 * aloja al nodo destino.
 *
 *   [rama 0: backbone/gateway] ---.
 *   [rama 1: dispositivos]     ---+--- HUB ---
 *   [rama 2: dispositivos]     ---'
 *
 * Valida el cableado antes de energizar con `validateWiring(...)` segun el
 * perfil de `bus_profile.h` y luego entra en el bucle de reenvio.
 */

#include <PCD_CAN.h>

namespace {

/* Velocidad conservadora para estrella/arbol (ver recommendedProfile). */
const uint32_t kHubBitrate = 125000UL;

#if defined(ARDUINO_ARCH_ESP32)
/* ESP32 integra un unico controlador TWAI. Para mas de una rama se agregan
 * transceptores MCP2515 por SPI (consultar hal/hal_can_mcp2515.h, hoy AVR). */
const int kBackboneTx = 5;
const int kBackboneRx = 4;
pcd::Esp32TwaiBus g_backbone(kBackboneTx, kBackboneRx);
pcd::CanTreeHub g_hub(kHubBitrate);
#elif defined(__AVR__)
/* AVR: un MCP2515 por ramal, cada uno con su CS propio en el bus SPI. */
pcd::Mcp2515Bus g_backbone(10, pcd::MCP_CLOCK_16MHZ);
pcd::Mcp2515Bus g_branch_a(9, pcd::MCP_CLOCK_16MHZ);
pcd::Mcp2515Bus g_branch_b(8, pcd::MCP_CLOCK_16MHZ);
pcd::CanTreeHub g_hub(kHubBitrate);
#else
/* Entorno de escritorio: sin hardware, solo estructura de referencia. */
pcd::CanTreeHub g_hub(kHubBitrate);
#endif

void reportWiring() {
    /* Estrella: ramas de hasta 60 cm de derivacion y 100 m, con hub. */
    const pcd::BusWiringIssue issue =
        pcd::validateWiring(pcd::BUS_TOPOLOGY_STAR, kHubBitrate, 60, 600, 100, 2, true);
    if (issue != pcd::BUS_WIRING_OK) {
        /* LOG_ERROR(pcd::wiringIssueName(issue)); */
    }
}

}  // namespace

void setup() {
    reportWiring();

#if defined(ARDUINO_ARCH_ESP32)
    g_hub.addPort(g_backbone, pcd::kBackboneSegment);
    /* g_hub.addPort(mcp_branch_a, 1); ... */
#elif defined(__AVR__)
    g_hub.addPort(g_backbone, pcd::kBackboneSegment);
    g_hub.addPort(g_branch_a, 1);
    g_hub.addPort(g_branch_b, 2);
#endif

    g_hub.setRouteMode(pcd::HUB_ROUTE_LEARNED);
    if (!g_hub.begin(kHubBitrate)) {
        /* LOG_ERROR("No se pudo inicializar algun ramal CAN"); */
    }
}

void loop() {
    g_hub.poll(millis());
}#include "bridge/bridge_dali.h"

#include <string.h>

#include "device_manager.h" /* unpackSetValueTarget / unpackSetValueFade */

namespace pcd {

uint16_t daliDirectArcPower(uint8_t short_address, uint8_t level) {
    const uint8_t address = static_cast<uint8_t>(((short_address & 0x3F) << 1) | 0x01);
    return static_cast<uint16_t>((static_cast<uint16_t>(address) << 8) | (level & 0xFF));
}

uint16_t daliShortCommand(uint8_t short_address, uint8_t command) {
    const uint8_t address = static_cast<uint8_t>((short_address & 0x3F) << 1);
    return static_cast<uint16_t>((static_cast<uint16_t>(address) << 8) | command);
}

uint16_t daliGroupArcPower(uint8_t group, uint8_t level) {
    const uint8_t address = static_cast<uint8_t>(0x80 | ((group & 0x0F) << 1) | 0x01);
    return static_cast<uint16_t>((static_cast<uint16_t>(address) << 8) | (level & 0xFF));
}

uint16_t daliGroupCommand(uint8_t group, uint8_t command) {
    const uint8_t address = static_cast<uint8_t>(0x80 | ((group & 0x0F) << 1));
    return static_cast<uint16_t>((static_cast<uint16_t>(address) << 8) | command);
}

uint16_t daliBroadcastArcPower(uint8_t level) {
    return static_cast<uint16_t>((static_cast<uint16_t>(kDaliBroadcastDapc) << 8) |
                                 (level & 0xFF));
}

uint16_t daliBroadcastCommand(uint8_t command) {
    return static_cast<uint16_t>((static_cast<uint16_t>(kDaliBroadcastCommand) << 8) | command);
}

DaliFrame splitDaliFrame(uint16_t frame) {
    DaliFrame out;
    out.address_byte = static_cast<uint8_t>(frame >> 8);
    out.data_byte = static_cast<uint8_t>(frame & 0xFF);
    return out;
}

bool daliIsDirectArcPower(uint16_t frame) {
    const uint8_t address = static_cast<uint8_t>(frame >> 8);
    if ((address & 0x80) == 0) {
        return (address & 0x01) != 0; /* direccion corta */
    }
    if ((address & 0xC0) == 0x80) {
        return (address & 0x01) != 0; /* direccion de grupo */
    }
    if (address >= 0xFC) {
        return (address & 0x01) != 0; /* broadcast */
    }
    return false; /* comando especial: 101CCCC1 / 110CCCC1 */
}

/*
 * Mapeo porcentaje -> nivel DALI.
 *
 * La curva luminosa real de DALI es logaritmica; aqui el porcentaje se
 * interpreta como posicion de consigna (arc power) para que el mapeo sea
 * determinista e invertible en ambos sentidos sin libreria matematica. El
 * proyecto que quiera curva perceptual puede aplicar su propia tabla antes de
 * llamar al puente (ver wiki 11).
 */
uint8_t daliLevelFromPercent(uint8_t percent) {
    if (percent == 0) {
        return 0;
    }
    if (percent >= 100) {
        return kDaliMaxLevel;
    }
    const uint32_t level = (static_cast<uint32_t>(percent) * kDaliMaxLevel + 50UL) / 100UL;
    return static_cast<uint8_t>(level > kDaliMaxLevel ? kDaliMaxLevel : level);
}

uint8_t daliPercentFromLevel(uint8_t level) {
    if (level == 0) {
        return 0;
    }
    if (level >= kDaliMaxLevel) {
        return 100;
    }
    return static_cast<uint8_t>((static_cast<uint32_t>(level) * 100UL + kDaliMaxLevel / 2) /
                                kDaliMaxLevel);
}

/*
 * Codigo de fade time DALI (0 = sin fundido). La escala normalizada crece en
 * razon raiz de 2 desde 0,7 s: 0,7 / 1 / 1,4 / 2 / 2,8 / 4 / 5,7 / 8 / 11,3 /
 * 16 / 22,6 / 32 / 45 / 64 / 90 segundos. Se calcula con aritmetica entera.
 */
uint8_t daliFadeTimeCode(uint32_t fade_ms) {
    if (fade_ms == 0) {
        return 0;
    }
    uint32_t candidate_ms = 707; /* codigo 1 */
    for (uint8_t code = 1; code < 15; ++code) {
        const uint32_t next_ms = (candidate_ms * 1414UL) / 1000UL;
        if (fade_ms < (candidate_ms + next_ms) / 2UL) {
            return code;
        }
        candidate_ms = next_ms;
    }
    return 15;
}

DaliBridge::DaliBridge(IDaliTransport &transport)
    : transport_(transport),
      track_next_(0),
      pending_count_(0),
      frames_sent_(0),
      backward_received_(0) {
    memset(tracked_, 0, sizeof(tracked_));
    for (uint8_t i = 0; i < 8; ++i) {
        pending_[i] = CanonicalFrame();
    }
}

bool DaliBridge::sendFrame(uint16_t frame) {
    if (transport_.sendFrame == 0) {
        return false;
    }
    if (!transport_.sendFrame(frame, transport_.ctx)) {
        return false;
    }
    ++frames_sent_;
    return true;
}

void DaliBridge::rememberLevel(uint8_t short_address, uint8_t level) {
    for (uint8_t i = 0; i < CAN_DALI_TRACK_SLOTS; ++i) {
        if (tracked_[i].valid && tracked_[i].address == short_address) {
            tracked_[i].level = level;
            return;
        }
    }
    TrackedChannel &slot = tracked_[track_next_];
    slot.address = short_address;
    slot.level = level;
    slot.valid = true;
    track_next_ = static_cast<uint8_t>((track_next_ + 1) % CAN_DALI_TRACK_SLOTS);
}

uint8_t DaliBridge::trackedLevel(uint8_t short_address) const {
    for (uint8_t i = 0; i < CAN_DALI_TRACK_SLOTS; ++i) {
        if (tracked_[i].valid && tracked_[i].address == short_address) {
            return tracked_[i].level;
        }
    }
    return 0;
}

bool DaliBridge::sendLevel(uint8_t channel, uint8_t level) {
    if (channel <= kDaliShortMax) {
        rememberLevel(channel, level);
        return sendFrame(daliDirectArcPower(channel, level));
    }
    if (channel >= kDaliGroupBase && channel <= kDaliGroupMax) {
        return sendFrame(daliGroupArcPower(static_cast<uint8_t>(channel - kDaliGroupBase), level));
    }
    if (channel == kDaliBroadcastChannel) {
        return sendFrame(daliBroadcastArcPower(level));
    }
    return false;
}

bool DaliBridge::process(const CanonicalFrame &frame) {
    if (frame.resource != RES_DALI_LIGHT && frame.resource != RES_LIGHT &&
        frame.resource != RES_DIMMER) {
        return false;
    }
    const uint8_t channel = frame.channel;

    if (frame.action == ACT_SCENE) {
        const uint8_t scene = static_cast<uint8_t>(frame.param & 0x0F);
        const uint8_t command = static_cast<uint8_t>(DALI_CMD_GO_TO_SCENE_0 + scene);
        if (channel <= kDaliShortMax) {
            return sendFrame(daliShortCommand(channel, command));
        }
        if (channel >= kDaliGroupBase && channel <= kDaliGroupMax) {
            return sendFrame(
                daliGroupCommand(static_cast<uint8_t>(channel - kDaliGroupBase), command));
        }
        if (channel == kDaliBroadcastChannel) {
            return sendFrame(daliBroadcastCommand(command));
        }
        return false;
    }

    uint8_t level = 0;
    switch (frame.action) {
        case ACT_OFF:
            level = 0;
            break;
        case ACT_ON: {
            const uint8_t command = DALI_CMD_RECALL_MAX_LEVEL;
            if (channel <= kDaliShortMax) {
                rememberLevel(channel, kDaliMaxLevel);
                return sendFrame(daliShortCommand(channel, command));
            }
            if (channel >= kDaliGroupBase && channel <= kDaliGroupMax) {
                return sendFrame(
                    daliGroupCommand(static_cast<uint8_t>(channel - kDaliGroupBase), command));
            }
            if (channel == kDaliBroadcastChannel) {
                return sendFrame(daliBroadcastCommand(command));
            }
            return false;
        }
        case ACT_TOGGLE: {
            const uint8_t current = trackedLevel(channel);
            level = current > 0 ? 0 : kDaliMaxLevel;
            break;
        }
        case ACT_SET_VALUE: {
            uint8_t target = static_cast<uint8_t>(unpackSetValueTarget(frame.param));
            const uint16_t fade_ms = unpackSetValueFade(frame.param);
            if (target > 100) {
                target = 100;
            }
            level = daliLevelFromPercent(target);
            if (fade_ms > 0 && channel <= kDaliShortMax) {
                /* El fade time DALI se programa por balasto mediante DTR. */
                sendFrame(static_cast<uint16_t>((static_cast<uint16_t>(kDaliSpecialSetDtr)
                                                 << 8) |
                                                daliFadeTimeCode(fade_ms)));
                sendFrame(daliShortCommand(channel, DALI_CMD_STORE_FADE_TIME));
            }
            break;
        }
        default:
            return false;
    }
    return sendLevel(channel, level);
}

bool DaliBridge::queueLevel(uint8_t short_address, uint8_t level, uint16_t source_id,
                            uint8_t resource) {
    if (short_address > kDaliShortMax || pending_count_ >= 8) {
        return false;
    }
    CanonicalFrame &entry = pending_[pending_count_++];
    entry = CanonicalFrame();
    entry.protocol = PROTO_CAN;
    entry.source_id = source_id;
    entry.resource = resource;
    entry.channel = short_address;
    entry.value = static_cast<float>(daliPercentFromLevel(level));
    entry.flags = DIAG_NONE;
    entry.is_command = 0;
    rememberLevel(short_address, level);
    return true;
}

void DaliBridge::onBackwardFrame(uint8_t short_address, uint8_t status) {
    ++backward_received_;
    if (short_address <= kDaliShortMax) {
        rememberLevel(short_address, status);
    }
}

bool DaliBridge::buildCanonical(CanonicalFrame &out) {
    if (pending_count_ == 0) {
        return false;
    }
    out = pending_[0];
    for (uint8_t i = 1; i < pending_count_; ++i) {
        pending_[i - 1] = pending_[i];
    }
    --pending_count_;
    pending_[pending_count_] = CanonicalFrame();
    return true;
}

bool DaliBridge::available() const {
    return pending_count_ > 0;
}

}  // namespace pcd#pragma once

/*
 * Extension DALI (iluminacion profesional).
 *
 * El bus DALI es un bus de 16 bits hacia los balastos (forward frame) y 8 bits
 * de respuesta (backward frame), con velocidad fija de 1200 bps. Esta libreria
 * NO genera la senal electrica: define la codificacion de las tramas y un
 * puente agnostico que traduce comandos PCD a DALI y estados DALI a PCD, de modo
 * que el firmware solo tenga que aportar el driver de linea (optoacoplado) y la
 * fuente de alimentacion DALI.
 *
 * Mapeo acordado con el protocolo PCD:
 *
 *   ResourceType          RES_DALI_LIGHT (0x86)
 *   Canal                 0..63  -> direccion corta DALI
 *                         0x80..0x8F -> grupo DALI 0..15
 *                         0xFF  -> broadcast DALI
 *   ACT_ON / ACT_OFF      RECALL MAX LEVEL / OFF
 *   ACT_TOGGLE            conmutacion local del nivel recordado
 *   ACT_SET_VALUE         Direct Arc Power Control (0..100 % -> 0..254)
 *   MSG_GROUP + param     GO TO SCENE 0..15
 *
 * El nivel recordado se guarda por direccion corta en una tabla de 16 entradas
 * (suficiente para el uso tipico de un ramal; ampliable con CAN_DALI_TRACK_SLOTS).
 */

#include <stddef.h>
#include <stdint.h>

#include "bridge/bridge.h"
#include "can_protocol.h"

namespace pcd {

/* Direcciones y constantes DALI. */
static const uint8_t kDaliShortMax = 63;
static const uint8_t kDaliGroupBase = 0x80;
static const uint8_t kDaliGroupMax = 0x8F;
static const uint8_t kDaliBroadcastChannel = 0xFF;
static const uint8_t kDaliBroadcastDapc = 0xFF;
static const uint8_t kDaliBroadcastCommand = 0xFE;
static const uint8_t kDaliSpecialSetDtr = 0xA3;
static const uint8_t kDaliMaxLevel = 254;

/* Comandos DALI estandar (segundo byte del forward frame). */
enum DaliCommand : uint8_t {
    DALI_CMD_OFF = 0x00,
    DALI_CMD_UP = 0x01,
    DALI_CMD_DOWN = 0x02,
    DALI_CMD_STEP_UP = 0x03,
    DALI_CMD_STEP_DOWN = 0x04,
    DALI_CMD_RECALL_MAX_LEVEL = 0x05,
    DALI_CMD_RECALL_MIN_LEVEL = 0x06,
    DALI_CMD_ON_AND_STEP_UP = 0x08,
    DALI_CMD_GO_TO_SCENE_0 = 0x10,
    DALI_CMD_RESET = 0x20,
    DALI_CMD_STORE_MAX_LEVEL = 0x2A,
    DALI_CMD_STORE_MIN_LEVEL = 0x2B,
    DALI_CMD_STORE_FADE_TIME = 0x2E
};

#ifndef CAN_DALI_TRACK_SLOTS
#define CAN_DALI_TRACK_SLOTS 16
#endif

/* ------------------------------------------------------------------ */
/* Codificacion de tramas DALI                                          */
/* ------------------------------------------------------------------ */

uint16_t daliDirectArcPower(uint8_t short_address, uint8_t level);
uint16_t daliShortCommand(uint8_t short_address, uint8_t command);
uint16_t daliGroupArcPower(uint8_t group, uint8_t level);
uint16_t daliGroupCommand(uint8_t group, uint8_t command);
uint16_t daliBroadcastArcPower(uint8_t level);
uint16_t daliBroadcastCommand(uint8_t command);

/* Trama DALI descompuesta. */
struct DaliFrame {
    uint8_t address_byte;
    uint8_t data_byte;

    uint16_t raw() const {
        return static_cast<uint16_t>((static_cast<uint16_t>(address_byte) << 8) | data_byte);
    }
};

DaliFrame splitDaliFrame(uint16_t frame);
bool daliIsDirectArcPower(uint16_t frame);

/* Conversion entre porcentaje (0..100) y nivel DALI (0..254). */
uint8_t daliLevelFromPercent(uint8_t percent);
uint8_t daliPercentFromLevel(uint8_t level);

/* Codigo de fade time DALI mas cercano a un tiempo en milisegundos. */
uint8_t daliFadeTimeCode(uint32_t fade_ms);

/* ------------------------------------------------------------------ */
/* Transporte inyectable                                                */
/* ------------------------------------------------------------------ */

struct IDaliTransport {
    /* Enviar un forward frame de 16 bits al bus DALI. */
    bool (*sendFrame)(uint16_t frame, void *ctx);
    /* Callback de backward frame (nivel o estado) recibido del bus DALI. */
    void (*onBackward)(uint8_t short_address, uint8_t status, void *ctx);
    void *ctx;

    IDaliTransport() : sendFrame(0), onBackward(0), ctx(0) {}
};

/* ------------------------------------------------------------------ */
/* Puente DALI <-> PCD                                                  */
/* ------------------------------------------------------------------ */

class DaliBridge : public IBridge {
  public:
    explicit DaliBridge(IDaliTransport &transport);

    /* Comando canonico -> DALI. */
    bool process(const CanonicalFrame &frame) override;

    /* Evento DALI -> canonico (nivel confirmado de un balasto). */
    bool buildCanonical(CanonicalFrame &out) override;
    bool available() const override;

    /* Encola un nivel leido del bus DALI para publicarlo como MSG_STATE. */
    bool queueLevel(uint8_t short_address, uint8_t level, uint16_t source_id,
                    uint8_t resource = RES_DALI_LIGHT);

    /* Ultimo nivel conocido de una direccion corta (0..254), 0 si no se sabe. */
    uint8_t trackedLevel(uint8_t short_address) const;
    uint32_t framesSent() const { return frames_sent_; }
    uint32_t backwardReceived() const { return backward_received_; }

    /* Notifica niveles recibidos por el transporte (llamar desde el callback). */
    void onBackwardFrame(uint8_t short_address, uint8_t status);

  private:
    bool sendFrame(uint16_t frame);
    bool sendLevel(uint8_t channel, uint8_t level);
    void rememberLevel(uint8_t short_address, uint8_t level);

    IDaliTransport &transport_;
    struct TrackedChannel {
        uint8_t address;
        uint8_t level;
        bool valid;
    };
    TrackedChannel tracked_[CAN_DALI_TRACK_SLOTS];
    uint8_t track_next_;

    CanonicalFrame pending_[8];
    uint8_t pending_count_;
    uint32_t frames_sent_;
    uint32_t backward_received_;
};

}  // namespace pcd#include "bridge/bridge_modbus_tcp.h"

#include <string.h>

namespace pcd {

/* ------------------------------------------------------------------ */
/* Helpers big-endian                                                  */
/* ------------------------------------------------------------------ */

static uint16_t be16(const uint8_t *p) {
    return static_cast<uint16_t>((static_cast<uint16_t>(p[0]) << 8) | p[1]);
}

static void put16(uint8_t *p, uint16_t v) {
    p[0] = static_cast<uint8_t>(v >> 8);
    p[1] = static_cast<uint8_t>(v & 0xFFu);
}

/* ------------------------------------------------------------------ */
/* Codec                                                               */
/* ------------------------------------------------------------------ */

bool modbusTcpHasCompleteAdu(const uint8_t *data, size_t len) {
    if (data == 0 || len < 7) {
        return false;
    }
    /* Los bytes 4..5 (longitud) cuentan UnitId + PDU. */
    const uint16_t length = be16(data + 4);
    if (length < 2) {
        return false; /* longitud invalida: se ignora */
    }
    const size_t total = static_cast<size_t>(6) + length;
    return len >= total;
}

/* Escribe una respuesta de excepcion. Devuelve el largo escrito. */
static size_t buildException(uint8_t *out, const uint8_t *request, uint8_t function,
                             uint8_t code) {
    out[0] = request[0]; /* transaction id hi */
    out[1] = request[1]; /* transaction id lo */
    out[2] = 0;          /* protocol id hi */
    out[3] = 0;          /* protocol id lo */
    out[4] = 0;
    out[5] = 3;          /* longitud: unit id + fc + code */
    out[6] = request[6]; /* unit id */
    out[7] = static_cast<uint8_t>(function | 0x80);
    out[8] = code;
    return 9;
}

/* Preambulo comun de una respuesta normal. Devuelve el offset del PDU. */
static size_t beginResponse(uint8_t *out, const uint8_t *request, uint8_t function,
                            uint8_t pdu_bytes) {
    out[0] = request[0];
    out[1] = request[1];
    out[2] = 0;
    out[3] = 0;
    const uint16_t length = static_cast<uint16_t>(1 + pdu_bytes); /* unit + pdu */
    put16(out + 4, length);
    out[6] = request[6];
    out[7] = function;
    return 8;
}
bool modbusTcpHandleRequest(const uint8_t *request, size_t request_len,
                            IModbusRegisterMap &map, uint8_t *response,
                            size_t &response_len) {
    response_len = 0;
    if (request == 0 || response == 0 || request_len < 8) {
        return false;
    }
    /* Protocolo siempre 0 en Modbus TCP. */
    if (request[2] != 0 || request[3] != 0) {
        return false;
    }
    const uint16_t length = be16(request + 4);
    if (length < 2 || static_cast<size_t>(6) + length > request_len) {
        return false;
    }

    const uint8_t function = request[7];
    const uint8_t *pdu = request + 8;          /* primer byte tras el codigo */
    const size_t pdu_len = static_cast<size_t>(length) - 1; /* sin unit id */

    switch (function) {
        case MODBUS_FC_READ_COILS:
        case MODBUS_FC_READ_DISCRETE_INPUTS: {
            if (pdu_len < 4) return false;
            const uint16_t start = be16(pdu);
            const uint16_t qty = be16(pdu + 2);
            if (qty < 1 || qty > 2000) {
                response_len = buildException(response, request, function,
                                              MODBUS_EX_ILLEGAL_DATA_VALUE);
                return true;
            }
            const uint16_t byte_count = static_cast<uint16_t>((qty + 7) / 8);
            const size_t off = beginResponse(response, request, function,
                                             static_cast<uint8_t>(byte_count + 2));
            response[off] = static_cast<uint8_t>(byte_count);
            uint8_t bits = 0;
            uint8_t bit_index = 0;
            size_t out_index = off + 1;
            for (uint16_t i = 0; i < qty; ++i) {
                bool value = false;
                if (!map.readCoil(static_cast<uint16_t>(start + i), value, map.ctx)) {
                    response_len = buildException(response, request, function,
                                                  MODBUS_EX_ILLEGAL_DATA_ADDRESS);
                    return true;
                }
                if (value) {
                    bits |= static_cast<uint8_t>(1u << bit_index);
                }
                ++bit_index;
                if (bit_index == 8) {
                    response[out_index++] = bits;
                    bits = 0;
                    bit_index = 0;
                }
            }
            if (bit_index != 0) {
                response[out_index++] = bits;
            }
            response_len = out_index;
            return true;
        }

        case MODBUS_FC_READ_HOLDING_REGISTERS:
        case MODBUS_FC_READ_INPUT_REGISTERS: {
            if (pdu_len < 4) return false;
            const uint16_t start = be16(pdu);
            const uint16_t qty = be16(pdu + 2);
            if (qty < 1 || qty > 125) {
                response_len = buildException(response, request, function,
                                              MODBUS_EX_ILLEGAL_DATA_VALUE);
                return true;
            }
            const uint16_t byte_count = static_cast<uint16_t>(qty * 2);
            const size_t off = beginResponse(response, request, function,
                                             static_cast<uint8_t>(byte_count + 1));
            response[off] = static_cast<uint8_t>(byte_count);
            size_t out_index = off + 1;
            for (uint16_t i = 0; i < qty; ++i) {
                uint16_t value = 0;
                if (!map.readRegister(static_cast<uint16_t>(start + i), value, map.ctx)) {
                    response_len = buildException(response, request, function,
                                                  MODBUS_EX_ILLEGAL_DATA_ADDRESS);
                    return true;
                }
                put16(response + out_index, value);
                out_index += 2;
            }
            response_len = out_index;
            return true;
        }

        case MODBUS_FC_WRITE_SINGLE_COIL: {
            if (pdu_len < 4) return false;
            const uint16_t address = be16(pdu);
            const uint16_t value = be16(pdu + 2);
            if (value != 0x0000 && value != 0xFF00) {
                response_len = buildException(response, request, function,
                                              MODBUS_EX_ILLEGAL_DATA_VALUE);
                return true;
            }
            if (!map.writeCoil(address, value == 0xFF00, map.ctx)) {
                response_len = buildException(response, request, function,
                                              MODBUS_EX_DEVICE_FAILURE);
                return true;
            }
            /* Eco exacto del request. */
            response_len = static_cast<size_t>(6) + length;
            memcpy(response, request, response_len);
            return true;
        }

        case MODBUS_FC_WRITE_SINGLE_REGISTER: {
            if (pdu_len < 4) return false;
            const uint16_t address = be16(pdu);
            const uint16_t value = be16(pdu + 2);
            if (!map.writeRegister(address, value, map.ctx)) {
                response_len = buildException(response, request, function,
                                              MODBUS_EX_DEVICE_FAILURE);
                return true;
            }
            response_len = static_cast<size_t>(6) + length;
            memcpy(response, request, response_len);
            return true;
        }

        case MODBUS_FC_WRITE_MULTIPLE_COILS: {
            if (pdu_len < 5) return false;
            const uint16_t start = be16(pdu);
            const uint16_t qty = be16(pdu + 2);
            const uint8_t byte_count = pdu[4];
            if (qty < 1 || qty > 1968 ||
                byte_count != static_cast<uint8_t>((qty + 7) / 8) ||
                pdu_len < static_cast<size_t>(5) + byte_count) {
                response_len = buildException(response, request, function,
                                              MODBUS_EX_ILLEGAL_DATA_VALUE);
                return true;
            }
            const uint8_t *bits = pdu + 5;
            for (uint16_t i = 0; i < qty; ++i) {
                const bool value = (bits[i / 8] & (1u << (i % 8))) != 0;
                if (!map.writeCoil(static_cast<uint16_t>(start + i), value, map.ctx)) {
                    response_len = buildException(response, request, function,
                                                  MODBUS_EX_DEVICE_FAILURE);
                    return true;
                }
            }
            const size_t off = beginResponse(response, request, function, 4);
            put16(response + off, start);
            put16(response + off + 2, qty);
            response_len = off + 4;
            return true;
        }

        case MODBUS_FC_WRITE_MULTIPLE_REGISTERS: {
            if (pdu_len < 5) return false;
            const uint16_t start = be16(pdu);
            const uint16_t qty = be16(pdu + 2);
            const uint8_t byte_count = pdu[4];
            if (qty < 1 || qty > 123 || byte_count != static_cast<uint8_t>(qty * 2) ||
                pdu_len < static_cast<size_t>(5) + byte_count) {
                response_len = buildException(response, request, function,
                                              MODBUS_EX_ILLEGAL_DATA_VALUE);
                return true;
            }
            const uint8_t *regs = pdu + 5;
            for (uint16_t i = 0; i < qty; ++i) {
                const uint16_t value = be16(regs + i * 2);
                if (!map.writeRegister(static_cast<uint16_t>(start + i), value, map.ctx)) {
                    response_len = buildException(response, request, function,
                                                  MODBUS_EX_DEVICE_FAILURE);
                    return true;
                }
            }
            const size_t off = beginResponse(response, request, function, 4);
            put16(response + off, start);
            put16(response + off + 2, qty);
            response_len = off + 4;
            return true;
        }

        default:
            response_len = buildException(response, request, function,
                                          MODBUS_EX_ILLEGAL_FUNCTION);
            return true;
    }
}

/* ------------------------------------------------------------------ */
/* Servidor                                                            */
/* ------------------------------------------------------------------ */

ModbusTcpServer::ModbusTcpServer(IModbusTcpStream &stream, IModbusRegisterMap &map)
    : stream_(stream), map_(map), unit_id_(kModbusTcpAnyUnit), buffered_(0),
      client_was_connected_(false) {
    resetBuffer();
}

bool ModbusTcpServer::begin() {
    return stream_.begin();
}

void ModbusTcpServer::resetBuffer() {
    memset(buffer_, 0, sizeof(buffer_));
    buffered_ = 0;
}

void ModbusTcpServer::poll() {
    const bool connected = stream_.clientConnected();

    if (!connected) {
        if (client_was_connected_) {
            resetBuffer(); /* nueva conexion limpia en el proximo ciclo */
        }
        client_was_connected_ = false;
        return;
    }

    if (!client_was_connected_) {
        resetBuffer();
    }
    client_was_connected_ = true;

    /* 1. Acumular bytes entrantes. */
    const size_t available = stream_.available();
    if (available > 0 && buffered_ < kModbusTcpBuffer) {
        const size_t space = kModbusTcpBuffer - buffered_;
        const size_t to_read = available < space ? available : space;
        buffered_ += stream_.read(buffer_ + buffered_, to_read);
    }

    /* 2. Procesar ADUs completos. */
    while (buffered_ >= 7) {
        const uint16_t length = be16(buffer_ + 4);
        if (length < 2) {
            resetBuffer(); /* cabecera corrupta */
            break;
        }
        const size_t adu_len = static_cast<size_t>(6) + length;
        if (buffered_ < adu_len) {
            break; /* esperar mas bytes */
        }

        uint8_t response[kModbusTcpBuffer];
        size_t response_len = 0;
        const uint8_t unit = buffer_[6];
        if (unit_id_ == kModbusTcpAnyUnit || unit == unit_id_) {
            modbusTcpHandleRequest(buffer_, adu_len, map_, response, response_len);
            if (response_len > 0) {
                stream_.write(response, response_len);
            }
        }

        /* Consumir el ADU procesado. */
        const size_t remaining = buffered_ - adu_len;
        if (remaining > 0) {
            memmove(buffer_, buffer_ + adu_len, remaining);
        }
        buffered_ = remaining;
    }
}

}  // namespace pcd#pragma once

/*
 * Servidor Modbus TCP (slave) agnostico a la red.
 *
 * Loxone Config integra hardware de terceros como maestro Modbus TCP: el
 * Miniserver abre una conexion TCP al puerto 502 del gateway y lee/escribe
 * coils y holding registers. Este modulo es la mitad que faltaba: el
 * `ModbusBridge` ya traduce coils/registers <-> CAN, pero solo define el
 * modelo de datos (`IModbusRegisterMap`); aqui vive el servidor que habla el
 * ADU Modbus TCP (MBAP + PDU) y responde a las consultas del maestro.
 *
 *   Loxone Config (maestro) --TCP:502--> ModbusTcpServer --IModbusRegisterMap-->
 *                                                                  ModbusBridge <-> CAN
 *
 * Como el resto de la libreria, no se acopla a ningun stack IP: la aplicacion
 * implementa `IModbusTcpStream` con su servidor TCP preferido (WiFiServer,
 * EthernetServer, AsyncTCP, sockets nativos...) y la pasa al servidor.
 */

#include <stddef.h>
#include <stdint.h>

#include "bridge/bridge.h" /* IModbusRegisterMap */

namespace pcd {

/* ------------------------------------------------------------------ */
/* Transporte de flujo TCP inyectable                                 */
/* ------------------------------------------------------------------ */

class IModbusTcpStream {
  public:
    virtual ~IModbusTcpStream() {}

    /* Inicia el servidor TCP. Devuelve false si no pudo escuchar. */
    virtual bool begin() = 0;

    /* true si hay un cliente conectado en este instante. */
    virtual bool clientConnected() = 0;

    /* Bytes pendientes de lectura del cliente conectado. */
    virtual size_t available() = 0;

    /* Lee hasta max_len bytes del cliente. Devuelve la cantidad leida. */
    virtual size_t read(uint8_t *data, size_t max_len) = 0;

    /* Escribe len bytes al cliente. Devuelve la cantidad escrita. */
    virtual size_t write(const uint8_t *data, size_t len) = 0;

    /* Cierra la conexion con el cliente actual. */
    virtual void stopClient() = 0;
};

/* ------------------------------------------------------------------ */
/* Constantes del protocolo                                            */
/* ------------------------------------------------------------------ */

static const uint16_t kModbusTcpDefaultPort = 502;

/* Tamano maximo de un ADU Modbus TCP: 7 (MBAP) + 253 (PDU). */
static const uint16_t kModbusTcpMaxAdu = 260;

/* Buffer interno del servidor (margen sobre el ADU maximo). */
static const uint16_t kModbusTcpBuffer = kModbusTcpMaxAdu + 8;

/* Unidad de direccionamiento (slave) por defecto: 0xFF = aceptar cualquiera. */
static const uint8_t kModbusTcpAnyUnit = 0xFF;

/* Codigos de funcion Modbus soportados. */
enum ModbusFunction : uint8_t {
    MODBUS_FC_READ_COILS = 0x01,
    MODBUS_FC_READ_DISCRETE_INPUTS = 0x02,
    MODBUS_FC_READ_HOLDING_REGISTERS = 0x03,
    MODBUS_FC_READ_INPUT_REGISTERS = 0x04,
    MODBUS_FC_WRITE_SINGLE_COIL = 0x05,
    MODBUS_FC_WRITE_SINGLE_REGISTER = 0x06,
    MODBUS_FC_WRITE_MULTIPLE_COILS = 0x0F,
    MODBUS_FC_WRITE_MULTIPLE_REGISTERS = 0x10
};

/* Codigos de excepcion Modbus. */
enum ModbusException : uint8_t {
    MODBUS_EX_ILLEGAL_FUNCTION = 0x01,
    MODBUS_EX_ILLEGAL_DATA_ADDRESS = 0x02,
    MODBUS_EX_ILLEGAL_DATA_VALUE = 0x03,
    MODBUS_EX_DEVICE_FAILURE = 0x04
};

/* ------------------------------------------------------------------ */
/* Codec del ADU Modbus TCP (funciones puras, testeables)              */
/* ------------------------------------------------------------------ */

/*
 * Parsea un request Modbus TCP completo y lo ejecuta contra `map`.
 *
 *   request      bytes recibidos (ADU completo, con cabecera MBAP)
 *   request_len  cantidad de bytes
 *   response     buffer de salida con el ADU de respuesta
 *   response_len cantidad de bytes escritos en response (salida)
 *
 * Devuelve true si se genero una respuesta (normal o de excepcion). Si el
 * request esta incompleto o malformado devuelve false y no escribe nada.
 */
bool modbusTcpHandleRequest(const uint8_t *request, size_t request_len,
                            IModbusRegisterMap &map, uint8_t *response,
                            size_t &response_len);

/*
 * true si `data` contiene al menos un ADU completo (cabecera MBAP de 7 bytes
 * cuya longitud coincide con lo disponible). Util para saber si el stream ya
 * acumulo un pedido entero.
 */
bool modbusTcpHasCompleteAdu(const uint8_t *data, size_t len);

/* ------------------------------------------------------------------ */
/* Servidor Modbus TCP                                                 */
/* ------------------------------------------------------------------ */

class ModbusTcpServer {
  public:
    ModbusTcpServer(IModbusTcpStream &stream, IModbusRegisterMap &map);

    /* Inicia el stream TCP. */
    bool begin();

    /*
     * Atiende una iteracion del servidor: acepta datos del cliente, procesa
     * pedidos completos y responde. Se llama desde el loop principal.
     */
    void poll();

    /* Restringe el slave/unit id aceptado (kModbusTcpAnyUnit = cualquiera). */
    void setUnitId(uint8_t unit_id) { unit_id_ = unit_id; }
    uint8_t unitId() const { return unit_id_; }

  private:
    void resetBuffer();

    IModbusTcpStream &stream_;
    IModbusRegisterMap &map_;
    uint8_t unit_id_;
    uint8_t buffer_[kModbusTcpBuffer];
    size_t buffered_;
    bool client_was_connected_;
};

}  // namespace pcd#include "routing/knx_group_map.h"

#include <string.h>

namespace pcd {

uint16_t knxGroupAddress(uint8_t main, uint8_t middle, uint8_t sub) {
    const uint16_t main_bits = static_cast<uint16_t>((main & 0x0F) << 11);
    const uint16_t middle_bits = static_cast<uint16_t>((middle & 0x07) << 8);
    return static_cast<uint16_t>(main_bits | middle_bits | sub);
}

bool knxSplitGroupAddress(uint16_t address, uint8_t &main, uint8_t &middle, uint8_t &sub) {
    main = static_cast<uint8_t>((address >> 11) & 0x0F);
    middle = static_cast<uint8_t>((address >> 8) & 0x07);
    sub = static_cast<uint8_t>(address & 0xFF);
    return true;
}

/* Escribe un entero sin signo en decimal dentro del buffer (sin stdio). */
static size_t writeDecimal(char *out, size_t out_len, uint16_t value) {
    char digits[6];
    uint8_t count = 0;
    if (value == 0) {
        digits[count++] = '0';
    }
    while (value > 0 && count < sizeof(digits)) {
        digits[count++] = static_cast<char>('0' + (value % 10));
        value = static_cast<uint16_t>(value / 10);
    }
    size_t written = 0;
    while (count > 0 && written + 1 < out_len) {
        out[written++] = digits[--count];
    }
    return written;
}

bool knxFormatGroupAddress(uint16_t address, char *out, size_t out_len) {
    if (out == 0 || out_len < 8) {
        return false;
    }
    uint8_t main = 0;
    uint8_t middle = 0;
    uint8_t sub = 0;
    knxSplitGroupAddress(address, main, middle, sub);

    size_t pos = writeDecimal(out, out_len, main);
    if (pos + 1 < out_len) {
        out[pos++] = '/';
    }
    pos += writeDecimal(&out[pos], out_len - pos, middle);
    if (pos + 1 < out_len) {
        out[pos++] = '/';
    }
    pos += writeDecimal(&out[pos], out_len - pos, sub);
    out[pos] = '\0';
    return true;
}

/* Lee un entero decimal y consume un separador si lo encuentra. */
static bool readDecimal(const char *&text, uint16_t &value) {
    if (text == 0) {
        return false;
    }
    uint32_t acc = 0;
    uint8_t digits = 0;
    while (*text >= '0' && *text <= '9' && digits < 5) {
        acc = acc * 10UL + static_cast<uint32_t>(*text - '0');
        ++text;
        ++digits;
    }
    if (digits == 0) {
        return false;
    }
    value = static_cast<uint16_t>(acc);
    if (*text == '/' || *text == '.' || *text == '-') {
        ++text;
    }
    return true;
}

bool knxParseGroupAddress(const char *text, uint16_t &address_out) {
    uint16_t main = 0;
    uint16_t middle = 0;
    uint16_t sub = 0;
    if (!readDecimal(text, main) || !readDecimal(text, middle) || !readDecimal(text, sub)) {
        return false;
    }
    if (main > 15 || middle > 7 || sub > 255) {
        return false;
    }
    address_out = knxGroupAddress(static_cast<uint8_t>(main), static_cast<uint8_t>(middle),
                                  static_cast<uint8_t>(sub));
    return true;
}

uint8_t knxDptSize(uint8_t dpt) {
    switch (dpt) {
        case KNX_DPT_BOOL:
        case KNX_DPT_SCALING:
        case KNX_DPT_VALUE_1:
        case KNX_DPT_SCENE:
            return 1;
        case KNX_DPT_VALUE_2:
        case KNX_DPT_VALUE_2F:
        case KNX_DPT_FLOAT_2:
            return 2;
        case KNX_DPT_VALUE_4:
        case KNX_DPT_FLOAT_4:
            return 4;
        default:
            return 0;
    }
}

const char *knxDptName(uint8_t dpt) {
    switch (dpt) {
        case KNX_DPT_BOOL: return "1.xxx bool";
        case KNX_DPT_SCALING: return "5.001 escalado";
        case KNX_DPT_VALUE_1: return "6.xxx entero 8";
        case KNX_DPT_VALUE_2: return "7.xxx entero 16";
        case KNX_DPT_VALUE_2F: return "8.xxx entero 16 con signo";
        case KNX_DPT_FLOAT_2: return "9.xxx float 2";
        case KNX_DPT_VALUE_4: return "12.xxx entero 32";
        case KNX_DPT_FLOAT_4: return "14.xxx float 4";
        case KNX_DPT_SCENE: return "17.001 escena";
        default: return "no soportado";
    }
}

/* DPT 9.xxx: 0,01 * mantisa(11 bits) * 2^exponente(4 bits con signo). */
static bool encodeDpt9(float value, uint8_t *out, size_t out_len, size_t &len_out) {
    if (out_len < 2) {
        return false;
    }
    float mantissa_units = value * 100.0f;
    int8_t exponent = 0;
    while ((mantissa_units > 2047.0f || mantissa_units < -2048.0f) && exponent < 15) {
        mantissa_units /= 2.0f;
        ++exponent;
    }
    while ((mantissa_units < 100.0f && mantissa_units > -100.0f) && exponent > -8) {
        mantissa_units *= 2.0f;
        --exponent;
    }
    const float rounded = mantissa_units >= 0.0f ? mantissa_units + 0.5f : mantissa_units - 0.5f;
    int16_t mantissa = static_cast<int16_t>(rounded);
    if (mantissa > 2047) {
        mantissa = 2047;
    }
    if (mantissa < -2048) {
        mantissa = -2048;
    }
    const uint8_t sign = mantissa < 0 ? 0x80 : 0x00;
    const uint16_t magnitude = static_cast<uint16_t>(mantissa < 0 ? -mantissa : mantissa);
    out[0] = static_cast<uint8_t>(sign | ((static_cast<uint8_t>(exponent) & 0x0F) << 3) |
                                  ((magnitude >> 8) & 0x07));
    out[1] = static_cast<uint8_t>(magnitude & 0xFF);
    len_out = 2;
    return true;
}

static bool decodeDpt9(const uint8_t *data, size_t len, float &value_out) {
    if (len < 2) {
        return false;
    }
    const bool negative = (data[0] & 0x80) != 0;
    int8_t exponent = static_cast<int8_t>((data[0] >> 3) & 0x0F);
    if ((exponent & 0x08) != 0) {
        exponent = static_cast<int8_t>(exponent | 0xF0); /* extiende el signo */
    }
    const uint16_t mantissa = static_cast<uint16_t>(((data[0] & 0x07) << 8) | data[1]);
    float value = 0.01f * static_cast<float>(mantissa);
    while (exponent > 0) {
        value *= 2.0f;
        --exponent;
    }
    while (exponent < 0) {
        value /= 2.0f;
        ++exponent;
    }
    value_out = negative ? -value : value;
    return true;
}

bool knxEncodeDpt(uint8_t dpt, float value, uint32_t scene_param, uint8_t *out, size_t out_len,
                  size_t &len_out) {
    if (out == 0) {
        return false;
    }
    switch (dpt) {
        case KNX_DPT_BOOL: {
            if (out_len < 1) return false;
            out[0] = value > 0.5f ? 1 : 0;
            len_out = 1;
            return true;
        }
        case KNX_DPT_SCALING: {
            if (out_len < 1) return false;
            float percent = value;
            if (percent < 0.0f) percent = 0.0f;
            if (percent > 100.0f) percent = 100.0f;
            out[0] = static_cast<uint8_t>((percent * 255.0f + 50.0f) / 100.0f);
            len_out = 1;
            return true;
        }
        case KNX_DPT_VALUE_1:
        case KNX_DPT_SCENE: {
            if (out_len < 1) return false;
            if (dpt == KNX_DPT_SCENE) {
                out[0] = static_cast<uint8_t>(scene_param & 0x3F);
            } else {
                int16_t v = static_cast<int16_t>(value >= 0.0f ? value + 0.5f : value - 0.5f);
                if (v > 127) v = 127;
                if (v < -128) v = -128;
                out[0] = static_cast<uint8_t>(v & 0xFF);
            }
            len_out = 1;
            return true;
        }
        case KNX_DPT_VALUE_2:
        case KNX_DPT_VALUE_2F: {
            if (out_len < 2) return false;
            int32_t v = static_cast<int32_t>(value >= 0.0f ? value + 0.5f : value - 0.5f);
            if (v > 32767) v = 32767;
            if (v < -32768) v = -32768;
            out[0] = static_cast<uint8_t>((v >> 8) & 0xFF);
            out[1] = static_cast<uint8_t>(v & 0xFF);
            len_out = 2;
            return true;
        }
        case KNX_DPT_FLOAT_2:
            return encodeDpt9(value, out, out_len, len_out);
        case KNX_DPT_VALUE_4: {
            if (out_len < 4) return false;
            const int32_t v = static_cast<int32_t>(value);
            out[0] = static_cast<uint8_t>((v >> 24) & 0xFF);
            out[1] = static_cast<uint8_t>((v >> 16) & 0xFF);
            out[2] = static_cast<uint8_t>((v >> 8) & 0xFF);
            out[3] = static_cast<uint8_t>(v & 0xFF);
            len_out = 4;
            return true;
        }
        case KNX_DPT_FLOAT_4: {
            if (out_len < 4) return false;
            uint32_t bits = 0;
            memcpy(&bits, &value, sizeof(bits));
            out[0] = static_cast<uint8_t>((bits >> 24) & 0xFF);
            out[1] = static_cast<uint8_t>((bits >> 16) & 0xFF);
            out[2] = static_cast<uint8_t>((bits >> 8) & 0xFF);
            out[3] = static_cast<uint8_t>(bits & 0xFF);
            len_out = 4;
            return true;
        }
        default:
            return false;
    }
}

bool knxDecodeDpt(uint8_t dpt, const uint8_t *data, size_t len, float &value_out,
                  uint32_t &param_out) {
    if (data == 0) {
        return false;
    }
    const uint8_t size = knxDptSize(dpt);
    if (size == 0 || len < size) {
        return false;
    }
    param_out = 0;
    switch (dpt) {
        case KNX_DPT_BOOL:
            value_out = data[0] & 0x01 ? 1.0f : 0.0f;
            return true;
        case KNX_DPT_SCALING:
            value_out = (static_cast<float>(data[0]) * 100.0f) / 255.0f;
            return true;
        case KNX_DPT_VALUE_1:
            value_out = static_cast<float>(static_cast<int8_t>(data[0]));
            return true;
        case KNX_DPT_SCENE:
            param_out = data[0] & 0x3F;
            value_out = static_cast<float>(param_out);
            return true;
        case KNX_DPT_VALUE_2:
            value_out = static_cast<float>((static_cast<uint16_t>(data[0]) << 8) | data[1]);
            return true;
        case KNX_DPT_VALUE_2F:
            value_out = static_cast<float>(static_cast<int16_t>((static_cast<uint16_t>(data[0])
                                                                 << 8) | data[1]));
            return true;
        case KNX_DPT_FLOAT_2:
            return decodeDpt9(data, len, value_out);
        case KNX_DPT_VALUE_4:
            value_out = static_cast<float>(static_cast<int32_t>(
                (static_cast<uint32_t>(data[0]) << 24) | (static_cast<uint32_t>(data[1]) << 16) |
                (static_cast<uint32_t>(data[2]) << 8) | static_cast<uint32_t>(data[3])));
            return true;
        case KNX_DPT_FLOAT_4: {
            const uint32_t bits = (static_cast<uint32_t>(data[0]) << 24) |
                                  (static_cast<uint32_t>(data[1]) << 16) |
                                  (static_cast<uint32_t>(data[2]) << 8) |
                                  static_cast<uint32_t>(data[3]);
            memcpy(&value_out, &bits, sizeof(value_out));
            return true;
        }
        default:
            return false;
    }
}

KnxGroupMap::KnxGroupMap() : count_(0) {
    clear();
}

void KnxGroupMap::clear() {
    count_ = 0;
}

bool KnxGroupMap::add(const KnxGroupMapping &mapping) {
    if (mapping.node_id == 0 || !isValidSource(mapping.node_id) ||
        knxDptSize(mapping.dpt) == 0) {
        return false;
    }
    if (findByGroup(mapping.group_address) != 0) {
        return false; /* una direccion de grupo solo puede mapearse una vez */
    }
    if (count_ >= CAN_MAX_KNX_MAPPINGS) {
        return false;
    }
    mappings_[count_++] = mapping;
    return true;
}

bool KnxGroupMap::remove(uint8_t index) {
    if (index >= count_) {
        return false;
    }
    for (uint8_t i = index + 1; i < count_; ++i) {
        mappings_[i - 1] = mappings_[i];
    }
    --count_;
    return true;
}

const KnxGroupMapping *KnxGroupMap::at(uint8_t index) const {
    return index < count_ ? &mappings_[index] : 0;
}

const KnxGroupMapping *KnxGroupMap::findByGroup(uint16_t group_address) const {
    for (uint8_t i = 0; i < count_; ++i) {
        if (mappings_[i].group_address == group_address) {
            return &mappings_[i];
        }
    }
    return 0;
}

const KnxGroupMapping *KnxGroupMap::findByTarget(uint16_t node_id, uint8_t resource,
                                                 uint8_t channel) const {
    for (uint8_t i = 0; i < count_; ++i) {
        const KnxGroupMapping &entry = mappings_[i];
        if (entry.node_id == node_id && entry.resource == resource && entry.channel == channel) {
            return &entry;
        }
    }
    return 0;
}

bool KnxGroupMap::toCanonical(uint16_t group_address, const uint8_t *data, size_t len,
                              CanonicalFrame &out) const {
    const KnxGroupMapping *mapping = findByGroup(group_address);
    if (mapping == 0) {
        return false;
    }
    float value = 0.0f;
    uint32_t param = 0;
    if (!knxDecodeDpt(mapping->dpt, data, len, value, param)) {
        return false;
    }
    out = CanonicalFrame();
    out.protocol = PROTO_KNX;
    out.source_id = group_address;
    out.resource = mapping->resource;
    out.channel = mapping->channel;
    out.value = value;
    if (mapping->dpt == KNX_DPT_SCENE) {
        out.is_command = 1;
        out.action = ACT_SCENE;
        out.param = param;
    } else if (mapping->dpt == KNX_DPT_BOOL) {
        out.is_command = 1;
        out.action = value > 0.5f ? ACT_ON : ACT_OFF;
    } else {
        out.is_command = 0;
    }
    return true;
}

bool KnxGroupMap::fromCanonical(const CanonicalFrame &frame, uint16_t &group_address_out,
                                uint8_t *data_out, size_t out_len, size_t &len_out,
                                uint8_t &dpt_out) const {
    const KnxGroupMapping *mapping = findByTarget(frame.source_id, frame.resource, frame.channel);
    if (mapping == 0) {
        return false;
    }
    const float value = frame.is_command ? static_cast<float>(frame.action) : frame.value;
    if (!knxEncodeDpt(mapping->dpt, value, frame.param, data_out, out_len, len_out)) {
        return false;
    }
    group_address_out = mapping->group_address;
    dpt_out = mapping->dpt;
    return true;
}

bool KnxGroupMap::serialize(uint8_t *out, uint16_t out_len) const {
    const uint16_t needed = static_cast<uint16_t>(3 + kKnxMappingBytes * count_);
    if (out == 0 || out_len < needed) {
        return false;
    }
    out[0] = kMagic;
    out[1] = kVersion;
    out[2] = count_;
    uint16_t offset = 3;
    for (uint8_t i = 0; i < count_; ++i) {
        const KnxGroupMapping &entry = mappings_[i];
        writeUint16BE(&out[offset], entry.group_address);
        out[offset + 2] = entry.dpt;
        writeUint16BE(&out[offset + 3], entry.node_id);
        out[offset + 5] = entry.resource;
        out[offset + 6] = entry.channel;
        out[offset + 7] = 0; /* reservado */
        offset = static_cast<uint16_t>(offset + kKnxMappingBytes);
    }
    return true;
}

bool KnxGroupMap::deserialize(const uint8_t *in, uint16_t in_len) {
    if (in == 0 || in_len < 3 || in[0] != kMagic || in[1] != kVersion) {
        return false;
    }
    const uint8_t stored = in[2];
    if (stored > CAN_MAX_KNX_MAPPINGS ||
        in_len < static_cast<uint16_t>(3 + kKnxMappingBytes * stored)) {
        return false;
    }
    count_ = 0;
    uint16_t offset = 3;
    for (uint8_t i = 0; i < stored; ++i) {
        KnxGroupMapping entry;
        entry.group_address = readUint16BE(&in[offset]);
        entry.dpt = in[offset + 2];
        entry.node_id = readUint16BE(&in[offset + 3]);
        entry.resource = in[offset + 5];
        entry.channel = in[offset + 6];
        if (knxDptSize(entry.dpt) != 0) {
            mappings_[count_++] = entry;
        }
        offset = static_cast<uint16_t>(offset + kKnxMappingBytes);
    }
    return true;
}

}  // namespace pcd#pragma once

/*
 * Extension KNX (puente de interoperabilidad).
 *
 * Traduce entre el modelo PCD (Node-ID, recurso, canal) y los objetos de grupo
 * KNX (una direccion de grupo de 16 bits mas un DPT). La capa fisica (TP1 con
 * NCN5120/TP-UART o KNXnet/IP por software) la aporta el proyecto: esta libreria
 * resuelve la tabla de mapeo, la codificacion de los DPT mas usados y su
 * persistencia, que es la parte que debe ser identica en cada instalacion.
 *
 * Ejemplo de la tabla:
 *
 *   grupo 1/1/5 (DPT 9.001) <-> Node-ID 0x0016, RES_ENV_SENSOR, canal 2
 *   grupo 1/1/10 (DPT 1.001) -> Node-ID 0x0016, RES_RELAY, canal 1
 *
 * DPT soportados: 1 (bool), 5 (escalado 0..100 %), 6 (entero 1 byte), 7
 * (entero 2 bytes), 8 (entero 2 bytes con signo), 9 (float 2 bytes), 12 (entero
 * 4 bytes), 14 (float 4 bytes) y 17 (escena). Cualquier otro DPT se rechaza de
 * forma explicita para que el proyecto lo implemente y documente.
 */

#include <stddef.h>
#include <stdint.h>

#include "routing/canonical.h"

namespace pcd {

#ifndef CAN_MAX_KNX_MAPPINGS
#define CAN_MAX_KNX_MAPPINGS 24
#endif

enum KnxDpt : uint8_t {
    KNX_DPT_NONE = 0,
    KNX_DPT_BOOL = 1,       /* 1.xxx  conmutacion (1 bit)                */
    KNX_DPT_SCALING = 5,    /* 5.001  porcentaje 0..100 % (1 byte)       */
    KNX_DPT_VALUE_1 = 6,    /* 6.xxx  entero 8 bits con signo            */
    KNX_DPT_VALUE_2 = 7,    /* 7.xxx  entero 16 bits                     */
    KNX_DPT_VALUE_2F = 8,   /* 8.xxx  entero 16 bits con signo           */
    KNX_DPT_FLOAT_2 = 9,    /* 9.xxx  float 2 bytes (temperatura, lux)   */
    KNX_DPT_VALUE_4 = 12,   /* 12.xxx entero 32 bits                     */
    KNX_DPT_FLOAT_4 = 14,   /* 14.xxx float 4 bytes                      */
    KNX_DPT_SCENE = 17      /* 17.001 numero de escena                   */
};

/* ------------------------------------------------------------------ */
/* Direcciones de grupo                                                 */
/* ------------------------------------------------------------------ */

/* Direccion de 3 niveles: principal (0..15), intermedio (0..7), sub (0..255). */
uint16_t knxGroupAddress(uint8_t main, uint8_t middle, uint8_t sub);
bool knxSplitGroupAddress(uint16_t address, uint8_t &main, uint8_t &middle, uint8_t &sub);

/* Escritura "1/1/5" en un buffer del llamador (sin stdio). */
bool knxFormatGroupAddress(uint16_t address, char *out, size_t out_len);
bool knxParseGroupAddress(const char *text, uint16_t &address_out);

/* ------------------------------------------------------------------ */
/* DPT                                                                  */
/* ------------------------------------------------------------------ */

/* Tamano en bytes de un DPT soportado; 0 si no se soporta. */
uint8_t knxDptSize(uint8_t dpt);

/* Valor numerico -> bytes KNX. Devuelve false si el DPT no se soporta. */
bool knxEncodeDpt(uint8_t dpt, float value, uint32_t scene_param, uint8_t *out, size_t out_len,
                  size_t &len_out);

/* Bytes KNX -> valor numerico. */
bool knxDecodeDpt(uint8_t dpt, const uint8_t *data, size_t len, float &value_out,
                  uint32_t &param_out);

const char *knxDptName(uint8_t dpt);

/* ------------------------------------------------------------------ */
/* Tabla de mapeo de objetos de grupo                                   */
/* ------------------------------------------------------------------ */

struct KnxGroupMapping {
    uint16_t group_address;
    uint8_t dpt;
    uint16_t node_id;
    uint8_t resource;
    uint8_t channel;

    KnxGroupMapping()
        : group_address(0),
          dpt(KNX_DPT_BOOL),
          node_id(0),
          resource(0),
          channel(0) {}
};

static const uint8_t kKnxMappingBytes = 8;

class KnxGroupMap {
  public:
    KnxGroupMap();

    bool add(const KnxGroupMapping &mapping);
    bool remove(uint8_t index);
    void clear();

    uint8_t count() const { return count_; }
    const KnxGroupMapping *at(uint8_t index) const;

    const KnxGroupMapping *findByGroup(uint16_t group_address) const;
    const KnxGroupMapping *findByTarget(uint16_t node_id, uint8_t resource,
                                        uint8_t channel) const;

    /* Telegrama KNX -> canonico (entrada al bus PCD). */
    bool toCanonical(uint16_t group_address, const uint8_t *data, size_t len,
                     CanonicalFrame &out) const;

    /* Estado canonico -> telegrama KNX (salida del bus PCD). */
    bool fromCanonical(const CanonicalFrame &frame, uint16_t &group_address_out, uint8_t *data_out,
                       size_t out_len, size_t &len_out, uint8_t &dpt_out) const;

    /* Persistencia binaria: magia + version + cantidad + entradas de 8 bytes. */
    bool serialize(uint8_t *out, uint16_t out_len) const;
    bool deserialize(const uint8_t *in, uint16_t in_len);

    static const uint8_t kMagic = 0xB7;
    static const uint8_t kVersion = 1;

  private:
    KnxGroupMapping mappings_[CAN_MAX_KNX_MAPPINGS];
    uint8_t count_;
};

}  // namespace pcd#include "security/hmac_authenticator.h"

#include <string.h>

#include "security/sha256.h"

namespace pcd {

static const size_t kBlockBytes = kSha256BlockBytes; /* 64 */

HmacAuthenticator::HmacAuthenticator(const uint8_t *key, size_t key_len, size_t tag_len)
    : key_len_(0), tag_len_(kHmacDefaultTagBytes) {
    memset(key_, 0, sizeof(key_));
    if (tag_len < kHmacMinTagBytes || tag_len > kHmacFullTagBytes) {
        tag_len_ = kHmacDefaultTagBytes;
    } else {
        tag_len_ = tag_len;
    }
    if (key == 0 || key_len == 0) {
        return;
    }
    if (key_len > kBlockBytes) {
        /* RFC 2104: claves largas se reemplazan por su digest. */
        Sha256::hash(key, key_len, key_);
        key_len_ = kSha256DigestBytes;
        return;
    }
    memcpy(key_, key, key_len);
    key_len_ = key_len;
}

void HmacAuthenticator::computeFull(const uint8_t *data, size_t len,
                                    uint8_t out[kHmacFullTagBytes]) const {
    uint8_t key_block[kBlockBytes];
    memset(key_block, 0, sizeof(key_block));
    memcpy(key_block, key_, key_len_);

    uint8_t inner_pad[kBlockBytes];
    uint8_t outer_pad[kBlockBytes];
    for (size_t i = 0; i < kBlockBytes; ++i) {
        inner_pad[i] = static_cast<uint8_t>(key_block[i] ^ 0x36);
        outer_pad[i] = static_cast<uint8_t>(key_block[i] ^ 0x5C);
    }

    uint8_t inner_digest[kSha256DigestBytes];
    Sha256 inner;
    inner.begin();
    inner.update(inner_pad, sizeof(inner_pad));
    inner.update(data, len);
    inner.final(inner_digest);

    Sha256 outer;
    outer.begin();
    outer.update(outer_pad, sizeof(outer_pad));
    outer.update(inner_digest, sizeof(inner_digest));
    outer.final(out);
}

bool HmacAuthenticator::sign(const uint8_t *data, size_t len, uint8_t *tag, size_t tag_len) {
    if (tag == 0 || tag_len != tag_len_ || !ready()) {
        return false;
    }
    uint8_t full[kHmacFullTagBytes];
    computeFull(data, len, full);
    memcpy(tag, full, tag_len);
    memset(full, 0, sizeof(full));
    return true;
}

bool HmacAuthenticator::verify(const uint8_t *data, size_t len, const uint8_t *tag,
                               size_t tag_len) {
    if (tag == 0 || tag_len != tag_len_ || !ready()) {
        return false;
    }
    uint8_t full[kHmacFullTagBytes];
    computeFull(data, len, full);
    const bool ok = constantTimeEquals(full, tag, tag_len);
    memset(full, 0, sizeof(full));
    return ok;
}

bool HmacAuthenticator::constantTimeEquals(const uint8_t *a, const uint8_t *b, size_t len) {
    if (a == 0 || b == 0) {
        return false;
    }
    uint8_t diff = 0;
    for (size_t i = 0; i < len; ++i) {
        diff = static_cast<uint8_t>(diff | (a[i] ^ b[i]));
    }
    return diff == 0;
}

size_t HmacAuthenticator::signDatagram(const uint8_t *datagram, size_t len, uint8_t *out,
                                       size_t out_len) const {
    if (datagram == 0 || out == 0 || len == 0 || !ready() || out_len < len + tag_len_) {
        return 0;
    }
    uint8_t full[kHmacFullTagBytes];
    computeFull(datagram, len, full);
    memcpy(out, datagram, len);
    memcpy(&out[len], full, tag_len_);
    memset(full, 0, sizeof(full));
    return len + tag_len_;
}

bool HmacAuthenticator::verifyDatagram(const uint8_t *in, size_t len,
                                       size_t &datagram_len) const {
    if (in == 0 || !ready() || len <= tag_len_) {
        return false;
    }
    const size_t payload_len = len - tag_len_;
    uint8_t full[kHmacFullTagBytes];
    computeFull(in, payload_len, full);
    const bool ok = constantTimeEquals(full, &in[payload_len], tag_len_);
    memset(full, 0, sizeof(full));
    if (ok) {
        datagram_len = payload_len;
    }
    return ok;
}

}  // namespace pcd#pragma once

/*
 * Autenticacion HMAC-SHA256 de datagramas de tunel CAN-sobre-IP.
 *
 * Implementa el contrato `ITunnelAuthenticator` que consume la aplicacion del
 * gateway, de modo que el tunel pueda dejar de ser "confianza ciega en la LAN"
 * y pasar a exigir un tag de integridad por datagrama. Tambien sirve para
 * firmar comandos SDO de configuracion y campanas OTA.
 *
 *   tag = HMAC-SHA256(clave, datagrama)[0..tag_len)
 *
 * Detalles de diseno:
 *
 *   - la clave se normaliza al construirse: si supera 64 bytes se reemplaza por
 *     su SHA-256 (regla de RFC 2104),
 *   - el tag se compara en tiempo constante para no filtrar informacion,
 *   - el truncamiento recomendado es de 16 bytes (128 bits); se admiten 8..32,
 *   - la clave nunca se copia a memoria no volatil por la libreria.
 *
 * La implementacion se valida con los vectores oficiales de RFC 4231 en
 * `test/test_security`.
 */

#include <stddef.h>
#include <stdint.h>

#include "tunnel/tunnel_transport.h"

namespace pcd {

#ifndef CAN_HMAC_KEY_BYTES
#define CAN_HMAC_KEY_BYTES 64
#endif

static const size_t kHmacMinTagBytes = 8;
static const size_t kHmacFullTagBytes = 32;
static const size_t kHmacDefaultTagBytes = 16;

class HmacAuthenticator : public ITunnelAuthenticator {
  public:
    /*
     * key/key_len: secreto compartido (no se guarda en claro mas alla de la
     * instancia). tag_len: 8..32; valores fuera de rango se ajustan al default.
     */
    HmacAuthenticator(const uint8_t *key, size_t key_len,
                      size_t tag_len = kHmacDefaultTagBytes);

    /* ITunnelAuthenticator: firma/verifica un bloque de bytes. */
    bool sign(const uint8_t *data, size_t len, uint8_t *tag, size_t tag_len) override;
    bool verify(const uint8_t *data, size_t len, const uint8_t *tag, size_t tag_len) override;

    /* HMAC completo de 32 bytes. */
    void computeFull(const uint8_t *data, size_t len, uint8_t out[kHmacFullTagBytes]) const;

    /*
     * Variante para datagramas de tunel: firma los len bytes y escribe el
     * datagrama original seguido del tag en out. Devuelve los bytes escritos
     * (0 si no cabe en out_len).
     */
    size_t signDatagram(const uint8_t *datagram, size_t len, uint8_t *out,
                        size_t out_len) const;

    /*
     * Verifica un datagrama extendido. Si el tag es valido devuelve true y
     * `datagram_len` recibe el tamano del datagrama original (len - tag_len).
     */
    bool verifyDatagram(const uint8_t *in, size_t len, size_t &datagram_len) const;

    size_t tagBytes() const { return tag_len_; }
    size_t keyBytes() const { return key_len_; }
    bool ready() const { return key_len_ > 0; }

    /* Comparacion en tiempo constante. */
    static bool constantTimeEquals(const uint8_t *a, const uint8_t *b, size_t len);

  private:
    uint8_t key_[CAN_HMAC_KEY_BYTES];
    size_t key_len_;
    size_t tag_len_;
};

}  // namespace pcd#include "security/sha256.h"

#include <string.h>

namespace pcd {

namespace {

/* Constantes de ronda de SHA-256 (FIPS 180-4, seccion 4.2.2). */
const uint32_t kRoundConstants[64] = {
    0x428a2f98UL, 0x71374491UL, 0xb5c0fbcfUL, 0xe9b5dba5UL, 0x3956c25bUL, 0x59f111f1UL,
    0x923f82a4UL, 0xab1c5ed5UL, 0xd807aa98UL, 0x12835b01UL, 0x243185beUL, 0x550c7dc3UL,
    0x72be5d74UL, 0x80deb1feUL, 0x9bdc06a7UL, 0xc19bf174UL, 0xe49b69c1UL, 0xefbe4786UL,
    0x0fc19dc6UL, 0x240ca1ccUL, 0x2de92c6fUL, 0x4a7484aaUL, 0x5cb0a9dcUL, 0x76f988daUL,
    0x983e5152UL, 0xa831c66dUL, 0xb00327c8UL, 0xbf597fc7UL, 0xc6e00bf3UL, 0xd5a79147UL,
    0x06ca6351UL, 0x14292967UL, 0x27b70a85UL, 0x2e1b2138UL, 0x4d2c6dfcUL, 0x53380d13UL,
    0x650a7354UL, 0x766a0abbUL, 0x81c2c92eUL, 0x92722c85UL, 0xa2bfe8a1UL, 0xa81a664bUL,
    0xc24b8b70UL, 0xc76c51a3UL, 0xd192e819UL, 0xd6990624UL, 0xf40e3585UL, 0x106aa070UL,
    0x19a4c116UL, 0x1e376c08UL, 0x2748774cUL, 0x34b0bcb5UL, 0x391c0cb3UL, 0x4ed8aa4aUL,
    0x5b9cca4fUL, 0x682e6ff3UL, 0x748f82eeUL, 0x78a5636fUL, 0x84c87814UL, 0x8cc70208UL,
    0x90befffaUL, 0xa4506cebUL, 0xbef9a3f7UL, 0xc67178f2UL};

const uint32_t kInitialState[8] = {0x6a09e667UL, 0xbb67ae85UL, 0x3c6ef372UL, 0xa54ff53aUL,
                                   0x510e527fUL, 0x9b05688cUL, 0x1f83d9abUL, 0x5be0cd19UL};

inline uint32_t rotr(uint32_t value, uint8_t bits) {
    return (value >> bits) | (value << (32U - bits));
}

}  // namespace

Sha256::Sha256() : bit_length_(0), buffer_len_(0) {
    memcpy(state_, kInitialState, sizeof(state_));
    memset(buffer_, 0, sizeof(buffer_));
}

void Sha256::begin() {
    memcpy(state_, kInitialState, sizeof(state_));
    bit_length_ = 0;
    buffer_len_ = 0;
    memset(buffer_, 0, sizeof(buffer_));
}

void Sha256::transform(const uint8_t block[kSha256BlockBytes]) {
    uint32_t w[64];
    for (uint8_t i = 0; i < 16; ++i) {
        w[i] = (static_cast<uint32_t>(block[i * 4]) << 24) |
               (static_cast<uint32_t>(block[i * 4 + 1]) << 16) |
               (static_cast<uint32_t>(block[i * 4 + 2]) << 8) |
               static_cast<uint32_t>(block[i * 4 + 3]);
    }
    for (uint8_t i = 16; i < 64; ++i) {
        const uint32_t s0 = rotr(w[i - 15], 7) ^ rotr(w[i - 15], 18) ^ (w[i - 15] >> 3);
        const uint32_t s1 = rotr(w[i - 2], 17) ^ rotr(w[i - 2], 19) ^ (w[i - 2] >> 10);
        w[i] = w[i - 16] + s0 + w[i - 7] + s1;
    }

    uint32_t a = state_[0];
    uint32_t b = state_[1];
    uint32_t c = state_[2];
    uint32_t d = state_[3];
    uint32_t e = state_[4];
    uint32_t f = state_[5];
    uint32_t g = state_[6];
    uint32_t h = state_[7];

    for (uint8_t i = 0; i < 64; ++i) {
        const uint32_t s1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
        const uint32_t ch = (e & f) ^ (~e & g);
        const uint32_t temp1 = h + s1 + ch + kRoundConstants[i] + w[i];
        const uint32_t s0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
        const uint32_t maj = (a & b) ^ (a & c) ^ (b & c);
        const uint32_t temp2 = s0 + maj;

        h = g;
        g = f;
        f = e;
        e = d + temp1;
        d = c;
        c = b;
        b = a;
        a = temp1 + temp2;
    }

    state_[0] += a;
    state_[1] += b;
    state_[2] += c;
    state_[3] += d;
    state_[4] += e;
    state_[5] += f;
    state_[6] += g;
    state_[7] += h;
}

void Sha256::absorb(const uint8_t *data, size_t len) {
    while (len > 0) {
        const size_t free_bytes = kSha256BlockBytes - buffer_len_;
        const size_t take = len < free_bytes ? len : free_bytes;
        memcpy(&buffer_[buffer_len_], data, take);
        buffer_len_ += take;
        data += take;
        len -= take;
        if (buffer_len_ == kSha256BlockBytes) {
            transform(buffer_);
            buffer_len_ = 0;
        }
    }
}

void Sha256::update(const uint8_t *data, size_t len) {
    if (data == 0 || len == 0) {
        return;
    }
    bit_length_ += static_cast<uint64_t>(len) * 8ULL;
    absorb(data, len);
}

void Sha256::final(uint8_t digest[kSha256DigestBytes]) {
    const uint64_t total_bits = bit_length_;

    /* 0x80, ceros y la longitud en bits en big-endian (FIPS 180-4, 5.1.1). */
    uint8_t padding[kSha256BlockBytes];
    memset(padding, 0, sizeof(padding));
    padding[0] = 0x80;

    const size_t remainder = static_cast<size_t>(buffer_len_);
    const size_t padding_len = (remainder < 56) ? (56 - remainder) : (120 - remainder);
    absorb(padding, padding_len);

    uint8_t length_bytes[8];
    for (uint8_t i = 0; i < 8; ++i) {
        length_bytes[i] = static_cast<uint8_t>((total_bits >> (56 - i * 8)) & 0xFF);
    }
    absorb(length_bytes, sizeof(length_bytes));

    bit_length_ = total_bits;
    if (digest == 0) {
        return;
    }
    for (uint8_t i = 0; i < 8; ++i) {
        digest[i * 4] = static_cast<uint8_t>((state_[i] >> 24) & 0xFF);
        digest[i * 4 + 1] = static_cast<uint8_t>((state_[i] >> 16) & 0xFF);
        digest[i * 4 + 2] = static_cast<uint8_t>((state_[i] >> 8) & 0xFF);
        digest[i * 4 + 3] = static_cast<uint8_t>(state_[i] & 0xFF);
    }
}

void Sha256::hash(const uint8_t *data, size_t len, uint8_t digest[kSha256DigestBytes]) {
    Sha256 context;
    context.begin();
    context.update(data, len);
    context.final(digest);
}

}  // namespace pcd#pragma once

/*
 * SHA-256 propio (FIPS 180-4), sin dependencias externas.
 *
 * La libreria no incluye ningun stack criptografico de terceros: si el proyecto
 * necesita autenticar el tunel CAN-sobre-IP o firmar comandos de configuracion,
 * puede usar esta implementacion (o inyectar la suya a traves del contrato
 * ITunnelAuthenticator). El tamano del digest y de los bloques es el estandar:
 *
 *   digests:  32 bytes
 *   bloque:  64 bytes
 *
 * La implementacion se valida con los vectores oficiales de FIPS 180-4 y de
 * RFC 4231 en `test/test_security`.
 */

#include <stddef.h>
#include <stdint.h>

namespace pcd {

static const size_t kSha256DigestBytes = 32;
static const size_t kSha256BlockBytes = 64;

class Sha256 {
  public:
    Sha256();

    /* Reinicia el estado para una nueva operacion. */
    void begin();
    void update(const uint8_t *data, size_t len);
    void final(uint8_t digest[kSha256DigestBytes]);

    /* Utilidad de una sola pasada. */
    static void hash(const uint8_t *data, size_t len, uint8_t digest[kSha256DigestBytes]);

  private:
    void absorb(const uint8_t *data, size_t len); /* no modifica bit_length_ */
    void transform(const uint8_t block[kSha256BlockBytes]);

    uint32_t state_[8];
    uint64_t bit_length_;
    uint8_t buffer_[kSha256BlockBytes];
    size_t buffer_len_;
};

}  // namespace pcd#include "topology/bus_profile.h"

namespace pcd {

namespace {

const BusProfile kProfiles[] = {
    /* name                              topologia            bitrate  stub totalStub length term hub   rec */
    {"lineal-1m",                       BUS_TOPOLOGY_LINEAR, 1000000, 10,  100,       25,   2, false, true},
    {"lineal-500k",                     BUS_TOPOLOGY_LINEAR, 500000,  30,  300,      100,   2, false, true},
    {"lineal-250k",                     BUS_TOPOLOGY_LINEAR, 250000,  60,  600,      250,   2, false, true},
    {"lineal-125k",                     BUS_TOPOLOGY_LINEAR, 125000, 120, 1200,      500,   2, false, true},
    {"lineal-50k",                      BUS_TOPOLOGY_LINEAR,  50000, 300, 3000,     1000,   2, false, true},
    {"estrella-hub-125k",               BUS_TOPOLOGY_STAR,   125000,  60,  600,      100,   2, true,  true},
    {"estrella-hub-50k",                BUS_TOPOLOGY_STAR,    50000, 150, 1500,      250,   2, true,  true},
    {"arbol-hub-50k",                   BUS_TOPOLOGY_TREE,    50000, 150, 1500,      500,   2, true,  true},
    {"estrella-sin-terminacion-50k",    BUS_TOPOLOGY_STAR,    50000,  50,  500,      100,   0, false, false},
    {"arbol-sin-terminacion-50k",       BUS_TOPOLOGY_TREE,    50000,  50,  500,      100,   0, false, false}
};

const uint8_t kProfileCount = static_cast<uint8_t>(sizeof(kProfiles) / sizeof(kProfiles[0]));

}  // namespace

uint8_t busProfileCount() {
    return kProfileCount;
}

const BusProfile *busProfileAt(uint8_t index) {
    return index < kProfileCount ? &kProfiles[index] : 0;
}

const BusProfile *findBusProfile(BusTopology topology, uint32_t bitrate) {
    const BusProfile *fallback = 0;
    for (uint8_t i = 0; i < kProfileCount; ++i) {
        const BusProfile &profile = kProfiles[i];
        if (profile.topology != topology) {
            continue;
        }
        if (profile.bitrate == bitrate && profile.recommended) {
            return &profile;
        }
        if (fallback == 0 && profile.bitrate == bitrate) {
            fallback = &profile;
        }
    }
    return fallback;
}

const BusProfile *recommendedProfile(BusTopology topology) {
    const BusProfile *best = 0;
    for (uint8_t i = 0; i < kProfileCount; ++i) {
        const BusProfile &profile = kProfiles[i];
        if (profile.topology != topology || !profile.recommended) {
            continue;
        }
        if (best == 0 || profile.bitrate > best->bitrate) {
            best = &profile;
        }
    }
    return best;
}

bool topologySupports(BusTopology topology, uint32_t bitrate) {
    return findBusProfile(topology, bitrate) != 0;
}

uint16_t maxStubCm(BusTopology topology, uint32_t bitrate) {
    const BusProfile *profile = findBusProfile(topology, bitrate);
    return profile == 0 ? 0 : profile->max_stub_cm;
}

bool topologyRequiresHub(BusTopology topology) {
    const BusProfile *profile = findBusProfile(topology, 125000);
    if (profile != 0) {
        return profile->requires_hub;
    }
    profile = findBusProfile(topology, 50000);
    return profile == 0 ? false : profile->requires_hub;
}

const char *topologyName(BusTopology topology) {
    switch (topology) {
        case BUS_TOPOLOGY_LINEAR: return "lineal";
        case BUS_TOPOLOGY_STAR: return "estrella";
        case BUS_TOPOLOGY_TREE: return "arbol";
        default: return "desconocida";
    }
}

BusWiringIssue validateWiring(BusTopology topology, uint32_t bitrate, uint32_t stub_cm,
                              uint32_t total_stub_cm, uint32_t length_m, uint8_t terminations,
                              bool has_hub) {
    const BusProfile *profile = findBusProfile(topology, bitrate);
    if (profile == 0) {
        return BUS_WIRING_UNKNOWN_PROFILE;
    }
    if (profile->requires_hub && !has_hub) {
        return BUS_WIRING_MISSING_HUB;
    }
    if (terminations != profile->terminations) {
        return BUS_WIRING_BAD_TERMINATION;
    }
    if (stub_cm > profile->max_stub_cm) {
        return BUS_WIRING_STUB_TOO_LONG;
    }
    if (total_stub_cm > profile->max_total_stub_cm) {
        return BUS_WIRING_TOTAL_STUB_TOO_LONG;
    }
    if (length_m > profile->max_length_m) {
        return BUS_WIRING_TOO_LONG;
    }
    return BUS_WIRING_OK;
}

const char *wiringIssueName(BusWiringIssue issue) {
    switch (issue) {
        case BUS_WIRING_OK: return "ok";
        case BUS_WIRING_UNKNOWN_PROFILE: return "perfil desconocido";
        case BUS_WIRING_STUB_TOO_LONG: return "derivacion demasiado larga";
        case BUS_WIRING_TOTAL_STUB_TOO_LONG: return "suma de derivaciones excesiva";
        case BUS_WIRING_TOO_LONG: return "tramo demasiado largo";
        case BUS_WIRING_MISSING_HUB: return "falta el hub/star coupler";
        case BUS_WIRING_BAD_TERMINATION: return "terminacion incorrecta";
        default: return "desconocido";
    }
}

}  // namespace pcd#pragma once

/*
 * Perfiles de capa fisica CAN por topologia.
 *
 * El CAN clasico (ISO 11898-2) exige bus lineal con dos terminaciones de
 * 120 ohm en los extremos. Una topologia en estrella o en arbol no se resuelve
 * cambiando el controlador: se resuelve aislando cada rama con su propio
 * transceptor (star coupler / repetidor de capa fisica) y bajando la velocidad.
 *
 * Este modulo concentra los numeros de instalacion (derivacion maxima, longitud,
 * terminaciones, necesidad de hub) para que el firmware pueda:
 *
 *   - elegir la velocidad del bus segun la topologia del proyecto,
 *   - validar el cableado declarado por el instalador antes de energizar,
 *   - documentar por que una rama no terminada solo es segura a baja velocidad.
 *
 * Los valores de `max_stub_cm` son deliberadamente conservadores (peor caso de
 * reflexion con transceptores economicos). El fabricante del transceptor o del
 * cable puede permitir derivaciones mas largas; la wiki 10 reproduce ambas
 * tablas y explica el criterio.
 */

#include <stdint.h>

namespace pcd {

enum BusTopology : uint8_t {
    BUS_TOPOLOGY_LINEAR = 0,  /* tronco unico, terminado en los dos extremos     */
    BUS_TOPOLOGY_STAR = 1,    /* varias ramas cortas sobre un star coupler       */
    BUS_TOPOLOGY_TREE = 2     /* ramas y sub-ramas sobre un hub repetidor        */
};

struct BusProfile {
    const char *name;
    BusTopology topology;
    uint32_t bitrate;             /* bits por segundo                          */
    uint16_t max_stub_cm;         /* derivacion maxima por nodo, en cm         */
    uint32_t max_total_stub_cm;   /* suma de todas las derivaciones, en cm     */
    uint32_t max_length_m;        /* longitud maxima del tramo o de la rama    */
    uint8_t terminations;         /* 120 ohm requeridas por rama               */
    bool requires_hub;            /* true si exige star coupler/repetidor      */
    bool recommended;             /* false: posible pero fuera de lo prudente  */
};

/* Tabla de perfiles incluida en la libreria. */
uint8_t busProfileCount();
const BusProfile *busProfileAt(uint8_t index);

/* Perfil exacto para la combinacion pedida (0 si no existe). */
const BusProfile *findBusProfile(BusTopology topology, uint32_t bitrate);

/* Perfil recomendado mas rapido de una topologia (0 si no hay). */
const BusProfile *recommendedProfile(BusTopology topology);

/* true si la combinacion topologia + velocidad esta soportada. */
bool topologySupports(BusTopology topology, uint32_t bitrate);

/* Derivacion maxima (cm) para la combinacion; 0 si no esta soportada. */
uint16_t maxStubCm(BusTopology topology, uint32_t bitrate);

/* true si la topologia exige un hub/star coupler con un transceptor por rama. */
bool topologyRequiresHub(BusTopology topology);

const char *topologyName(BusTopology topology);

/* ------------------------------------------------------------------ */
/* Validador de instalacion                                             */
/* ------------------------------------------------------------------ */

enum BusWiringIssue : uint8_t {
    BUS_WIRING_OK = 0,
    BUS_WIRING_UNKNOWN_PROFILE,
    BUS_WIRING_STUB_TOO_LONG,
    BUS_WIRING_TOTAL_STUB_TOO_LONG,
    BUS_WIRING_TOO_LONG,
    BUS_WIRING_MISSING_HUB,
    BUS_WIRING_BAD_TERMINATION
};

/*
 * Valida el cableado declarado:
 *
 *   stub_cm        derivacion mas larga de la rama
 *   total_stub_cm  suma de todas las derivaciones de la rama
 *   length_m       longitud del tramo (lineal) o de la rama (estrella/arbol)
 *   terminations   resistencias de 120 ohm presentes en la rama
 *   has_hub        true si la rama cuelga de un star coupler
 */
BusWiringIssue validateWiring(BusTopology topology, uint32_t bitrate, uint32_t stub_cm,
                              uint32_t total_stub_cm, uint32_t length_m, uint8_t terminations,
                              bool has_hub);

const char *wiringIssueName(BusWiringIssue issue);

}  // namespace pcd#include "topology/can_tree_hub.h"

#include <string.h>

namespace pcd {

CanTreeHub::CanTreeHub(uint32_t bitrate)
    : port_count_(0),
      learn_next_(0),
      dedupe_next_(0),
      bitrate_(bitrate),
      dedupe_ms_(kHubDefaultDedupeMs),
      route_mode_(HUB_ROUTE_LEARNED),
      forwarded_(0),
      dropped_(0),
      loops_(0),
      started_(false) {
    clear();
}

CanTreeHub::~CanTreeHub() {}

void CanTreeHub::clear() {
    port_count_ = 0;
    forwarded_ = 0;
    dropped_ = 0;
    loops_ = 0;
    learn_next_ = 0;
    dedupe_next_ = 0;
    memset(buses_, 0, sizeof(buses_));
    memset(ports_, 0, sizeof(ports_));
    memset(learned_, 0, sizeof(learned_));
    memset(dedupe_, 0, sizeof(dedupe_));
}

bool CanTreeHub::addPort(ICanBus &bus, uint8_t segment) {
    if (port_count_ >= CAN_HUB_MAX_PORTS) {
        return false;
    }
    CanHubPort &entry = ports_[port_count_];
    entry.bus = &bus;
    entry.segment = segment;
    entry.stats.received = 0;
    entry.stats.forwarded = 0;
    entry.stats.dropped = 0;
    entry.stats.errors = 0;
    buses_[port_count_] = &bus;
    ++port_count_;
    return true;
}

bool CanTreeHub::begin(uint32_t bitrate) {
    const uint32_t rate = bitrate == 0 ? bitrate_ : bitrate;
    for (uint8_t i = 0; i < port_count_; ++i) {
        if (ports_[i].bus->begin(rate) != CAN_OK) {
            return false;
        }
        ports_[i].bus->setFilter(CanFilter::acceptAll());
    }
    started_ = port_count_ > 0;
    return started_;
}

void CanTreeHub::end() {
    for (uint8_t i = 0; i < port_count_; ++i) {
        ports_[i].bus->end();
    }
    started_ = false;
}

const CanHubPort *CanTreeHub::port(uint8_t index) const {
    return index < port_count_ ? &ports_[index] : 0;
}

ICanBus *CanTreeHub::portBus(uint8_t segment) const {
    for (uint8_t i = 0; i < port_count_; ++i) {
        if (ports_[i].segment == segment) {
            return ports_[i].bus;
        }
    }
    return 0;
}

uint32_t CanTreeHub::fingerprint(const CanFrame &frame) const {
    uint32_t hash = 2166136261UL;
    hash ^= frame.id;
    hash *= 16777619UL;
    hash ^= frame.dlc;
    hash *= 16777619UL;
    for (uint8_t i = 0; i < frame.dlc && i < kPayloadSize; ++i) {
        hash ^= frame.data[i];
        hash *= 16777619UL;
    }
    return hash;
}

bool CanTreeHub::recentlySeen(uint32_t fingerprint_value, uint32_t now_ms) {
    for (uint8_t i = 0; i < CAN_HUB_DEDUPE_SLOTS; ++i) {
        DedupeEntry &entry = dedupe_[i];
        if (!entry.valid) {
            continue;
        }
        if ((now_ms - entry.seen_ms) >= dedupe_ms_) {
            entry.valid = false;
            continue;
        }
        if (entry.fingerprint == fingerprint_value) {
            return true;
        }
    }
    DedupeEntry &slot = dedupe_[dedupe_next_];
    slot.fingerprint = fingerprint_value;
    slot.seen_ms = now_ms;
    slot.valid = true;
    dedupe_next_ = static_cast<uint8_t>((dedupe_next_ + 1) % CAN_HUB_DEDUPE_SLOTS);
    return false;
}

void CanTreeHub::learn(uint16_t node_id, uint8_t port) {
    const uint8_t address = nodeIdAddress(node_id);
    if (address == 0) {
        return;
    }
    for (uint8_t i = 0; i < CAN_HUB_LEARN_SLOTS; ++i) {
        LearnEntry &entry = learned_[i];
        if (entry.valid && entry.address == address) {
            entry.port = port;
            return;
        }
    }
    LearnEntry &slot = learned_[learn_next_];
    slot.address = address;
    slot.port = port;
    slot.seen_ms = 0;
    slot.valid = true;
    learn_next_ = static_cast<uint8_t>((learn_next_ + 1) % CAN_HUB_LEARN_SLOTS);
}

void CanTreeHub::expireLearning(uint32_t now_ms) {
    for (uint8_t i = 0; i < CAN_HUB_LEARN_SLOTS; ++i) {
        LearnEntry &entry = learned_[i];
        if (entry.valid && entry.seen_ms != 0 && (now_ms - entry.seen_ms) >= kHubLearnHoldMs) {
            entry.valid = false;
        }
    }
}

int8_t CanTreeHub::learnedPort(uint8_t address) const {
    for (uint8_t i = 0; i < CAN_HUB_LEARN_SLOTS; ++i) {
        const LearnEntry &entry = learned_[i];
        if (entry.valid && entry.address == address) {
            return static_cast<int8_t>(entry.port);
        }
    }
    return kUnknownPort;
}

void CanTreeHub::forward(uint8_t origin_port, const CanFrame &frame, const CanId &id) {
    const bool directed = id.target != kBroadcastTarget;
    int8_t destination = kUnknownPort;
    if (route_mode_ == HUB_ROUTE_LEARNED && directed) {
        destination = learnedPort(id.target);
    }
    for (uint8_t p = 0; p < port_count_; ++p) {
        if (p == origin_port || ports_[p].bus == 0) {
            continue;
        }
        if (destination != kUnknownPort && destination != static_cast<int8_t>(p)) {
            continue;
        }
        if (ports_[p].bus->send(frame) == CAN_OK) {
            ++forwarded_;
            ++ports_[p].stats.forwarded;
        } else {
            ++ports_[p].stats.errors;
        }
    }
}

bool CanTreeHub::handleFrame(uint8_t origin_port, const CanFrame &frame, uint32_t now_ms) {
    if (origin_port >= port_count_) {
        return false;
    }
    const uint32_t fingerprint_value = fingerprint(frame);
    if (recentlySeen(fingerprint_value, now_ms)) {
        /* La misma trama ya circulo por el hub dentro de la ventana: lazo de
         * topologia o retransmision identica. No se reenvia. */
        ++dropped_;
        ++loops_;
        ++ports_[origin_port].stats.dropped;
        return false;
    }

    const CanId id = frame.fields();
    if (isValidSource(id.source)) {
        learn(id.source, origin_port);
        const uint8_t address = nodeIdAddress(id.source);
        for (uint8_t i = 0; i < CAN_HUB_LEARN_SLOTS; ++i) {
            if (learned_[i].valid && learned_[i].address == address) {
                learned_[i].seen_ms = now_ms;
            }
        }
    }
    forward(origin_port, frame, id);
    return true;
}

void CanTreeHub::poll(uint32_t now_ms) {
    if (!started_) {
        return;
    }
    for (uint8_t p = 0; p < port_count_; ++p) {
        ICanBus *bus = ports_[p].bus;
        if (bus == 0) {
            continue;
        }
        if (bus->isBusOff()) {
            bus->recover();
            ++ports_[p].stats.errors;
        }
        CanFrame frame;
        while (bus->receive(frame) == CAN_OK) {
            ++ports_[p].stats.received;
            handleFrame(p, frame, now_ms);
        }
    }
    expireLearning(now_ms);
}

}  // namespace pcd#pragma once

/*
 * Hub / star coupler CAN multi-puerto (Tree Extension).
 *
 * Es el nucleo software del nodo "Hub Repetidor" del PRD: un microcontrolador
 * con varios transceptores CAN, uno por ramal, que reenvia tramas entre ramales
 * aislados galvanicamente. Cada ramal es un bus lineal propio con sus dos
 * terminaciones de 120 ohm, de modo que la topologia global puede ser estrella
 * o arbol sin que las reflexiones de una rama afecten a las otras.
 *
 * Caracteristicas:
 *
 *   - un ICanBus por puerto (TWAI, MCP2515, bus virtual en pruebas),
 *   - reenvio con anti-bucle por huella temporal de trama (dedupe),
 *   - modo FLOOD (copia a todos los ramales) y modo LEARNED (aprende que
 *     direccion vive en cada ramal a partir del origen de las tramas y enruta
 *     los comandos dirigidos solo hacia el ramal correcto),
 *   - recuperacion automatica de bus-off por puerto y estadisticas por ramal,
 *   - sin memoria dinamica: tablas de tamano fijo.
 *
 * La topologia con lazos (dos hubs uniendo los mismos ramales) esta prohibida;
 * si ocurre, el dedupe la contiene pero el trafico se degrada.
 */

#include <stdint.h>

#include "can_protocol.h"
#include "hal_can.h"
#include "system_config.h"
#include "topology/bus_profile.h"

namespace pcd {

#ifndef CAN_HUB_MAX_PORTS
#define CAN_HUB_MAX_PORTS 4
#endif

#ifndef CAN_HUB_DEDUPE_SLOTS
#define CAN_HUB_DEDUPE_SLOTS 16
#endif

#ifndef CAN_HUB_LEARN_SLOTS
#define CAN_HUB_LEARN_SLOTS 16
#endif

/* Ventana anti-bucle por defecto: un lazo se cierra en menos de un milisegundo. */
static const uint32_t kHubDefaultDedupeMs = 20;

/* Tiempo de validez del aprendizaje de direccion -> ramal. */
static const uint32_t kHubLearnHoldMs = 30000;

enum HubRouteMode : uint8_t {
    HUB_ROUTE_FLOOD = 0,   /* reenvia toda trama a los demas ramales        */
    HUB_ROUTE_LEARNED = 1  /* enruta los comandos dirigidos al ramal sabido */
};

struct CanHubPortStats {
    uint32_t received;
    uint32_t forwarded;
    uint32_t dropped;
    uint32_t errors;
};

struct CanHubPort {
    ICanBus *bus;
    uint8_t segment;
    CanHubPortStats stats;
};

class CanTreeHub {
  public:
    explicit CanTreeHub(uint32_t bitrate = CAN_BUS_BITRATE);
    ~CanTreeHub();

    /* Registra un ramal. `segment` es el identificador logico del ramal. */
    bool addPort(ICanBus &bus, uint8_t segment);

    /* Inicializa todos los puertos. bitrate 0 usa el del constructor. */
    bool begin(uint32_t bitrate = 0);
    void end();

    /* Procesa todos los puertos: recibe, aprende y reenvia. */
    void poll(uint32_t now_ms);

    /* Procesa una trama ya recibida de `origin_port` (uso avanzado/pruebas). */
    bool handleFrame(uint8_t origin_port, const CanFrame &frame, uint32_t now_ms);

    void setRouteMode(HubRouteMode mode) { route_mode_ = mode; }
    HubRouteMode routeMode() const { return route_mode_; }
    void setDedupeWindow(uint32_t window_ms) { dedupe_ms_ = window_ms; }
    uint32_t dedupeWindow() const { return dedupe_ms_; }

    uint8_t portCount() const { return port_count_; }
    const CanHubPort *port(uint8_t index) const;
    ICanBus *portBus(uint8_t segment) const;

    uint32_t forwardedCount() const { return forwarded_; }
    uint32_t droppedCount() const { return dropped_; }
    uint32_t loopSuppressed() const { return loops_; }

    /* Ramal aprendido para una direccion; -1 (0xFF) si se desconoce. */
    int8_t learnedPort(uint8_t address) const;

    /* Devuelve el puerto al estado inicial sin tocar el hardware. */
    void clear();

  private:
    static const int8_t kUnknownPort = -1;

    uint32_t fingerprint(const CanFrame &frame) const;
    bool recentlySeen(uint32_t fingerprint, uint32_t now_ms);
    void learn(uint16_t node_id, uint8_t port);
    void expireLearning(uint32_t now_ms);
    void forward(uint8_t origin_port, const CanFrame &frame, const CanId &id);

    ICanBus *buses_[CAN_HUB_MAX_PORTS];
    CanHubPort ports_[CAN_HUB_MAX_PORTS];
    uint8_t port_count_;

    struct LearnEntry {
        uint8_t address;
        uint8_t port;
        uint32_t seen_ms;
        bool valid;
    };
    LearnEntry learned_[CAN_HUB_LEARN_SLOTS];
    uint8_t learn_next_;

    struct DedupeEntry {
        uint32_t fingerprint;
        uint32_t seen_ms;
        bool valid;
    };
    DedupeEntry dedupe_[CAN_HUB_DEDUPE_SLOTS];
    uint8_t dedupe_next_;

    uint32_t bitrate_;
    uint32_t dedupe_ms_;
    HubRouteMode route_mode_;
    uint32_t forwarded_;
    uint32_t dropped_;
    uint32_t loops_;
    bool started_;
};

}  // namespace pcd#include "node_watchdog.h"

#include <string.h>

namespace pcd {

NodeWatchdog::NodeWatchdog(uint32_t default_timeout_ms)
    : count_(0), default_timeout_ms_(default_timeout_ms), handler_(0), handler_ctx_(0) {
    clear();
}

void NodeWatchdog::clear() {
    count_ = 0;
    memset(nodes_, 0, sizeof(nodes_));
}

void NodeWatchdog::setDefaultTimeout(uint32_t timeout_ms) {
    default_timeout_ms_ = timeout_ms;
}

void NodeWatchdog::setSafeStateHandler(SafeStateHandler handler, void *ctx) {
    handler_ = handler;
    handler_ctx_ = ctx;
}

WatchedNode *NodeWatchdog::ensure(uint16_t node_id) {
    for (uint8_t i = 0; i < count_; ++i) {
        if (nodes_[i].node_id == node_id) {
            return &nodes_[i];
        }
    }
    if (count_ >= CAN_MAX_WATCHED_NODES) {
        return 0;
    }
    WatchedNode &node = nodes_[count_++];
    node.node_id = node_id;
    node.last_seen_ms = 0;
    node.timeout_ms = default_timeout_ms_;
    node.missed = 0;
    node.health = HEALTH_OK;
    node.online = true;
    node.ever_seen = true;
    return &node;
}

bool NodeWatchdog::setTimeout(uint16_t node_id, uint32_t timeout_ms) {
    WatchedNode *node = ensure(node_id);
    if (node == 0) {
        return false;
    }
    node->timeout_ms = timeout_ms;
    return true;
}

bool NodeWatchdog::feed(const CanFrame &frame, uint32_t now_ms) {
    const CanId id = frame.fields();
    if (!isValidSource(id.source)) {
        return false;
    }
    if (id.msg_type == MSG_HEARTBEAT) {
        uint32_t uptime = 0;
        uint8_t flags = 0;
        if (!decodeHeartbeat(frame, uptime, flags)) {
            return false;
        }
        WatchedNode *node = ensure(id.source);
        if (node == 0) {
            return false;
        }
        node->last_seen_ms = now_ms;
        node->online = true;
        node->missed = 0;
        node->health = flags;
        return true;
    }

    if (id.msg_type == MSG_STATE && frame.resource() == RES_SYSTEM &&
        frame.channel() == kHealthChannelReport) {
        NodeHealth health;
        if (!decodeHealthReport(frame, health)) {
            return false;
        }
        WatchedNode *node = ensure(id.source);
        if (node == 0) {
            return false;
        }
        node->health = health.flags;
        node->last_seen_ms = now_ms;
        node->online = true;
        node->missed = 0;
        return true;
    }
    return false;
}

uint8_t NodeWatchdog::poll(uint32_t now_ms) {
    uint8_t transitions = 0;
    for (uint8_t i = 0; i < count_; ++i) {
        WatchedNode &node = nodes_[i];
        if (node.timeout_ms == 0) {
            continue;
        }
        const uint32_t elapsed = now_ms - node.last_seen_ms;
        if (elapsed < node.timeout_ms) {
            continue;
        }
        const uint16_t windows = static_cast<uint16_t>(elapsed / node.timeout_ms);
        if (windows > node.missed) {
            const bool was_online = node.online;
            node.missed = windows;
            node.online = false;
            if (was_online && handler_ != 0) {
                handler_(node.node_id, node.last_seen_ms, handler_ctx_);
            }
            if (was_online) {
                ++transitions;
            }
        }
    }
    return transitions;
}

const WatchedNode *NodeWatchdog::find(uint16_t node_id) const {
    for (uint8_t i = 0; i < count_; ++i) {
        if (nodes_[i].node_id == node_id) {
            return &nodes_[i];
        }
    }
    return 0;
}

const WatchedNode *NodeWatchdog::at(uint8_t index) const {
    return index < count_ ? &nodes_[index] : 0;
}

bool NodeWatchdog::isOnline(uint16_t node_id) const {
    const WatchedNode *node = find(node_id);
    return node != 0 && node->online;
}

bool NodeWatchdog::age(uint16_t node_id, uint32_t now_ms, uint32_t &age_ms) const {
    const WatchedNode *node = find(node_id);
    if (node == 0) {
        return false;
    }
    age_ms = now_ms - node->last_seen_ms;
    return true;
}

uint16_t NodeWatchdog::missedWindows(uint16_t node_id) const {
    const WatchedNode *node = find(node_id);
    return node == 0 ? 0 : node->missed;
}

uint8_t NodeWatchdog::healthFlags(uint16_t node_id) const {
    const WatchedNode *node = find(node_id);
    return node == 0 ? static_cast<uint8_t>(HEALTH_OK) : node->health;
}

}  // namespace pcd#pragma once

/*
 * Perro guardian de red (Node Watchdog) con estado de falla seguro.
 *
 * Vigila los heartbeats de los nodos que le interesan: si un nodo de campo deja
 * de anunciarse, ejecuta una reaccion local (apagar cargas criticas, mantener la
 * ultima consigna segura, marcar el canal como no disponible...). El tiempo de
 * expiracion es configurable por nodo, de modo que un sensor de bateria pueda
 * tener una tolerancia distinta a la de un teclado.
 *
 * Es agnostico: no usa red ni memoria dinamica y sirve igual en un nodo de
 * campo (para vigilar al gateway) que en el gateway (para vigilar el campo).
 * El inventario completo con recursos es responsabilidad de NodeRegistry; este
 * watchdog solo responde a "quien dejo de hablar y que hago".
 */

#include <stdint.h>

#include "can_protocol.h"
#include "system_config.h"

namespace pcd {

#ifndef CAN_MAX_WATCHED_NODES
#define CAN_MAX_WATCHED_NODES 16
#endif

/* Reaccion de falla segura: se invoca una vez por transicion online -> offline. */
typedef void (*SafeStateHandler)(uint16_t node_id, uint32_t last_seen_ms, void *ctx);

struct WatchedNode {
    uint16_t node_id;
    uint32_t last_seen_ms;
    uint32_t timeout_ms;
    uint16_t missed;      /* ventanas de timeout vencidas desde el ultimo aviso */
    uint8_t health;       /* ultima bandera de salud (HealthFlag)               */
    bool online;
    bool ever_seen;
};

class NodeWatchdog {
  public:
    explicit NodeWatchdog(uint32_t default_timeout_ms = 3UL * CAN_HEARTBEAT_PERIOD_MS);

    /* Tolerancia por defecto para nodos nuevos. */
    void setDefaultTimeout(uint32_t timeout_ms);
    uint32_t defaultTimeout() const { return default_timeout_ms_; }

    /* Tolerancia especifica de un nodo (lo registra si no existe). */
    bool setTimeout(uint16_t node_id, uint32_t timeout_ms);

    /* Handler de falla segura invocado en cada expiracion. */
    void setSafeStateHandler(SafeStateHandler handler, void *ctx = 0);

    /* Alimenta el perro con una trama propia de un nodo remoto.
     * Acepta MSG_HEARTBEAT y el reporte de salud (MSG_STATE, RES_SYSTEM). */
    bool feed(const CanFrame &frame, uint32_t now_ms);

    /* Detecta expiraciones. Devuelve cuantas transiciones genero en esta llamada. */
    uint8_t poll(uint32_t now_ms);

    bool isOnline(uint16_t node_id) const;
    bool age(uint16_t node_id, uint32_t now_ms, uint32_t &age_ms) const;
    uint16_t missedWindows(uint16_t node_id) const;
    uint8_t healthFlags(uint16_t node_id) const;

    uint8_t count() const { return count_; }
    const WatchedNode *at(uint8_t index) const;
    const WatchedNode *find(uint16_t node_id) const;

    /* Olvida todos los nodos; el handler no se invoca. */
    void clear();

  private:
    WatchedNode *ensure(uint16_t node_id);

    WatchedNode nodes_[CAN_MAX_WATCHED_NODES];
    uint8_t count_;
    uint32_t default_timeout_ms_;
    SafeStateHandler handler_;
    void *handler_ctx_;
};

}  // namespace pcd#include "ota_receiver.h"

#include <string.h>

#include "config_storage.h"

namespace pcd {

OtaReceiver::OtaReceiver(uint16_t node_id, uint8_t hardware_id, IOtaTarget *target)
    : node_id_(node_id),
      hardware_id_(hardware_id),
      target_(target),
      state_(OTA_RX_IDLE),
      timeout_ms_(2000),
      sender_address_(0),
      version_major_(0),
      version_minor_(0),
      image_size_(0),
      total_blocks_(0),
      expected_crc_(0),
      window_size_(CAN_OTA_WINDOW_SLOTS > 16 ? 16 : CAN_OTA_WINDOW_SLOTS),
      window_index_(0),
      window_base_(0),
      window_mask_(0),
      blocks_received_(0),
      bytes_written_(0),
      computed_crc_(0xFFFF),
      last_activity_ms_(0),
      timeouts_(0),
      last_status_(OTA_STATUS_OK),
      image_verified_(false) {
    memset(slots_, 0, sizeof(slots_));
    memset(slot_len_, 0, sizeof(slot_len_));
}

const char *OtaReceiver::stateName() const {
    switch (state_) {
        case OTA_RX_IDLE: return "idle";
        case OTA_RX_VALIDATING: return "validating";
        case OTA_RX_RECEIVING: return "receiving";
        case OTA_RX_VERIFYING: return "verifying";
        case OTA_RX_DONE: return "done";
        default: return "failed";
    }
}

void OtaReceiver::reset() {
    if (target_ != 0 && (state_ == OTA_RX_RECEIVING || state_ == OTA_RX_VERIFYING)) {
        target_->abort();
    }
    state_ = OTA_RX_IDLE;
    sender_address_ = 0;
    version_major_ = 0;
    version_minor_ = 0;
    image_size_ = 0;
    total_blocks_ = 0;
    expected_crc_ = 0;
    window_index_ = 0;
    window_base_ = 0;
    window_mask_ = 0;
    blocks_received_ = 0;
    bytes_written_ = 0;
    computed_crc_ = 0xFFFF;
    timeouts_ = 0;
    last_status_ = OTA_STATUS_OK;
    image_verified_ = false;
    memset(slot_len_, 0, sizeof(slot_len_));
}

uint16_t OtaReceiver::fullWindowMask() const {
    const uint8_t size = window_size_ >= 16 ? 16 : window_size_;
    return size >= 16 ? 0xFFFF : static_cast<uint16_t>((1U << size) - 1U);
}

uint16_t OtaReceiver::expectedSlotCount() const {
    if (total_blocks_ <= window_base_) {
        return 0;
    }
    const uint16_t remaining = static_cast<uint16_t>(total_blocks_ - window_base_);
    return remaining > window_size_ ? window_size_ : remaining;
}

uint16_t OtaReceiver::missingMask() const {
    uint16_t expected = 0;
    const uint16_t slots = expectedSlotCount();
    for (uint8_t i = 0; i < slots; ++i) {
        expected |= static_cast<uint16_t>(1U << i);
    }
    return static_cast<uint16_t>(expected & ~window_mask_);
}

void OtaReceiver::fail(uint8_t status) {
    last_status_ = status;
    state_ = OTA_RX_FAILED;
    if (target_ != 0) {
        target_->abort();
    }
}

bool OtaReceiver::flushSlots(uint16_t count) {
    if (target_ == 0) {
        return false;
    }
    for (uint16_t i = 0; i < count; ++i) {
        if (slot_len_[i] == 0) {
            return false; /* hueco: la flash no se puede escribir en desorden */
        }
        if (!target_->writeBlock(static_cast<uint16_t>(window_base_ + i), slots_[i],
                                 slot_len_[i])) {
            return false;
        }
        computed_crc_ = crc16(slots_[i], slot_len_[i], computed_crc_);
        bytes_written_ += slot_len_[i];
        slot_len_[i] = 0;
    }
    return true;
}

bool OtaReceiver::acceptBlock(uint16_t sequence, const uint8_t *data, uint8_t len, uint32_t now_ms,
                              CanFrame &response, bool &needs_response) {
    if (len == 0 || len > kPayloadSize - 1) {
        return false;
    }
    if (sequence < window_base_) {
        return true; /* bloque ya confirmado en una ventana anterior */
    }
    if (sequence >= static_cast<uint16_t>(window_base_ + window_size_)) {
        uint8_t payload[6] = {OTA_STATUS_SEQUENCE_ERROR, 0, 0, 0, 0, 0};
        response = makeOtaControl(node_id_, sender_address_, OTA_STATUS, payload, sizeof(payload));
        needs_response = true;
        return true;
    }

    const uint8_t slot = static_cast<uint8_t>(sequence - window_base_);
    const uint16_t bit = static_cast<uint16_t>(1U << slot);
    if ((window_mask_ & bit) == 0) {
        memcpy(slots_[slot], data, len);
        slot_len_[slot] = len;
        window_mask_ |= bit;
        ++blocks_received_;
    }
    last_activity_ms_ = now_ms;
    timeouts_ = 0;

    if (expectedSlotCount() > 0 && window_mask_ == fullWindowMask()) {
        const uint16_t slots = expectedSlotCount();
        if (!flushSlots(slots)) {
            fail(OTA_STATUS_FLASH_ERROR);
            uint8_t aborted[1] = {OTA_STATUS_FLASH_ERROR};
            response =
                makeOtaControl(node_id_, sender_address_, OTA_ABORT, aborted, sizeof(aborted));
            needs_response = true;
            return true;
        }
        const uint8_t window_done = static_cast<uint8_t>(window_index_);
        window_base_ = static_cast<uint16_t>(window_base_ + window_size_);
        window_mask_ = 0;
        ++window_index_;
        uint8_t payload[6] = {window_done, 0, 0, OTA_STATUS_OK, 0, 0};
        response =
            makeOtaControl(node_id_, sender_address_, OTA_WINDOW_ACK, payload, sizeof(payload));
        needs_response = true;
    }
    return true;
}

bool OtaReceiver::handleControl(const CanFrame &frame, uint8_t command, const uint8_t *payload,
                                uint32_t now_ms, CanFrame &response, bool &needs_response) {
    (void)frame;
    switch (command) {
        case OTA_START: {
            image_size_ = readUint32BE(&payload[2]);
            version_major_ = payload[0];
            version_minor_ = payload[1];
            window_index_ = 0;
            window_base_ = 0;
            window_mask_ = 0;
            blocks_received_ = 0;
            bytes_written_ = 0;
            computed_crc_ = 0xFFFF;
            timeouts_ = 0;
            image_verified_ = false;
            last_activity_ms_ = now_ms;
            if (image_size_ == 0) {
                fail(OTA_STATUS_BAD_REQUEST);
                uint8_t aborted[1] = {OTA_STATUS_BAD_REQUEST};
                response = makeOtaControl(node_id_, sender_address_, OTA_ABORT, aborted,
                                          sizeof(aborted));
                needs_response = true;
                return true;
            }
            state_ = OTA_RX_VALIDATING;
            uint8_t status[6] = {OTA_STATUS_OK, 0, 0, 0, 0, 0};
            response = makeOtaControl(node_id_, sender_address_, OTA_STATUS, status,
                                      sizeof(status));
            needs_response = true;
            return true;
        }

        case OTA_META: {
            if (state_ != OTA_RX_VALIDATING) {
                uint8_t status[6] = {OTA_STATUS_BAD_REQUEST, 0, 0, 0, 0, 0};
                response = makeOtaControl(node_id_, sender_address_, OTA_STATUS, status,
                                          sizeof(status));
                needs_response = true;
                return true;
            }
            const uint8_t hardware = payload[0];
            expected_crc_ = readUint16BE(&payload[1]);
            total_blocks_ = readUint16BE(&payload[3]);
            const uint8_t requested_window = payload[5];
            if (requested_window > 0 && requested_window < window_size_) {
                window_size_ = requested_window;
            }
            const uint16_t expected_blocks =
                static_cast<uint16_t>((image_size_ + (kPayloadSize - 2)) / (kPayloadSize - 1));
            if (hardware != hardware_id_) {
                fail(OTA_STATUS_HW_MISMATCH);
                uint8_t aborted[1] = {OTA_STATUS_HW_MISMATCH};
                response = makeOtaControl(node_id_, sender_address_, OTA_ABORT, aborted,
                                          sizeof(aborted));
                needs_response = true;
                return true;
            }
            if (total_blocks_ == 0 || total_blocks_ != expected_blocks ||
                total_blocks_ > kOtaMaxDataBlocks) {
                fail(OTA_STATUS_BAD_REQUEST);
                uint8_t aborted[1] = {OTA_STATUS_BAD_REQUEST};
                response = makeOtaControl(node_id_, sender_address_, OTA_ABORT, aborted,
                                          sizeof(aborted));
                needs_response = true;
                return true;
            }
            if (target_ == 0 || !target_->begin(hardware_id_, image_size_)) {
                fail(OTA_STATUS_NO_SPACE);
                uint8_t aborted[1] = {OTA_STATUS_NO_SPACE};
                response = makeOtaControl(node_id_, sender_address_, OTA_ABORT, aborted,
                                          sizeof(aborted));
                needs_response = true;
                return true;
            }
            state_ = OTA_RX_RECEIVING;
            last_activity_ms_ = now_ms;
            timeouts_ = 0;
            uint8_t ready[6] = {OTA_STATUS_OK, window_size_, 0, 0, 0, 0};
            response =
                makeOtaControl(node_id_, sender_address_, OTA_READY_ACK, ready, sizeof(ready));
            needs_response = true;
            return true;
        }

        default:
            break;
    }
    return handleFinishOrAbort(command, payload, response, needs_response);
}

bool OtaReceiver::handleFinishOrAbort(uint8_t command, const uint8_t *payload, CanFrame &response,
                                      bool &needs_response) {
    switch (command) {
        case OTA_FINISH: {
            if (state_ != OTA_RX_RECEIVING) {
                uint8_t status[6] = {OTA_STATUS_NOT_READY, 0, 0, 0, 0, 0};
                response = makeOtaControl(node_id_, sender_address_, OTA_STATUS, status,
                                          sizeof(status));
                needs_response = true;
                return true;
            }
            if (blocks_received_ != total_blocks_) {
                const uint8_t window_done = static_cast<uint8_t>(window_index_);
                const uint16_t missing = missingMask();
                uint8_t ack[6] = {window_done, static_cast<uint8_t>(missing >> 8),
                                  static_cast<uint8_t>(missing & 0xFF), OTA_STATUS_OK, 0, 0};
                response = makeOtaControl(node_id_, sender_address_, OTA_WINDOW_ACK, ack,
                                          sizeof(ack));
                needs_response = true;
                return true;
            }
            if (!flushSlots(expectedSlotCount())) {
                fail(OTA_STATUS_FLASH_ERROR);
                uint8_t aborted[1] = {OTA_STATUS_FLASH_ERROR};
                response = makeOtaControl(node_id_, sender_address_, OTA_ABORT, aborted,
                                          sizeof(aborted));
                needs_response = true;
                return true;
            }
            state_ = OTA_RX_VERIFYING;
            if (computed_crc_ != expected_crc_) {
                fail(OTA_STATUS_CRC_ERROR);
                uint8_t aborted[1] = {OTA_STATUS_CRC_ERROR};
                response = makeOtaControl(node_id_, sender_address_, OTA_ABORT, aborted,
                                          sizeof(aborted));
                needs_response = true;
                return true;
            }
            if (target_ == 0 || !target_->finish()) {
                fail(OTA_STATUS_FLASH_ERROR);
                uint8_t aborted[1] = {OTA_STATUS_FLASH_ERROR};
                response = makeOtaControl(node_id_, sender_address_, OTA_ABORT, aborted,
                                          sizeof(aborted));
                needs_response = true;
                return true;
            }
            image_verified_ = true;
            last_status_ = OTA_STATUS_OK;
            state_ = OTA_RX_DONE;
            uint8_t ok[1] = {OTA_STATUS_OK};
            response = makeOtaControl(node_id_, sender_address_, OTA_FINISH, ok, sizeof(ok));
            needs_response = true;
            return true;
        }

        case OTA_ABORT: {
            /* El gateway cancela: se libera el medio y se confirma el aborto. */
            const bool active = state_ == OTA_RX_RECEIVING || state_ == OTA_RX_VERIFYING ||
                                state_ == OTA_RX_VALIDATING;
            if (target_ != 0 && active) {
                target_->abort();
            }
            state_ = OTA_RX_IDLE;
            last_status_ = payload[0];
            uint8_t status[6] = {payload[0], static_cast<uint8_t>(blocks_received_ >> 8),
                                 static_cast<uint8_t>(blocks_received_ & 0xFF), 0, 0, 0};
            response = makeOtaControl(node_id_, sender_address_, OTA_STATUS, status,
                                      sizeof(status));
            needs_response = true;
            return true;
        }

        default:
            return false;
    }
}

bool OtaReceiver::handleFrame(const CanFrame &frame, uint32_t now_ms, CanFrame &response,
                              bool &needs_response) {
    needs_response = false;
    const CanId id = frame.fields();
    if (id.msg_type != MSG_OTA || frame.dlc == 0) {
        return false;
    }
    if (id.target != address() && id.target != kBroadcastTarget) {
        return false;
    }
    if (!isValidSource(id.source)) {
        return false;
    }
    sender_address_ = nodeIdAddress(id.source);

    if (isOtaControlFrame(frame)) {
        uint8_t payload[6];
        uint8_t command = 0;
        if (!decodeOtaControl(frame, command, payload)) {
            return false;
        }
        return handleControl(frame, command, payload, now_ms, response, needs_response);
    }

    if (state_ != OTA_RX_RECEIVING) {
        return false;
    }
    const uint16_t sequence = frame.data[0];
    const uint8_t len = static_cast<uint8_t>(frame.dlc - 1);
    return acceptBlock(sequence, &frame.data[1], len, now_ms, response, needs_response);
}

bool OtaReceiver::poll(uint32_t now_ms, CanFrame &response) {
    if (state_ != OTA_RX_RECEIVING) {
        return false;
    }
    if ((now_ms - last_activity_ms_) < timeout_ms_) {
        return false;
    }
    last_activity_ms_ = now_ms;
    ++timeouts_;
    if (timeouts_ >= CAN_OTA_MAX_TIMEOUTS) {
        fail(OTA_STATUS_TIMEOUT);
        uint8_t aborted[1] = {OTA_STATUS_TIMEOUT};
        response = makeOtaControl(node_id_, sender_address_, OTA_ABORT, aborted, sizeof(aborted));
        return true;
    }
    uint8_t payload[6] = {OTA_STATUS_TIMEOUT, static_cast<uint8_t>(blocks_received_ >> 8),
                          static_cast<uint8_t>(blocks_received_ & 0xFF), 0, 0, 0};
    response = makeOtaControl(node_id_, sender_address_, OTA_STATUS, payload, sizeof(payload));
    return true;
}

}  // namespace pcd#pragma once

/*
 * Receptor OTA por CAN (lado nodo / bootloader).
 *
 * Implementa la maquina de estados de la wiki 6 sin conocer la plataforma: la
 * escritura real de la flash la aporta la aplicacion mediante IOtaTarget, de
 * modo que el mismo codigo sirve para:
 *
 *   - un bootloader AVR (seccion NRWW + escritura por paginas),
 *   - la particion OTA de un ESP32 (esp_ota_write/esp_ota_end),
 *   - un archivo en LittleFS o un arreglo en RAM para pruebas nativas.
 *
 * El receptor acumula una ventana de bloques en RAM (CAN_OTA_WINDOW_SLOTS
 * bloques de 7 bytes), la escribe en orden estricto cuando esta completa y
 * responde OTA_WINDOW_ACK con el mapa de bits faltante para que el emisor
 * retransmita solo lo perdido. La imagen solo se entrega a flash si el CRC-16
 * global coincide con el anunciado en OTA_META.
 */

#include <stddef.h>
#include <stdint.h>

#include "can_protocol.h"

namespace pcd {

/* Bloques por ventana que el receptor puede retener en RAM (7 bytes cada uno). */
#ifndef CAN_OTA_WINDOW_SLOTS
#define CAN_OTA_WINDOW_SLOTS 16
#endif

/* Timeouts consecutivos sin datos antes de abortar la campana. */
#ifndef CAN_OTA_MAX_TIMEOUTS
#define CAN_OTA_MAX_TIMEOUTS 3
#endif

enum OtaReceiverState : uint8_t {
    OTA_RX_IDLE = 0,     /* sin campana activa                            */
    OTA_RX_VALIDATING,   /* se recibio OTA_START, falta OTA_META          */
    OTA_RX_RECEIVING,    /* descargando bloques por ventanas              */
    OTA_RX_VERIFYING,    /* CRC correcto; se evalua el resultado del target */
    OTA_RX_DONE,         /* imagen aceptada y confirmada al emisor        */
    OTA_RX_FAILED        /* campana abortada (hw, CRC, flash o timeout)   */
};

/*
 * Destino de la imagen. La aplicacion lo implementa sobre su medio:
 *
 *   bool begin(hw_id, image_size)   prepara el medio (borra paginas/particion)
 *   bool writeBlock(seq, data, len) escribe el bloque `seq` en orden creciente
 *   bool finish()                   confirma la imagen (esp_ota_end, etc.)
 *   void abort()                    descarta lo escrito y libera recursos
 */
class IOtaTarget {
  public:
    virtual ~IOtaTarget() {}
    virtual bool begin(uint8_t hardware_id, size_t image_size) = 0;
    virtual bool writeBlock(uint16_t sequence, const uint8_t *data, uint8_t len) = 0;
    virtual bool finish() = 0;
    virtual void abort() = 0;
};

class OtaReceiver {
  public:
    OtaReceiver(uint16_t node_id, uint8_t hardware_id, IOtaTarget *target = 0);

    /* Instala o reemplaza el medio de escritura. */
    void setTarget(IOtaTarget *target) { target_ = target; }

    /* Timeout de inactividad por ventana (por defecto 2000 ms). */
    void setTimeout(uint32_t timeout_ms) { timeout_ms_ = timeout_ms; }

    /* Cancela la campana en curso y vuelve a IDLE. */
    void reset();

    /*
     * Procesa una trama MSG_OTA. Devuelve true cuando la trama pertenecia a
     * esta campana. `needs_response` indica que el llamador debe transmitir
     * `response` de vuelta al gateway.
     */
    bool handleFrame(const CanFrame &frame, uint32_t now_ms, CanFrame &response,
                     bool &needs_response);

    /* Vigila el timeout de la ventana. Devuelve true si genero una respuesta. */
    bool poll(uint32_t now_ms, CanFrame &response);

    OtaReceiverState state() const { return state_; }
    uint16_t blocksReceived() const { return blocks_received_; }
    uint16_t totalBlocks() const { return total_blocks_; }
    uint16_t lastWindow() const { return window_index_; }
    uint16_t missingMask() const;
    uint8_t lastStatus() const { return last_status_; }
    uint8_t windowSize() const { return window_size_; }
    uint8_t timeouts() const { return timeouts_; }
    bool imageVerified() const { return image_verified_; }
    size_t imageSize() const { return image_size_; }
    size_t bytesWritten() const { return bytes_written_; }
    uint16_t expectedCrc() const { return expected_crc_; }
    uint16_t computedCrc() const { return computed_crc_; }
    uint8_t versionMajor() const { return version_major_; }
    uint8_t versionMinor() const { return version_minor_; }
    uint8_t hardwareId() const { return hardware_id_; }
    const char *stateName() const;

  private:
    uint8_t address() const { return nodeIdAddress(node_id_); }
    uint16_t fullWindowMask() const;
    uint16_t expectedSlotCount() const;
    bool handleControl(const CanFrame &frame, uint8_t command, const uint8_t *payload,
                       uint32_t now_ms, CanFrame &response, bool &needs_response);
    bool handleFinishOrAbort(uint8_t command, const uint8_t *payload, CanFrame &response,
                             bool &needs_response);
    bool acceptBlock(uint16_t sequence, const uint8_t *data, uint8_t len, uint32_t now_ms,
                     CanFrame &response, bool &needs_response);
    bool flushSlots(uint16_t count);
    void fail(uint8_t status);

    uint16_t node_id_;
    uint8_t hardware_id_;
    IOtaTarget *target_;

    OtaReceiverState state_;
    uint32_t timeout_ms_;
    uint8_t sender_address_;

    uint8_t version_major_;
    uint8_t version_minor_;
    size_t image_size_;
    uint16_t total_blocks_;
    uint16_t expected_crc_;
    uint8_t window_size_;

    uint16_t window_index_;
    uint16_t window_base_;
    uint16_t window_mask_;
    uint16_t blocks_received_;
    size_t bytes_written_;
    uint16_t computed_crc_;

    uint32_t last_activity_ms_;
    uint8_t timeouts_;
    uint8_t last_status_;
    bool image_verified_;

    uint8_t slots_[CAN_OTA_WINDOW_SLOTS][kPayloadSize - 1];
    uint8_t slot_len_[CAN_OTA_WINDOW_SLOTS];
};

