}/*
 * CAN <-> Modbus TCP bidireccional (esclavo) para Loxone.
 *
 * El Miniserver Loxone integra hardware de terceros como MAESTRO Modbus TCP:
 * abre una conexion al puerto 502 del gateway y lee/escribe coils y holding
 * registers. Este sketch es el lado ESCLAVO:
 *
 *   Loxone Config (maestro) --TCP:502--> ModbusTcpServer --> IModbusRegisterMap
 *                                                            --> ModbusBridge --> CAN
 *
 * Dependencia de red (elegida por el proyecto): ArduinoModbus, ModbusTCP,
 * WiFiServer/EthernetServer manual, o AsyncTCP. `IModbusTcpStream` es un
 * adaptador de pocas lineas sobre el stack TCP elegido.
 */

#include <PCD_CAN.h>

/* ------------------------------------------------------------------ */
/* 1. Mapa de registros: traduccion coils/registers <-> valores CAN   */
/* ------------------------------------------------------------------ */

/*
 * Esquema de direccionamiento recomendado (bloques por nodo):
 *
 *   Coil = slot_nodo * 16 + (canal - 1)              -> reles y entradas digitales
 *   Reg  = 0x0100 + slot_nodo * 16 + (canal - 1)     -> dimmers/consignas (holding)
 *
 * `slot_nodo` lo asigna la aplicacion al descubrir el Node-ID (NodeRegistry).
 * El ejemplo usa un solo nodo 0x0016 con slot 0 para mantenerlo corto.
 */

static const uint16_t kHoldingBase = 0x0100;

struct RegisterMap {
    static const uint16_t kCoils = 16;
    static const uint16_t kRegs = 16;
    bool coils[kCoils];
    uint16_t regs[kRegs];
    pcd::ModbusBridge *bridge;

    static bool readCoil(uint16_t a, bool &v, void *ctx) {
        RegisterMap *self = static_cast<RegisterMap *>(ctx);
        if (a >= kCoils) return false;
        v = self->coils[a];
        return true;
    }
    static bool readRegister(uint16_t a, uint16_t &v, void *ctx) {
        RegisterMap *self = static_cast<RegisterMap *>(ctx);
        if (a < kHoldingBase || a - kHoldingBase >= kRegs) return false;
        v = self->regs[a - kHoldingBase];
        return true;
    }
    static bool writeCoil(uint16_t a, bool v, void *ctx) {
        RegisterMap *self = static_cast<RegisterMap *>(ctx);
        if (a >= kCoils) return false;
        self->coils[a] = v;
        /* Escritura del maestro -> comando CAN (rele/digital en canal a+1). */
        if (self->bridge != 0) {
            self->bridge->queueIncoming(0x0016, pcd::RES_RELAY, a + 1,
                                        v ? pcd::ACT_ON : pcd::ACT_OFF);
        }
        return true;
    }
    static bool writeRegister(uint16_t a, uint16_t v, void *ctx) {
        RegisterMap *self = static_cast<RegisterMap *>(ctx);
        if (a < kHoldingBase || a - kHoldingBase >= kRegs) return false;
        self->regs[a - kHoldingBase] = v;
        /* Consigna/dimmer -> comando CAN con valor. */
        if (self->bridge != 0) {
            self->bridge->queueIncoming(0x0016, pcd::RES_DIMMER, (a - kHoldingBase) + 1,
                                        pcd::ACT_SET_VALUE, v);
        }
        return true;
    }
};

/* ------------------------------------------------------------------ */
/* 2. Glue                                                             */
/* ------------------------------------------------------------------ */

RegisterMap g_map;
pcd::IModbusRegisterMap g_contract = {
    RegisterMap::readRegister, RegisterMap::readCoil,
    RegisterMap::writeRegister, RegisterMap::writeCoil, &g_map
};
pcd::ModbusBridge g_bridge(g_contract, kHoldingBase);

/*
 * El sketch real define un adaptador `IModbusTcpStream` sobre su stack TCP:
 *
 *   struct TcpStream : public pcd::IModbusTcpStream {
 *       // begin() -> server.begin(502)
 *       // clientConnected() -> client.connected()
 *       // available() -> client.available()
 *       // read/write -> client.read()/client.write()
 *       // stopClient() -> client.stop()
 *   };
 *   TcpStream g_tcp;
 *   pcd::ModbusTcpServer g_server(g_tcp, g_contract);
 */

void setup() {
    g_map.bridge = &g_bridge;
    // g_node.begin(...); g_gateway.attachBridge(g_bridge);
    // g_tcp.begin();
}

void loop() {
    // g_gateway.poll(millis());   // CAN <-> ModbusBridge
    // g_server.poll();            // Modbus TCP <-> IModbusRegisterMap
}/*
 * Gateway CAN <-> CAN por Ethernet LAN, ejecutable en dos ESP32.
 *
 * Flashear el mismo sketch en dos placas y cambiar kSegment/kLocalIp/
 * kPeerIp. Cada instancia tiene sus paginas /, /config y /simulate:
 *   /       estado del bridge e inventario local
 *   /config configura peer LAN, puertos y segmento
 *   /simulate simula un dispositivo de la otra red enviando un comando CAN
 *
 * Dependencias SOLO del ejemplo: Ethernet.h/EthernetUDP.h o WiFi.h/WiFiUDP.h
 * y WebServer.h. Ninguna se agrega a PCD_CAN.
 */
#include <PCD_CAN.h>
#include <WebServer.h>
#include <WiFi.h>
#include <WiFiUdp.h>

namespace {

const uint8_t kSegment = 1;       // En la segunda placa usar 2.
const char *kLocalIp = "192.168.10.21";
const char *kPeerIp = "192.168.10.22";
const uint16_t kTunnelPort = 17890;
const uint16_t kPeerPort = 17890;

class LanTransport : public pcd::ITunnelTransport {
  public:
    LanTransport() : peer_(1), port_(kTunnelPort), peer_port_(kPeerPort) {}

    void begin() { udp_.begin(port_); }

    bool send(uint16_t, const uint8_t *data, size_t len) override {
        if (udp_.beginPacket(peer_ip_, peer_port_) != 1) return false;
        if (udp_.write(data, len) != len) return false;
        return udp_.endPacket() == 1;
    }

    bool receive(uint16_t &peer, uint8_t *data, size_t max_len,
                 size_t &len) override {
        const int packet_size = udp_.parsePacket();
        if (packet_size <= 0) return false;
        len = udp_.read(data, max_len);
        peer = peer_;
        return len > 0;
    }

    bool available() const override {
        return const_cast<WiFiUDP &>(udp_).parsePacket() > 0;
    }

    void setPeer(const IPAddress &address, uint16_t port) {
        peer_ip_ = address;
        peer_port_ = port;
    }

    IPAddress peer_ip_;
    WiFiUDP udp_;
    uint16_t peer_;
    uint16_t port_;
    uint16_t peer_port_;
};

#if defined(ARDUINO_ARCH_ESP32)
pcd::Esp32TwaiBus can_bus(5, 4);
#else
#error "Este ejemplo LAN requiere ESP32 TWAI"
#endif
pcd::CanNode node(can_bus, kSegment == 1 ? 0x0001 : 0x0002);
LanTransport transport;
pcd::TunnelEngine tunnel(transport);
pcd::TunnelRelayGuard relay_guard(kSegment);
WebServer server(80);
uint32_t forwarded = 0;
uint32_t received = 0;
uint8_t simulated_target = kSegment == 1 ? 0x16 : 0x17;
bool injecting_remote = false;

void forwardFrame(const pcd::CanFrame &frame, void *) {
    if (!injecting_remote && relay_guard.accept(0xFF, frame, millis())) {
        tunnel.sendFrame(1, frame);
        ++forwarded;
    }
}

void pageHeader(const char *title) {
    server.setContentLength(CONTENT_LENGTH_UNKNOWN);
    server.send(200, "text/html; charset=utf-8", "<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width'><title>PCD LAN Bridge</title><style>body{font:16px sans-serif;max-width:760px;margin:30px auto;padding:0 18px;background:#f3f0e8;color:#17212b}nav{display:flex;gap:12px;flex-wrap:wrap;margin:18px 0}a,button{padding:10px 14px;background:#0c7c86;color:white;border:0;text-decoration:none}section{background:white;padding:20px;margin:14px 0;border:1px solid #d8d1c5}input{padding:9px;margin:5px;width:220px}</style></head><body><h1>PCD LAN Bridge</h1><p>Segmento local: ");
    server.sendContent(String(kSegment).c_str());
    server.sendContent("</p><nav><a href='/'>Estado</a><a href='/config'>Configurar</a><a href='/simulate'>Simular dispositivo</a></nav><section><h2>");
    server.sendContent(title);
    server.sendContent("</h2>");
}

void pageEnd() { server.sendContent("</section></body></html>"); }

void handleRoot() {
    pageHeader("Estado bidireccional");
    server.sendContent("<p>Peer LAN: " + transport.peer_ip_.toString() + ":" + String(transport.peer_port_) + "</p>");
    server.sendContent("<p>Datagramas CAN -> LAN: " + String(forwarded) + "</p>");
    server.sendContent("<p>Datagramas LAN -> CAN: " + String(received) + "</p>");
    server.sendContent("<p>Anti-loop: activo, ventana 5 segundos.</p>");
    server.sendContent("<p>El control local sigue funcionando si el peer se desconecta.</p>");
    pageEnd();
}

void handleConfig() {
    if (server.hasArg("peer")) {
        IPAddress address;
        if (address.fromString(server.arg("peer"))) {
            transport.setPeer(address, server.arg("port").toInt());
        }
    }
    pageHeader("Configurar peer");
    server.sendContent("<form method='post'><label>IP peer <input name='peer' value='" + transport.peer_ip_.toString() + "'></label><br><label>Puerto <input name='port' value='" + String(transport.peer_port_) + "'></label><br><button>Guardar</button></form>");
    pageEnd();
}

void handleSimulate() {
    if (server.hasArg("target")) simulated_target = server.arg("target").toInt();
    if (server.method() == HTTP_POST) {
        const uint8_t action = server.arg("action").toInt();
        node.sendCommand(simulated_target, pcd::RES_RELAY, 1, action);
    }
    pageHeader("Simular dispositivo remoto");
    server.sendContent("<p>Esto genera un comando CAN dirigido al Node-ID remoto configurado.</p><form method='post'><label>Node-ID <input name='target' value='" + String(simulated_target) + "'></label><br><label>Accion 0=OFF 1=ON 2=TOGGLE <input name='action' value='2'></label><br><button>Enviar por CAN</button></form>");
    pageEnd();
}

void setup() {
    IPAddress local_address;
    local_address.fromString(kLocalIp);
    WiFi.config(local_address, IPAddress(192,168,10,1), IPAddress(255,255,255,0));
    WiFi.begin("PCD-LAN", "cambiar-password");
    while (WiFi.status() != WL_CONNECTED) delay(250);

    IPAddress peer_address;
    peer_address.fromString(kPeerIp);
    transport.setPeer(peer_address, kPeerPort);
    transport.begin();
    node.onAnyFrame(forwardFrame, 0);
    node.begin(500000);

    server.on("/", HTTP_GET, handleRoot);
    server.on("/config", HTTP_ANY, handleConfig);
    server.on("/simulate", HTTP_ANY, handleSimulate);
    server.begin();
}

void loop() {
    server.handleClient();
    while (tunnel.available()) {
        uint16_t peer = 0;
        pcd::CanFrame frame;
        if (!tunnel.receiveFrame(peer, frame)) continue;
        if (relay_guard.accept(kSegment == 1 ? 2 : 1, frame, millis())) {
            injecting_remote = true;
            node.handleFrame(frame);
            injecting_remote = false;
            ++received;
        }
    }
    node.poll(millis());
}# CanLanBridgeGateway

Ejemplo completo para unir dos redes CAN independientes por una LAN usando dos ESP32.

## Topologia

```text
Red CAN A -- ESP32 Gateway A -- UDP LAN -- ESP32 Gateway B -- Red CAN B
```

Cada gateway conserva su Node-ID y sus dispositivos locales. El enlace solo
reenvia frames CAN seleccionados; no existe un controlador central obligatorio.
Si el peer LAN se apaga, cada red CAN local sigue operativa.

## Configuracion de las dos placas

En la primera instancia:

```cpp
const uint8_t kSegment = 1;
const char *kLocalIp = "192.168.10.21";
const char *kPeerIp = "192.168.10.22";
```

En la segunda:

```cpp
const uint8_t kSegment = 2;
const char *kLocalIp = "192.168.10.22";
const char *kPeerIp = "192.168.10.21";
```

El sketch usa UDP en el puerto 17890. Se puede reemplazar `WiFiUDP` por
`EthernetUDP`/W5500 manteniendo `ITunnelTransport`.

## Paginas de cada gateway

- `/`: estado del peer, frames enviados/recibidos y anti-loop.
- `/config`: cambia IP y puerto del peer.
- `/simulate`: genera un comando CAN dirigido a un Node-ID remoto para probar
  la red sin conectar todavía un dispositivo físico en el otro segmento.

La simulacion no inventa estados: solo envia el comando. El estado confirmado
debe volver como `MSG_STATE` desde el dispositivo remoto.

## Anti-loop

`TunnelRelayGuard` rechaza frames cuyo segmento de origen coincide con el local
y deduplica el mismo frame durante una ventana de 5 segundos. El datagrama base
no contiene autenticacion; el ejemplo debe usarse en una LAN confiable o detrás
de una VPN/firewall. Para una instalacion de produccion agregar HMAC/AEAD en el
proyecto de aplicacion./*
 * Anuncio de capacidades y filtros de escucha.
 *
 * Al primer poll() el nodo anuncia su identidad y cada recurso registrado.
 * Los filtros limitan los estados que llegan a las suscripciones locales.
 * Tambien pueden configurarse remotamente con CFG_SUBSCRIBE por CAN.
 */
#include <PCD_CAN.h>

#if defined(ARDUINO_ARCH_ESP32)
pcd::Esp32TwaiBus bus(5, 4);
#else
pcd::Mcp2515Bus bus(10, pcd::MCP_CLOCK_16MHZ, 2);
#endif

pcd::CanNode node(bus, 0x0016);
float relayValue = 0.0f;

bool relay(uint8_t, uint8_t action, uint32_t, float &value, void *) {
    relayValue = action == pcd::ACT_OFF ? 0.0f : 1.0f;
    value = relayValue;
    return action <= pcd::ACT_TOGGLE;
}

void onRemoteState(const pcd::CanFrame &, float value, void *) {
    Serial.print("Estado remoto recibido: ");
    Serial.println(value);
}

void setup() {
    Serial.begin(115200);
    node.registerResource(pcd::RES_RELAY, 1, relay);
    node.addListenFilter(pcd::kAnySource, pcd::RES_ENV_SENSOR, pcd::kAnyChannel);
    node.subscribe(pcd::kAnySource, pcd::RES_ENV_SENSOR, pcd::kAnyChannel,
                   onRemoteState);
    node.begin(500000);
    node.publishDiscovery();
}

void loop() {
    node.poll(millis());
