    } else {
        node.setNodeId(config.nodeId());
        config.setNodeIdMode(pcd::NODE_ID_MANUAL);
    }
    node.setNodeIdMode(config.nodeIdMode());
    config.setNodeId(node.nodeId());
    config.save();
    node.begin(500000);
    rules.begin();
}

void loop() {
