}/*
 * Nodo con multiples elementos: dos reles, dos dimmers y cuatro entradas.
 * Cada canal se anuncia por MSG_DISCOVERY_RESOURCE y se configura por CAN.
 */
#include <PCD_CAN.h>

#if defined(ARDUINO_ARCH_ESP32)
pcd::Esp32TwaiBus bus(5, 4);
#else
pcd::Mcp2515Bus bus(10, pcd::MCP_CLOCK_16MHZ, 2);
#endif
pcd::CanNode node(bus, 0x0020);
float values[8] = {0};

bool multiHandler(uint8_t channel, uint8_t action, uint32_t param, float &value, void *) {
    (void)param;
    if (channel >= 8 || action > pcd::ACT_SET_VALUE) return false;
    if (action == pcd::ACT_OFF) values[channel] = 0;
    else if (action == pcd::ACT_ON) values[channel] = 1;
    else if (action == pcd::ACT_TOGGLE) values[channel] = values[channel] > 0 ? 0 : 1;
    else values[channel] = pcd::unpackSetValueTarget(param);
    value = values[channel]; return true;
}
void setup() {
    for (uint8_t channel = 1; channel <= 2; ++channel)
        node.registerResource(pcd::RES_RELAY, channel, multiHandler);
    for (uint8_t channel = 1; channel <= 2; ++channel)
        node.registerResource(pcd::RES_DIMMER, channel, multiHandler);
    for (uint8_t channel = 1; channel <= 4; ++channel)
        node.registerResource(pcd::RES_DIGITAL_INPUT, channel, multiHandler);
    node.begin(500000);
}
void loop() { node.poll(millis()); }/*
 * Nodo de campo minimo: un rele en el canal 1 y un pulsador local.
 *
 * El pulsador difunde su evento al bus y conmuta el rele local; tras conmutar,
 * el nodo difunde el estado resultante para que pantallas y gateways se
 * sincronicen sin preguntar (lazo comando -> ejecucion -> difusion).
 */

#include <PCD_CAN.h>

#if defined(ARDUINO_ARCH_ESP32)
pcd::Esp32TwaiBus bus(5 /* TX */, 4 /* RX */);
#else
pcd::Mcp2515Bus bus(10 /* CS */, pcd::MCP_CLOCK_16MHZ, 2 /* INT */);
#endif

pcd::CanNode node(bus, 0x0016);

const uint8_t kRelayPin = 7;
const uint8_t kButtonPin = 8;

bool relay_state = false;
bool last_button = true;

bool relayHandler(uint8_t channel, uint8_t action, uint32_t param, float &out_value, void *ctx) {
    (void)channel;
    (void)param;
    (void)ctx;
    switch (action) {
        case pcd::ACT_OFF: relay_state = false; break;
        case pcd::ACT_ON: relay_state = true; break;
        case pcd::ACT_TOGGLE: relay_state = !relay_state; break;
        default: return false;
    }
    digitalWrite(kRelayPin, relay_state ? HIGH : LOW);
    out_value = relay_state ? 1.0f : 0.0f;
    return true;
}

void setup() {
    pinMode(kRelayPin, OUTPUT);
    pinMode(kButtonPin, INPUT_PULLUP);

    node.begin(500000);
    node.registerResource(pcd::RES_RELAY, 0x01, relayHandler);
}

void loop() {
    node.poll(millis());

    const bool button = digitalRead(kButtonPin);
    if (last_button && !button) {
        node.publishInputEvent(0x01, pcd::EVT_SHORT_CLICK);
        node.applyLocal(pcd::RES_RELAY, 0x01, pcd::ACT_TOGGLE);
        delay(30);
    }
    last_button = button;
}/*
