namespace pcd {

/* Contratos minimos: los SDK de CANopen/NMEA2000/KNX quedan en la aplicacion. */
struct ICanopenTransport {
    bool (*sendPdo)(uint16_t cob_id, const uint8_t *data, size_t len, void *ctx);
    void *ctx;
    ICanopenTransport() : sendPdo(0), ctx(0) {}
};

struct INmea2000Transport {
    bool (*sendPgn)(uint32_t pgn, uint8_t destination, const uint8_t *data,
                    size_t len, void *ctx);
    void *ctx;
    INmea2000Transport() : sendPgn(0), ctx(0) {}
};

class CanopenBridge : public IBridge {
  public:
    explicit CanopenBridge(ICanopenTransport &transport);
    void queueIncoming(uint16_t node_id, uint8_t resource, uint8_t channel,
                       uint8_t action, uint32_t param = 0);
    bool process(const CanonicalFrame &frame) override;
    bool buildCanonical(CanonicalFrame &out) override;
    bool available() const override;

  private:
    ICanopenTransport &transport_;
    CanonicalFrame pending_[8];
    uint8_t pending_count_;
};

class Nmea2000Bridge : public IBridge {
  public:
    explicit Nmea2000Bridge(INmea2000Transport &transport);
    void queueIncoming(uint16_t source_id, uint8_t resource, uint8_t channel,
                       float value, uint16_t flags = DIAG_NONE);
    bool process(const CanonicalFrame &frame) override;
    bool buildCanonical(CanonicalFrame &out) override;
    bool available() const override;

  private:
    INmea2000Transport &transport_;
    CanonicalFrame pending_[8];
    uint8_t pending_count_;
};

class KnxBridge : public IBridge {
  public:
    explicit KnxBridge(IKnxTransport &transport);
    void queueIncoming(const uint8_t *address, const uint8_t *data, size_t len,
                       uint8_t dpt, uint16_t source_id, uint8_t resource, uint8_t channel);
    bool process(const CanonicalFrame &frame) override;
    bool buildCanonical(CanonicalFrame &out) override;
    bool available() const override;

  private:
    IKnxTransport &transport_;
    CanonicalFrame pending_[8];
    uint8_t pending_count_;
};

/* PGNs de referencia para recursos PCD; la aplicacion puede reemplazarlos. */
static const uint32_t kPgnPcdState = 130000UL;
static const uint16_t kCanopenPcdBaseCobId = 0x180;

}  // namespace pcd#pragma once

/*
 * Interfaces de puente (bridges) agnosticas.
 *
 * Cada puente traduce en ambas direcciones entre el bus CAN y un protocolo
 * externo. Para NO acoplar librerias de terceros, la libreria define solo
 * *contratos* con callbacks/funciones que la aplicacion inyecta:
 *
 *   - MQTT    -> IMqttTransport (publicar, suscribirse, callback de llegada)
 *   - Modbus  -> IModbusRegisterMap (leer/escribir registros, coils)
 *   - ESP-NOW -> IEspNowTransport (enviar/recibir un paquete de bytes)
 *   - KNX     -> IKnxTransport (enviar/recibir GroupValue con DPT)
 *   - IP      -> ITunnelTransport (ya existe en tunnel/tunnel_transport.h)
 *
 * La aplicacion conecta su libreria preferida (PubSubClient, ModbusMaster,
 * esp_now.h, eremmel/knx, WiFiUdp...) escribiendo un adaptador de pocas
 * lineas, y lo pasa al bridge correspondiente.
 */

#include <stddef.h>
#include <stdint.h>

#include "routing/canonical.h"

namespace pcd {

/* ------------------------------------------------------------------ */
/* Contrato generico de un puente                                     */
/* ------------------------------------------------------------------ */

class IBridge {
  public:
    virtual ~IBridge() {}

    /* Recibe una CanonicalFrame de salida (el enrutador la entrego porque
     * el destino era este protocolo). El puente la traduce y la envia. */
    virtual bool process(const CanonicalFrame &frame) = 0;

    /* Ruta de entrada: algo llego del protocolo externo y debe convertirse
     * en una CanonicalFrame para el enrutador. */
    virtual bool buildCanonical(CanonicalFrame &out) = 0;

    /* true si hay una tarea pendiente de procesar (por ejemplo un mensaje
     * MQTT recibido). */
    virtual bool available() const = 0;
};

/* ------------------------------------------------------------------ */
/* Transporte MQTT inyectable                                        */
/* ------------------------------------------------------------------ */

struct IMqttTransport {
    /* Publicar un mensaje en un topico. Devuelve true si se encolo. */
    bool (*publish)(const char *topic, const uint8_t *data, size_t len, bool retain);

    /* Suscribirse a un topico. */
    bool (*subscribe)(const char *topic);

    /* Callback cuando llega un mensaje MQTT. */
    void (*onMessage)(const char *topic, const uint8_t *data, size_t len, void *ctx);
    void *ctx;

    IMqttTransport() : publish(0), subscribe(0), onMessage(0), ctx(0) {}
};

/* ------------------------------------------------------------------ */
/* Transporte Modbus inyectable                                      */
/* ------------------------------------------------------------------ */

struct IModbusRegisterMap {
    /* Leer un registro holding / input / coil. */
    bool (*readRegister)(uint16_t address, uint16_t &value, void *ctx);
    bool (*readCoil)(uint16_t address, bool &value, void *ctx);

    /* Escribir un registro holding / coil. */
    bool (*writeRegister)(uint16_t address, uint16_t value, void *ctx);
    bool (*writeCoil)(uint16_t address, bool value, void *ctx);
    void *ctx;

    IModbusRegisterMap()
        : readRegister(0), readCoil(0), writeRegister(0), writeCoil(0), ctx(0) {}
};

/* ------------------------------------------------------------------ */
/* Transporte ESP-NOW inyectable                                     */
/* ------------------------------------------------------------------ */

struct IEspNowTransport {
    /* Enviar un paquete de hasta 250 bytes a la MAC destino. */
    bool (*send)(const uint8_t *mac, const uint8_t *data, size_t len);

    /* Callback al recibir un paquete ESP-NOW. */
    void (*onReceive)(const uint8_t *mac, const uint8_t *data, size_t len, void *ctx);
    void *ctx;

    IEspNowTransport() : send(0), onReceive(0), ctx(0) {}
};

/* ------------------------------------------------------------------ */
/* Transporte KNX inyectable (Group Value + DPT)                     */
/* ------------------------------------------------------------------ */

struct IKnxTransport {
    /* Enviar un GroupValue con un DPT. datos se interpreta segun dpt. */
    bool (*sendGroupValue)(const uint8_t *addr, const uint8_t *data, size_t len, uint8_t dpt);

    /* Callback al recibir un GroupValue del bus KNX. */
    void (*onGroupValue)(const uint8_t *addr, const uint8_t *data, size_t len,
                         uint8_t dpt, void *ctx);
    void *ctx;

    IKnxTransport() : sendGroupValue(0), onGroupValue(0), ctx(0) {}
};

/* ------------------------------------------------------------------ */
/* Helpers de conversion CanonicalFrame <-> protocolos                */
/* ------------------------------------------------------------------ */

/* Recurso PCD -> tipo de componente Home Assistant / UI (para MQTT discovery). */
const char *resourceComponentName(uint8_t resource);

}  // namespace pcd#pragma once

/*
 * Bucle de eventos asincrono para CAN.
 *
 * Separa estrictamente la recepcion de hardware del procesamiento de la
 * logica de negocio:
 *
 *   ISR:
 *     [can_ctrl] --leer frame--> [event_loop->enqueue(frame)]   (~us)
 *
 *   Main loop:
 *     event_loop.tick() -> drena la cola y llama a process(frame, ctx)
 *
 * De esta forma una rafaga de tramas consecutivas a alta velocidad no bloquea
 * el bus: la ISR solo copia bytes y el procesamiento (descomprimir ID de 29
 * bits, validar recurso, actualizar EEPROM, ejecutar accion) ocurre fuera de
 * la interrupcion, en el hilo principal.
 */

#include "core/ring_buffer.h"
#include "can_protocol.h"

namespace pcd {

static const size_t kCanEventDepth = 16;

typedef void (*CanEventProcessor)(const CanFrame &frame, void *ctx);

class CanEventLoop {
  public:
    CanEventLoop() : process_(0), ctx_(0) {}

    void attach(CanEventProcessor process, void *ctx) {
        process_ = process;
        ctx_ = ctx;
    }

    /* ISR-safe: deposita la trama en el ring buffer SPSC. */
    bool enqueue(const CanFrame &frame) {
        return rx_.push(frame);
    }

    /* Main loop: drena todas las tramas pendientes y las despacha. */
    void tick() {
        CanFrame frame;
        while (rx_.pop(frame)) {
            if (process_ != 0) {
                process_(frame, ctx_);
            }
        }
    }

    /* Devuelve una unica trama pendiente (poll de una por ciclo). */
    bool next(CanFrame &frame) {
        return rx_.pop(frame);
    }

    size_t pending() const { return rx_.count(); }
    bool empty() const { return rx_.empty(); }

    void clear() {
        rx_.clear();
    }

  private:
    RingBuffer<CanFrame, kCanEventDepth> rx_;
    CanEventProcessor process_;
    void *ctx_;
};

}  // namespace pcd#if defined(ARDUINO_ARCH_ESP32)

#include "hal/hal_can_esp32.h"

#include <driver/twai.h>

#include <string.h>

namespace pcd {

namespace {

twai_timing_config_t timingFor(uint32_t bitrate) {
    switch (bitrate) {
        case 1000000UL: {
            twai_timing_config_t t = TWAI_TIMING_CONFIG_1MBITS();
            return t;
        }
        case 800000UL: {
            twai_timing_config_t t = TWAI_TIMING_CONFIG_800KBITS();
            return t;
        }
        case 250000UL: {
            twai_timing_config_t t = TWAI_TIMING_CONFIG_250KBITS();
            return t;
        }
        case 125000UL: {
            twai_timing_config_t t = TWAI_TIMING_CONFIG_125KBITS();
            return t;
        }
        case 100000UL: {
            twai_timing_config_t t = TWAI_TIMING_CONFIG_100KBITS();
            return t;
        }
        case 500000UL:
        default: {
            twai_timing_config_t t = TWAI_TIMING_CONFIG_500KBITS();
            return t;
        }
    }
}

}  // namespace

Esp32TwaiBus::Esp32TwaiBus(int tx_pin, int rx_pin)
    : tx_pin_(tx_pin), rx_pin_(rx_pin), started_(false), filter_(CanFilter::acceptAll()) {}

Esp32TwaiBus::~Esp32TwaiBus() {
    end();
}

CanStatus Esp32TwaiBus::begin(uint32_t bitrate) {
    twai_general_config_t general = TWAI_GENERAL_CONFIG_DEFAULT(
        static_cast<gpio_num_t>(tx_pin_), static_cast<gpio_num_t>(rx_pin_), TWAI_MODE_NORMAL);
    general.rx_queue_len = 32;
    general.tx_queue_len = 16;

    twai_timing_config_t timing = timingFor(bitrate);

    /*
     * El filtrado fino se aplica por software en receive(): el filtro de
     * aceptacion del TWAI solo admite una mascara y aqui se necesita aceptar
     * tanto el destino propio como el broadcast.
     */
    twai_filter_config_t accept = TWAI_FILTER_CONFIG_ACCEPT_ALL();

    if (twai_driver_install(&general, &timing, &accept) != ESP_OK) {
        LOG_ERROR("TWAI install failed");
        return CAN_ERR_INIT;
    }
    if (twai_start() != ESP_OK) {
        twai_driver_uninstall();
        LOG_ERROR("TWAI start failed");
        return CAN_ERR_INIT;
    }
    started_ = true;
    LOG_INFO("TWAI iniciado a %lu bps", static_cast<unsigned long>(bitrate));
    return CAN_OK;
}

void Esp32TwaiBus::end() {
    if (!started_) {
        return;
    }
    twai_stop();
    twai_driver_uninstall();
    started_ = false;
}

CanStatus Esp32TwaiBus::send(const CanFrame &frame, uint32_t timeout_ms) {
    if (!started_) {
        return CAN_ERR_NOT_STARTED;
    }
    twai_message_t msg;
    memset(&msg, 0, sizeof(msg));
    msg.identifier = frame.id & kExtendedIdMask;
    msg.extd = 1;
    msg.data_length_code = frame.dlc;
    memcpy(msg.data, frame.data, frame.dlc);

    const esp_err_t err = twai_transmit(&msg, pdMS_TO_TICKS(timeout_ms));
    if (err == ESP_OK) {
        return CAN_OK;
    }
    return (err == ESP_ERR_TIMEOUT) ? CAN_ERR_TX_BUSY : CAN_ERR_TX_FAIL;
}

CanStatus Esp32TwaiBus::receive(CanFrame &frame, uint32_t timeout_ms) {
    if (!started_) {
        return CAN_ERR_NOT_STARTED;
    }
    twai_message_t msg;
    if (twai_receive(&msg, pdMS_TO_TICKS(timeout_ms)) != ESP_OK) {
        return CAN_ERR_NO_DATA;
    }
    if (!msg.extd || !filter_.accepts(msg.identifier)) {
        return CAN_ERR_NO_DATA;
    }
    frame.id = msg.identifier;
    frame.dlc = msg.data_length_code;
    memcpy(frame.data, msg.data, sizeof(frame.data));
    return CAN_OK;
}

void Esp32TwaiBus::setFilter(const CanFilter &filter) {
    filter_ = filter;
}

bool Esp32TwaiBus::isBusOff() const {
    twai_status_info_t status;
    if (twai_get_status_info(&status) != ESP_OK) {
        return false;
    }
    return status.state == TWAI_STATE_BUS_OFF;
}

CanStatus Esp32TwaiBus::recover() {
    if (twai_initiate_recovery() != ESP_OK) {
        return CAN_ERR_BUS_OFF;
    }
    return (twai_start() == ESP_OK) ? CAN_OK : CAN_ERR_BUS_OFF;
}

}  // namespace pcd

#endif  /* ARDUINO_ARCH_ESP32 */#pragma once

