#include "hal/hal_can_native.h"

namespace pcd {

VirtualBus::VirtualBus() : node_count_(0), traffic_(0) {
    for (size_t i = 0; i < kMaxNodes; ++i) {
        nodes_[i] = NULL;
    }
}

void VirtualBus::attach(NativeCanBus *node) {
    if (node_count_ < kMaxNodes) {
        nodes_[node_count_++] = node;
    }
}

void VirtualBus::detach(NativeCanBus *node) {
    for (size_t i = 0; i < node_count_; ++i) {
        if (nodes_[i] == node) {
            for (size_t j = i; j + 1 < node_count_; ++j) {
                nodes_[j] = nodes_[j + 1];
            }
            nodes_[--node_count_] = NULL;
            return;
        }
    }
}

void VirtualBus::broadcast(const CanFrame &frame, NativeCanBus *sender) {
    ++traffic_;
    for (size_t i = 0; i < node_count_; ++i) {
        if (nodes_[i] != sender) {
            nodes_[i]->deliver(frame);
        }
    }
}

NativeCanBus::NativeCanBus(VirtualBus *bus)
    : bus_(bus),
      filter_(CanFilter::acceptAll()),
      started_(false),
      bus_off_(false),
      rx_head_(0),
      rx_count_(0),
      sent_count_(0) {}

NativeCanBus::~NativeCanBus() {
    end();
}

CanStatus NativeCanBus::begin(uint32_t bitrate) {
    (void)bitrate;
    if (!started_ && bus_ != NULL) {
        bus_->attach(this);
    }
    started_ = true;
    bus_off_ = false;
    return CAN_OK;
}

void NativeCanBus::end() {
    if (started_ && bus_ != NULL) {
        bus_->detach(this);
    }
    started_ = false;
    rx_head_ = 0;
    rx_count_ = 0;
}

CanStatus NativeCanBus::send(const CanFrame &frame, uint32_t timeout_ms) {
    (void)timeout_ms;
    if (!started_) {
        return CAN_ERR_NOT_STARTED;
    }
    if (bus_off_) {
        return CAN_ERR_BUS_OFF;
    }
    last_sent_ = frame;
    ++sent_count_;
    if (bus_ != NULL) {
        bus_->broadcast(frame, this);
    }
    return CAN_OK;
}

CanStatus NativeCanBus::receive(CanFrame &frame, uint32_t timeout_ms) {
    (void)timeout_ms;
    if (!started_) {
        return CAN_ERR_NOT_STARTED;
    }
    if (rx_count_ == 0) {
        return CAN_ERR_NO_DATA;
    }
    frame = rx_queue_[rx_head_];
    rx_head_ = (rx_head_ + 1) % kNativeQueueSize;
    --rx_count_;
    return CAN_OK;
}

void NativeCanBus::setFilter(const CanFilter &filter) {
    filter_ = filter;
}

bool NativeCanBus::isBusOff() const {
    return bus_off_;
}

CanStatus NativeCanBus::recover() {
    bus_off_ = false;
    return CAN_OK;
}

void NativeCanBus::deliver(const CanFrame &frame) {
    if (!started_ || !filter_.accepts(frame.id)) {
        return;
    }
    if (rx_count_ >= kNativeQueueSize) {
        /* Cola llena: se descarta la trama mas antigua. */
        rx_head_ = (rx_head_ + 1) % kNativeQueueSize;
        --rx_count_;
    }
    rx_queue_[(rx_head_ + rx_count_) % kNativeQueueSize] = frame;
    ++rx_count_;
}

}  // namespace pcd

#endif#pragma once

/*
 * Bus CAN virtual en memoria para pruebas de escritorio (entorno "native").
 * Todas las instancias conectadas a la misma VirtualBus se escuchan entre si,
 * lo que permite validar el lazo comando -> ejecucion -> difusion de estado sin
 * hardware.
 */

#include <stddef.h>

#include "can_protocol.h"

namespace pcd {

class ICanBus;
struct CanFilter;

static const size_t kNativeQueueSize = 32;

class NativeCanBus;

class VirtualBus {
  public:
    VirtualBus();

    void attach(NativeCanBus *node);
    void detach(NativeCanBus *node);

    /* Entrega la trama a todos los nodos conectados excepto el emisor. */
    void broadcast(const CanFrame &frame, NativeCanBus *sender);

    size_t traffic() const { return traffic_; }
    void resetTraffic() { traffic_ = 0; }

  private:
    static const size_t kMaxNodes = 8;
    NativeCanBus *nodes_[kMaxNodes];
    size_t node_count_;
    size_t traffic_;
};

}  // namespace pcd

#include "hal_can.h"

namespace pcd {

class NativeCanBus : public ICanBus {
  public:
    explicit NativeCanBus(VirtualBus *bus = NULL);
    ~NativeCanBus() override;

    CanStatus begin(uint32_t bitrate = CAN_BUS_BITRATE) override;
    void end() override;
    CanStatus send(const CanFrame &frame, uint32_t timeout_ms = 0) override;
    CanStatus receive(CanFrame &frame, uint32_t timeout_ms = 0) override;
    void setFilter(const CanFilter &filter) override;
    bool isBusOff() const override;
    CanStatus recover() override;

    /* Inyecta una trama como si viniese del bus (util en pruebas unitarias). */
    void deliver(const CanFrame &frame);

    /* Ultima trama transmitida y contador de transmisiones. */
    const CanFrame &lastSent() const { return last_sent_; }
    size_t sentCount() const { return sent_count_; }
    size_t pending() const { return rx_count_; }
    void simulateBusOff() { bus_off_ = true; }

  private:
    VirtualBus *bus_;
    CanFilter filter_;
    bool started_;
    bool bus_off_;
    CanFrame rx_queue_[kNativeQueueSize];
    size_t rx_head_;
    size_t rx_count_;
    CanFrame last_sent_;
    size_t sent_count_;
};

}  // namespace pcd#include "routing/route_table.h"

#include <string.h>

#include "config_storage.h"  /* crc16() */

namespace pcd {

void MappingRule::serialize(const MappingRule &rule, uint8_t *out) {
    memset(out, 0, kMappingRuleBytes);
    out[0] = rule.src_protocol;
    writeUint16BE(&out[1], rule.src_id);
    out[3] = rule.src_resource;
    out[4] = rule.src_channel;
    out[5] = rule.dst_protocol;
    writeUint16BE(&out[6], rule.dst_id);
    out[8] = rule.dst_resource;
    out[9] = rule.dst_channel;
    out[10] = rule.dst_action;
    writeUint32BE(&out[11], rule.dst_param);
}

void MappingRule::deserialize(const uint8_t *in, MappingRule &out) {
    out.src_protocol = in[0];
    out.src_id = readUint16BE(&in[1]);
    out.src_resource = in[3];
    out.src_channel = in[4];
    out.dst_protocol = in[5];
    out.dst_id = readUint16BE(&in[6]);
    out.dst_resource = in[8];
    out.dst_channel = in[9];
    out.dst_action = in[10];
    out.dst_param = readUint32BE(&in[11]);
}

RouteTable::RouteTable() : count_(0) {
    for (uint8_t i = 0; i < CAN_MAX_ROUTES; ++i) {
        rules_[i] = MappingRule();
    }
}

bool RouteTable::addRule(const MappingRule &rule) {
    if (count_ >= CAN_MAX_ROUTES) {
        return false;
    }
    rules_[count_++] = rule;
    return true;
}

bool RouteTable::removeRule(uint8_t index) {
    if (index >= count_) {
        return false;
    }
    for (uint8_t i = index; i + 1 < count_; ++i) {
        rules_[i] = rules_[i + 1];
    }
    --count_;
    return true;
}

bool RouteTable::match(const CanonicalFrame &frame, MappingRule &out) const {
    for (uint8_t i = 0; i < count_; ++i) {
        if (rules_[i].matches(frame)) {
            out = rules_[i];
            return true;
        }
    }
    return false;
}

bool RouteTable::serialize(uint8_t *out, uint16_t out_len) const {
    const uint16_t total = static_cast<uint16_t>(2 + 1 + 1 + kMappingRuleBytes * count_ + 2);
    if (out == 0 || out_len < total) {
        return false;
    }
    uint8_t header[4];
    header[0] = kMagic;
    header[1] = kVersion;
    header[2] = count_;
    header[3] = 0;
    memcpy(out, header, 4);

    uint16_t crc = crc16(header, 4);
    uint8_t raw[kMappingRuleBytes];
    for (uint8_t i = 0; i < count_; ++i) {
        MappingRule::serialize(rules_[i], raw);
        memcpy(&out[4 + kMappingRuleBytes * i], raw, kMappingRuleBytes);
        crc = crc16(raw, kMappingRuleBytes, crc);
    }
    writeUint16BE(&out[total - 2], crc);
    return true;
}

bool RouteTable::deserialize(const uint8_t *in, uint16_t in_len) {
    if (in == 0 || in_len < 6) {
        return false;
    }
    if (in[0] != kMagic || in[1] != kVersion) {
        return false;
    }
    const uint8_t count = in[2];
    if (count > CAN_MAX_ROUTES) {
        return false;
    }
    const uint16_t total = static_cast<uint16_t>(4 + kMappingRuleBytes * count + 2);
    if (in_len < total) {
        return false;
    }
    if (readUint16BE(&in[total - 2]) != crc16(in, total - 2)) {
        return false;
    }
    count_ = 0;
    for (uint8_t i = 0; i < count; ++i) {
        MappingRule rule;
        MappingRule::deserialize(&in[4 + kMappingRuleBytes * i], rule);
        rules_[count_++] = rule;
    }
    return true;
}

}  // namespace pcd#pragma once

/*
 * Tabla de mapeo dinamico entre protocolos (Cross-Protocol Mapping Table).
 *
 * Define los enlaces:
 *
 *   (Protocolo A, Origen, Recurso, Canal)  ->  (Protocolo B, Destino, Recurso, Canal, Accion, Param)
 *
 * Ejemplo: "Cuando el teclado KNX 1/1/10 informa pulsacion, accionar el rele
 * del Nodo CAN 0x0016, canal 2".
 *
 * La tabla es agnostica y serializable: la aplicacion puede guardarla en NVS
 * (via ConfigStore), EEPROM o LittleFS. Se usa CRC-16 (el mismo de la
 * persistencia de configuracion) para detectar corrupcion.
 */

#include <stdint.h>

#include "routing/canonical.h"

namespace pcd {

#ifndef CAN_MAX_ROUTES
#define CAN_MAX_ROUTES 16
#endif

/* Anchura de cada regla serializada (2+2+1+1 + 2+1+1+1+1+4 = 20). */
static const uint8_t kMappingRuleBytes = 20;

/* Una regla de mapeo: origen -> destino. */
struct MappingRule {
    /* Origen */
    uint8_t src_protocol;    /* ProtocolSource */
    uint16_t src_id;         /* id segun el protocolo de origen */
    uint8_t src_resource;    /* ResourceType */
    uint8_t src_channel;     /* kAnyChannel = comodin */

    /* Destino */
    uint8_t dst_protocol;    /* ProtocolSource */
    uint16_t dst_id;         /* id segun el protocolo de destino */
    uint8_t dst_resource;    /* ResourceType */
    uint8_t dst_channel;
    uint8_t dst_action;      /* Action */
    uint32_t dst_param;      /* parametro (temporizador, fade, consigna) */

    MappingRule()
        : src_protocol(PROTO_CAN), src_id(0), src_resource(0), src_channel(0),
          dst_protocol(PROTO_CAN), dst_id(0), dst_resource(0), dst_channel(0),
          dst_action(ACT_TOGGLE), dst_param(0) {}

    /* true cuando un CanonicalFrame entrante coincide con este origen. */
    bool matches(const CanonicalFrame &c) const {
        if (src_protocol != c.protocol) return false;
        if (src_id != 0 && src_id != c.source_id) return false;
        if (src_resource != 0 && src_resource != c.resource) return false;
        if (src_channel != 0xFF && src_channel != c.channel) return false;
        return true;
    }

    static void serialize(const MappingRule &rule, uint8_t *out);
    static void deserialize(const uint8_t *in, MappingRule &out);
};

class RouteTable {
  public:
    RouteTable();

    /* Gestion de reglas. Devuelve false si la tabla esta llena. */
    bool addRule(const MappingRule &rule);
    bool removeRule(uint8_t index);
    void clear() { count_ = 0; }

    uint8_t count() const { return count_; }
    const MappingRule &rule(uint8_t index) const { return rules_[index]; }

    /* Busca la primera regla cuyo origen coincide con `frame`. */
    bool match(const CanonicalFrame &frame, MappingRule &out) const;

    /* Serializacion para persistencia. Devuelve los bytes escritos en out. */
    bool serialize(uint8_t *out, uint16_t out_len) const;
    bool deserialize(const uint8_t *in, uint16_t in_len);

    static const uint8_t kMagic = 0xA5;
    static const uint8_t kVersion = 1;

  private:
    MappingRule rules_[CAN_MAX_ROUTES];
    uint8_t count_;
};

}  // namespace pcd#include "routing/routing_engine.h"

#include "system/system_logger.h"

namespace pcd {

RoutingEngine::RoutingEngine(RouteTable &table)
    : table_(table),
      node_(0),
      gateway_node_id_(0),
      sink_(0),
      sink_ctx_(0) {}

void RoutingEngine::attach(CanNode &node, uint16_t gateway_node_id) {
    node_ = &node;
    gateway_node_id_ = gateway_node_id;
}

void RoutingEngine::setSink(CanonicalSink sink, void *ctx) {
    sink_ = sink;
    sink_ctx_ = ctx;
}

void RoutingEngine::onCanFrame(const CanFrame &frame) {
    const CanId id = frame.fields();
    if (id.source == gateway_node_id_) {
        return;  /* no procesar las propias tramas del gateway */
    }
    /* Solo interesan eventos, estados, escenas y heartbeat de otros nodos. */
    if (id.msg_type != MSG_EVENT && id.msg_type != MSG_STATE &&
        id.msg_type != MSG_GROUP && id.msg_type != MSG_HEARTBEAT) {
        return;
    }
    process(CanonicalFrame::fromCanFrame(frame));
}

bool RoutingEngine::process(const CanonicalFrame &frame) {
    MappingRule rule;
    if (!table_.match(frame, rule)) {
        return false;
    }
    execute(rule);
    return true;
}

void RoutingEngine::execute(const MappingRule &rule) {
    /* Construye el frame canonico de destino a partir de la regla. */
    CanonicalFrame dst;
    dst.protocol = rule.dst_protocol;
    dst.source_id = rule.dst_id;
    dst.resource = rule.dst_resource;
    dst.channel = rule.dst_channel;
    dst.action = rule.dst_action;
    dst.param = rule.dst_param;
    dst.is_command = 1;

    switch (rule.dst_protocol) {
        case PROTO_CAN: {
            if (node_ == 0) {
                LOG_ERROR("RoutingEngine: destino CAN pero sin CanNode adjunto");
                return;
            }
            if (rule.dst_id == gateway_node_id_) {
                /* Aplicar localmente en el propio gateway. */
                node_->applyLocal(rule.dst_resource, rule.dst_channel,
                                  rule.dst_action, rule.dst_param);
            } else {
                node_->sendCommand(static_cast<uint8_t>(rule.dst_id & kTargetMask),
                                   rule.dst_resource, rule.dst_channel,
                                   rule.dst_action, rule.dst_param);
            }
            break;
        }

        default:
            /* Entregar a un puente externo (MQTT, Modbus, KNX, ESP-NOW, IP...). */
            if (sink_ != 0) {
                sink_(dst, sink_ctx_);
            } else {
                LOG_ERROR("RoutingEngine: destino no CAN sin sink configurado");
            }
            break;
    }
}

}  // namespace pcd#pragma once

/*
 * Motor de enrutamiento unificado (Core Routing Engine).
 *
 * Es el cerebro del gateway multi-protocolo. Recibe una CanonicalFrame (que
 * puede venir de CAN, ESP-NOW, Modbus, KNX, MQTT o IP), la evalua contra la
 * RouteTable y ejecuta la accion de destino:
 *
 *   - Si el destino es CAN: envia un comando al nodo (o lo aplica localmente).
 *   - Si el destino es otro protocolo: entrega la CanonicalFrame a un sink
 *     (un bridge/traductor externo).
 *
 * No depende de ninguna libreria de red: los puentes se conectan con un
 * callback (setSink()).
 */

#include <stdint.h>

#include "can_node.h"
#include "routing/canonical.h"
#include "routing/route_table.h"

namespace pcd {

class RoutingEngine {
  public:
    explicit RoutingEngine(RouteTable &table);

    /* Engancha el enrutador a un CanNode para observar el trafico CAN.
     * node_id es el Node-ID del propio gateway (para detectar auto-tramas). */
    void attach(CanNode &node, uint16_t gateway_node_id);

    /* Callback de salida hacia un puente (protocolo no CAN). */
    typedef void (*CanonicalSink)(const CanonicalFrame &frame, void *ctx);
    void setSink(CanonicalSink sink, void *ctx);

    /* Punto de entrada: una trama CAN entrante. */
    void onCanFrame(const CanFrame &frame);

    /* Punto de entrada: un evento normalizado (desde un bridge). */
    bool process(const CanonicalFrame &frame);

  private:
    void execute(const MappingRule &rule);

    RouteTable &table_;
    CanNode *node_;
    uint16_t gateway_node_id_;
    CanonicalSink sink_;
    void *sink_ctx_;
};

}  // namespace pcd#include "system/system_api.h"

namespace pcd {

/* Puntero global a la estructura de servicios inyectada por la aplicacion.
 * Se mantiene como puntero (no copia) para que el usuario pueda actualizarla
 * en caliente si lo desea; en la practica se configura una vez en setup(). */

static const SystemApi *g_api = 0;

void setSystemApi(const SystemApi *api) {
    g_api = api;
}

const SystemApi *systemApi() {
    return g_api;
}

time_ms_t systemMillis() {
    const SystemApi *api = systemApi();
    return (api && api->millis) ? api->millis() : 0;
}

void systemDelay(uint32_t ms) {
    const SystemApi *api = systemApi();
    if (api && api->delay_ms) {
        api->delay_ms(ms);
    }
}

}  // namespace pcd#pragma once

/*
 * Capa de servicios del sistema (System Layer API).
 *
 * La libreria base es 100% agnostica al framework: NO incluye <Arduino.h>,
 * no llama a millis(), delay() ni a Serial. En su lugar, la aplicacion
 * inyecta un SystemApi con punteros a las funciones de la plataforma.
 *
 * Mapeo tipico:
 *
 *   Arduino   -> millis(), delay(), una UART por vsnprintf
 *   ESP-IDF   -> esp_timer_get_time()/1000, vTaskDelay(), ESP_LOGV/ESP_LOGI
 *   FreeRTOS  -> xTaskGetTickCount(), vTaskDelay(), printf personalizado
 *   STM32 Cube -> HAL_GetTick(), HAL_Delay(), printf redirigido
 *   PC/native -> std::chrono, std::this_thread::sleep_for, std::printf
 *
 * El protocolo (can_protocol), la capa de nodo (can_node), el gestor de
 * recursos (device_manager), la persistencia (config_storage) y el motor de
 * reglas (rule_engine) dependen solo de esta interfaz para reloj, bloqueo y
 * diagnostico. Ninguna de ellas conoce la placa real.
 */

#include <stdarg.h>
#include <stdint.h>
#include <stddef.h>

namespace pcd {

/* Instante monotono en milisegundos. En AVR la escala es suficiente (49 dias). */
typedef uint32_t time_ms_t;

/* Prioridades de log. Coinciden con los niveles de los macros LOG_*. */
enum LogLevel : uint8_t {
    LOG_LEVEL_ERROR = 1,
    LOG_LEVEL_INFO = 2,
    LOG_LEVEL_DEBUG = 3
};

/*
 * Contrato de servicios que la aplicacion debe proveer.
 *
 *   millis   - reloj monotono en ms (obligatorio)
 *   delay_ms - bloqueo en ms (obligatorio)
 *   log      - sumidero de diagnostico con formato printf + va_list
 *              (opcional; si es 0 se desactivan las trazas)
 *   lock     - entrar en seccion critica (opcional; ver LockGuard)
 *   unlock   - salir de seccion critica (opcional; ver LockGuard)
 *
 * Una funcion de log con va_list permite al cliente formatear en su propia
 * consola (UART secundaria, WebSocket, archivo en SD, Network Logger...)
 * sin que la libreria dependa de un flujo de salida concreto. Cuando
 * CAN_LOG_LEVEL == 0 el compilador elimina por completo las cadenas.
 */
struct SystemApi {
    time_ms_t (*millis)();                          /* monotonic ms */
    void (*delay_ms)(uint32_t ms);                  /* blocking delay */
    void (*log)(uint8_t level, const char *format, va_list args);
    void (*lock)();                                 /* enter critical section */
    void (*unlock)();                               /* exit critical section */

    SystemApi() : millis(0), delay_ms(0), log(0), lock(0), unlock(0) {}

    bool hasTime() const { return millis != 0 && delay_ms != 0; }
    bool hasLog() const { return log != 0; }
    bool hasLock() const { return lock != 0 && unlock != 0; }
};

/*
 * API global de sistema. La aplicacion la configura una vez en setup():
 *
 *   static pcd::SystemApi api;
 *   api.millis = millis;
 *   api.delay_ms = [](uint32_t ms) { delay(ms); };
 *   api.log = myLogSink;
 *   pcd::setSystemApi(&api);
 *
 * Los nodos y los drivers creados despues leen punteros desde esta estructura
 * cada vez que necesitan un reloj o un log, de modo que no hay estado global
 * de tiempo copiado en cada objeto.
 */

void setSystemApi(const SystemApi *api);
const SystemApi *systemApi();

/* Accesos convenientes con bloqueo "intento de no romper nada". */
time_ms_t systemMillis();
void systemDelay(uint32_t ms);

}  // namespace pcd#pragma once

/*
 * Abstraccion avanzada de concurrencia (Thread-Safety).
 *
 * Protege las secciones criticas de la libreria (colas de transmision y
 * recepcion, acceso a EEPROM/NVS, tablas de suscripciones) segun el entorno:
 *
 *   - AVR 8-bit monocore -> cli()/sei() breves (no hay RTOS, y cualquier
 *     condicion de carrera se elimina enmascarando interrupciones).
 *   - ESP32 / RTOS        -> el usuario inyecta lock()/unlock() en SystemApi
 *     (semafaros o portENTER_CRITICAL) para proteger colas entre ISRs.
 *   - Bare-metal single-thread / PC -> no-op.
 *
 * Prioridad del guard:
 *   1. Si SystemApi provee lock/unlock, usa esos callbacks (framework
 *      agnostico, adecuado para ESP-IDF, FreeRTOS, Zephyr, etc.).
 *   2. Si no, en AVR cae a cli()/sei(); en el resto no hace nada.
 *
 * Uso:
 *   {
 *       LockGuard lock;   // entra en seccion critica
 *       rxQueue_.push(frame);
 *   }                     // sale automaticamente
 */

#include "system_api.h"

#if defined(__AVR__)
#include <avr/io.h>
#include <avr/interrupt.h>
#endif

namespace pcd {

class LockGuard {
  public:
    LockGuard()
        : lock_fn_(0),
          unlock_fn_(0),
          custom_(false)
#if defined(__AVR__)
          ,
          saved_sreg_(0)
#endif
    {
        const SystemApi *api = systemApi();
        if (api && api->hasLock()) {
            lock_fn_ = api->lock;
            unlock_fn_ = api->unlock;
            if (lock_fn_ != 0) {
                lock_fn_();
            }
            custom_ = true;
        } else {
#if defined(__AVR__)
            saved_sreg_ = SREG;
            cli();
#endif
        }
    }

    ~LockGuard() {
        if (custom_ && unlock_fn_ != 0) {
            unlock_fn_();
        } else {
#if defined(__AVR__)
            SREG = saved_sreg_;
#endif
        }
    }

    LockGuard(const LockGuard &) = delete;
    LockGuard &operator=(const LockGuard &) = delete;

  private:
    void (*lock_fn_)();
    void (*unlock_fn_)();
    bool custom_;
#if defined(__AVR__)
    uint8_t saved_sreg_;
#endif
};

}  // namespace pcd#pragma once

/*
 * Motor de registro inyectable (Custom Logger).
 *
 * Reemplaza las llamadas directas a Serial.print() por un sumidero de
 * diagnostico configurable por la aplicacion:
 *
 *   - un UART secundario,
 *   - la consola WebSocket del Gateway,
 *   - un archivo de texto en una tarjeta SD,
 *   - un logger de red,
 *   - o la desactivacion total (CAN_LOG_LEVEL == 0) para maximizar el
 *     rendimiento en microcontroladores con poca memoria Flash.
 *
 * El nivel de compilacion (CAN_LOG_LEVEL) decide si las cadenas entran o no
 * al binario. En produccion (0) el compilador elimina TODO, sin dejar ni un
 * string de trazas en Flash.
 *
 * Uso tipico (Arduino):
 *
 *   void myLog(uint8_t level, const char *format, va_list args) {
 *       char buf[128];
 *       vsnprintf(buf, sizeof(buf), format, args);
 *       Serial2.println(buf);
 *   }
 *
 *   static pcd::SystemApi api;
 *   api.millis = millis;
 *   api.delay_ms = [](uint32_t ms) { delay(ms); };
 *   api.log = myLog;
 *   pcd::setSystemApi(&api);
 */

#include <stdarg.h>

#include "system/system_api.h"

#ifndef CAN_LOG_LEVEL
#define CAN_LOG_LEVEL 0
#endif

namespace pcd {

/* Sumidero de mensajes. Se ejecuta solo si CAN_LOG_LEVEL >= nivel. */
inline void logMessage(uint8_t level, const char *format, ...) {
    const SystemApi *api = systemApi();
    if (api && api->log) {
        va_list args;
        va_start(args, format);
        api->log(level, format, args);
        va_end(args);
    }
}

}  // namespace pcd

/* Macro de nivel ERROR. `__VA_ARGS__` incluye la cadena de formato y los
 * argumentos, de modo que no se necesita el truco `##__VA_ARGS__` de GCC. */
#define LOG_ERROR(...)                                              \
    do {                                                            \
        if (CAN_LOG_LEVEL >= 1) {                                   \
            ::pcd::logMessage(::pcd::LOG_LEVEL_ERROR, __VA_ARGS__); \
        }                                                           \
    } while (0)

#define LOG_INFO(...)                                               \
    do {                                                            \
        if (CAN_LOG_LEVEL >= 2) {                                   \
            ::pcd::logMessage(::pcd::LOG_LEVEL_INFO, __VA_ARGS__);  \
        }                                                           \
    } while (0)

#define LOG_DEBUG(...)                                              \
    do {                                                            \
        if (CAN_LOG_LEVEL >= 3) {                                   \
            ::pcd::logMessage(::pcd::LOG_LEVEL_DEBUG, __VA_ARGS__); \
        }                                                           \
    } while (0)#include "tunnel/tunnel_engine.h"

#include <string.h>

#include "config_storage.h"  /* crc16() */

namespace pcd {

static const size_t kTunnelHeaderBytes = 6;  /* magia + id + dlc */
static const size_t kTunnelPayloadMax = 8;

bool encodeTunnelFrame(const CanFrame &frame, uint8_t *out, size_t out_len) {
    if (out_len < kTunnelDatagramBytes || out == 0) {
        return false;
    }
    memset(out, 0, kTunnelDatagramBytes);

    out[0] = kTunnelMagic;
    out[1] = static_cast<uint8_t>(frame.id & 0xFF);
    out[2] = static_cast<uint8_t>((frame.id >> 8) & 0xFF);
    out[3] = static_cast<uint8_t>((frame.id >> 16) & 0xFF);
    out[4] = static_cast<uint8_t>((frame.id >> 24) & 0xFF);

    const uint8_t dlc = (frame.dlc > kTunnelPayloadMax) ? kTunnelPayloadMax : frame.dlc;
    out[5] = frame.dlc & 0x0F;

    memcpy(&out[6], frame.data, dlc);

    const uint16_t crc = crc16(out, kTunnelHeaderBytes + dlc);
    out[14] = static_cast<uint8_t>(crc & 0xFF);
    out[15] = static_cast<uint8_t>((crc >> 8) & 0xFF);
    return true;
}

bool decodeTunnelFrame(const uint8_t *in, size_t in_len, CanFrame &frame) {
    if (in == 0 || in_len != kTunnelDatagramBytes) {
        return false;
    }
    if (in[0] != kTunnelMagic) {
        return false;
    }
    const uint8_t dlc = in[5] & 0x0F;
    if (dlc > kTunnelPayloadMax) {
        return false;
    }

    const uint16_t expected_crc = crc16(in, kTunnelHeaderBytes + dlc);
    const uint16_t stored_crc = static_cast<uint16_t>(in[14]) |
                                (static_cast<uint16_t>(in[15]) << 8);
    if (expected_crc != stored_crc) {
        return false;
    }

    frame.id = static_cast<uint32_t>(in[1]) | (static_cast<uint32_t>(in[2]) << 8) |
               (static_cast<uint32_t>(in[3]) << 16) | (static_cast<uint32_t>(in[4]) << 24);
    frame.id &= kExtendedIdMask;
    frame.dlc = dlc;
    memset(frame.data, 0, sizeof(frame.data));
    memcpy(frame.data, &in[6], dlc);
    return true;
}

TunnelEngine::TunnelEngine(ITunnelTransport &transport) : transport_(transport) {}

bool TunnelEngine::sendFrame(uint16_t peer, const CanFrame &frame) {
    uint8_t datagram[kTunnelDatagramBytes];
    if (!encodeTunnelFrame(frame, datagram, sizeof(datagram))) {
        return false;
    }
    return transport_.send(peer, datagram, sizeof(datagram));
}

bool TunnelEngine::receiveFrame(uint16_t &peer_out, CanFrame &frame) {
    uint8_t datagram[kTunnelDatagramBytes];
    uint16_t peer = kBroadcastPeer;
    size_t len = 0;
    if (!transport_.receive(peer, datagram, sizeof(datagram), len)) {
        return false;
    }
    if (!decodeTunnelFrame(datagram, len, frame)) {
        /* Datagrama corrupto o ajeno: se descarta. */
        return false;
    }
    peer_out = peer;
    return true;
}

bool TunnelEngine::available() const {
    return transport_.available();
}

}  // namespace pcd#pragma once

/*
 * Motor de tunel CAN-sobre-IP.
 *
 * Empaqueta/desempaqueta tramas del protocolo PCD en datagramas de 16 bytes
 * aptos para UDP/TCP, de modo que la libreria pueda enrutar tramas entre buses
 * CAN remotos sin conocer el stack IP.
 *
 * Formato del datagrama (little-endian):
 *
 *   byte  0      magia 0xA5
 *   bytes 1..4   ID extendido de 29 bits, LSB primero
 *   byte  5      DLC (0..8)
 *   bytes 6..13  payload (8 bytes)
 *   bytes 14..15 CRC-16/CCITT de los bytes 0..13
 *
 * El receptor descarta datagramas con magia incorrecta, DLC invalido o CRC
 * erroneo, evitando que una corrupcion de red se propague al bus CAN.
 */

#include <stddef.h>
#include <stdint.h>

#include "can_protocol.h"
#include "tunnel/tunnel_transport.h"

namespace pcd {

static const uint8_t kTunnelMagic = 0xA5;
static const size_t kTunnelDatagramBytes = 16;  /* 1 + 4 + 1 + 8 + 2 */

/* Codifica una trama CAN en un datagrama de kTunnelDatagramBytes bytes.
 * Devuelve false si out_len es menor que el tamano del datagrama. */
bool encodeTunnelFrame(const CanFrame &frame, uint8_t *out, size_t out_len);

/* Decodifica un datagrama (que debe medir exactamente kTunnelDatagramBytes)
 * en una trama CAN. Valida magia, DLC y CRC. */
bool decodeTunnelFrame(const uint8_t *in, size_t in_len, CanFrame &frame);

class TunnelEngine {
  public:
    explicit TunnelEngine(ITunnelTransport &transport);

    /* Envia una trama al peer remoto (o broadcast si peer == kBroadcastPeer). */
    bool sendFrame(uint16_t peer, const CanFrame &frame);

    /* Recolecta un datagrama pendiente, lo decodifica y devuelve la trama con
     * el peer emisor. Devuelve false si no hay datos validos. */
    bool receiveFrame(uint16_t &peer_out, CanFrame &frame);

    /* true cuando hay al menos un datagrama pendiente. */
    bool available() const;

  private:
    ITunnelTransport &transport_;
};

}  // namespace pcd#include "tunnel/tunnel_relay_guard.h"

#include <string.h>

namespace pcd {

TunnelRelayGuard::TunnelRelayGuard(uint8_t local_segment)
    : local_segment_(local_segment), window_ms_(5000), next_slot_(0) {
    clear();
}

void TunnelRelayGuard::clear() {
    memset(entries_, 0, sizeof(entries_));
    next_slot_ = 0;
}

uint32_t TunnelRelayGuard::fingerprint(const CanFrame &frame) const {
    uint32_t hash = 2166136261UL;
    hash ^= frame.id;
    hash *= 16777619UL;
    hash ^= frame.dlc;
    hash *= 16777619UL;
    for (uint8_t i = 0; i < frame.dlc && i < kPayloadSize; ++i) {
        hash ^= frame.data[i];
        hash *= 16777619UL;
    }
    return hash;
}

bool TunnelRelayGuard::accept(uint8_t source_segment, const CanFrame &frame,
                              uint32_t now_ms) {
    if (source_segment == local_segment_) {
        return false;
    }

    const uint32_t frame_fingerprint = fingerprint(frame);
    for (uint8_t i = 0; i < CAN_TUNNEL_REPLAY_SLOTS; ++i) {
        Entry &entry = entries_[i];
        if (!entry.valid) {
            continue;
        }
        if ((now_ms - entry.seen_ms) >= window_ms_) {
            entry.valid = false;
            continue;
        }
        if (entry.fingerprint == frame_fingerprint &&
            entry.source_segment == source_segment) {
            return false;
        }
    }

    Entry &slot = entries_[next_slot_];
    slot.fingerprint = frame_fingerprint;
    slot.seen_ms = now_ms;
    slot.source_segment = source_segment;
    slot.valid = true;
    next_slot_ = static_cast<uint8_t>((next_slot_ + 1) % CAN_TUNNEL_REPLAY_SLOTS);
    return true;
}

}  // namespace pcd#pragma once

#include <stdint.h>

#include "can_protocol.h"

namespace pcd {

#ifndef CAN_TUNNEL_REPLAY_SLOTS
#define CAN_TUNNEL_REPLAY_SLOTS 16
#endif

/*
 * Politica local de relay: evita reenviar la misma trama dentro de una
 * ventana de tiempo y recuerda el segmento de origen. No altera el datagrama
 * PCD de 16 bytes ni reemplaza autenticacion criptografica.
 */
class TunnelRelayGuard {
  public:
    explicit TunnelRelayGuard(uint8_t local_segment = 0);

    /* true si la trama puede entrar a este segmento. */
    bool accept(uint8_t source_segment, const CanFrame &frame, uint32_t now_ms);
    void clear();
    void setWindow(uint32_t window_ms) { window_ms_ = window_ms; }
    uint8_t localSegment() const { return local_segment_; }

  private:
    struct Entry {
        uint32_t fingerprint;
        uint32_t seen_ms;
        uint8_t source_segment;
        bool valid;
    };

    uint32_t fingerprint(const CanFrame &frame) const;
    uint8_t local_segment_;
    uint32_t window_ms_;
    uint8_t next_slot_;
    Entry entries_[CAN_TUNNEL_REPLAY_SLOTS];
};

}  // namespace pcd#include "tunnel/udp_tunnel_transport.h"

#include <string.h>

namespace pcd {

UdpTunnelTransport::UdpTunnelTransport() : head_(0), count_(0) {
    for (size_t i = 0; i < kMaxDatagrams; ++i) {
        queue_[i].peer = 0;
        queue_[i].len = 0;
        memset(queue_[i].data, 0, sizeof(queue_[i].data));
    }
}

bool UdpTunnelTransport::enqueue(uint16_t peer, const uint8_t *data, size_t len) {
    if (data == 0 || len == 0 || len > kMaxPayload || count_ >= kMaxDatagrams) {
        return false;
    }

    const size_t index = (head_ + count_) % kMaxDatagrams;
    queue_[index].peer = peer;
    queue_[index].len = len;
    memcpy(queue_[index].data, data, len);
    ++count_;
    return true;
}

bool UdpTunnelTransport::send(uint16_t peer, const uint8_t *data, size_t len) {
    return enqueue(peer, data, len);
}

bool UdpTunnelTransport::receive(uint16_t &peer_out, uint8_t *data, size_t max_len,
                                size_t &len) {
    if (count_ == 0 || data == 0) {
        return false;
    }

    Datagram &datagram = queue_[head_];
    peer_out = datagram.peer;
    len = datagram.len;

    if (len > max_len) {
        len = max_len;
    }

    memcpy(data, datagram.data, len);

    datagram.peer = 0;
    datagram.len = 0;
    memset(datagram.data, 0, sizeof(datagram.data));

    head_ = (head_ + 1) % kMaxDatagrams;
    --count_;
    return true;
}

bool UdpTunnelTransport::available() const {
    return count_ > 0;
}

}  // namespace pcd#pragma once

/*
 * Implementacion concreta de referencia para un transporte de datagramas
 * CAN-over-IP sin acoplar ninguna libreria de red.
 *
 * Sirve como adaptador base para stacks reales (WiFi UDP, Ethernet, TCP,
 * sockets nativos, etc.) y como cola de prueba para el entorno "native".
 */

#include <stddef.h>
#include <stdint.h>

#include "tunnel/tunnel_transport.h"

namespace pcd {

class UdpTunnelTransport : public ITunnelTransport {
  public:
    static const size_t kMaxDatagrams = 16;
    static const size_t kMaxPayload = 64;

    UdpTunnelTransport();

    /* Encola un datagrama recibido desde la red hacia la capa de tunel. */
    bool enqueue(uint16_t peer, const uint8_t *data, size_t len);

    bool send(uint16_t peer, const uint8_t *data, size_t len) override;
    bool receive(uint16_t &peer_out, uint8_t *data, size_t max_len,
                 size_t &len) override;
    bool available() const override;

  private:
    struct Datagram {
        uint16_t peer;
        uint8_t data[kMaxPayload];
        size_t len;
    };

    Datagram queue_[kMaxDatagrams];
    size_t head_;
    size_t count_;
};

}  // namespace pcd#pragma once

