/*
 * Nodo CAN con asignacion estatica en tiempo de compilacion.
 *
 * El requisito de "Sistema de Plantillas C++ para la Asignacion Estatica" se
 * materializa aqui: la misma clase instancia un búfer de tramas de tamano
 * configurable por template, sin usar malloc/new.
 *
 *   // Nodo compacto en ATmega328P: 4 tramas de RX
 *   CanNodeTmpl<4> node(bus, 0x0016);
 *
 *   // Gateway ESP32: 64 tramas de RX para rafagas de alta velocidad
 *   CanNodeTmpl<64> gateway(bus, 0x0001);
 *
 * La plantilla compone el CanNode existente (logica de protocolo, recursos y
 * suscripciones) con un RingBuffer SPSC, de modo que la ISR solo deposita la
 * trama (enqueueFrame) y el bucle principal la procesa en poll().
 */

#include "can_node.h"
#include "core/ring_buffer.h"

namespace pcd {

template <size_t RxDepth>
class CanNodeTmpl {
  public:
    CanNodeTmpl(ICanBus &bus, uint16_t node_id) : node_(bus, node_id) {}

    /* --- Delegacion completa de la interfaz CanNode --- */
    CanStatus begin(uint32_t bitrate = CAN_BUS_BITRATE) { return node_.begin(bitrate); }
    uint16_t nodeId() const { return node_.nodeId(); }
    uint8_t address() const { return node_.address(); }

    bool registerResource(uint8_t resource, uint8_t channel, ResourceHandler handler,
                          void *ctx = 0) {
        return node_.registerResource(resource, channel, handler, ctx);
    }

    DeviceManager &devices() { return node_.devices(); }
    const DeviceManager &devices() const { return node_.devices(); }

    bool subscribe(uint16_t source, uint8_t resource, uint8_t channel,
                   StateListener listener, void *ctx = 0) {
        return node_.subscribe(source, resource, channel, listener, ctx);
    }

    void onConfig(ConfigListener listener, void *ctx = 0) { node_.onConfig(listener, ctx); }
    void onAnyFrame(FrameListener listener, void *ctx = 0) { node_.onAnyFrame(listener, ctx); }

    /* --- Lado ISR: depositar la trama leida del controlador --- */
    bool enqueueFrame(const CanFrame &frame) { return rx_.push(frame); }

    /* --- Lado main-loop: drenar el ring buffer y procesarla --- */
    void poll(uint32_t now_ms) {
        CanFrame frame;
        while (rx_.pop(frame)) {
            node_.handleFrame(frame);
        }
        node_.poll(now_ms);
    }

    CanNode &inner() { return node_; }
    const CanNode &inner() const { return node_; }

    size_t pendingFrames() const { return rx_.count(); }
    size_t rxCapacity() const { return RxDepth; }

  private:
    CanNode node_;
    RingBuffer<CanFrame, RxDepth> rx_;
};

}  // namespace pcd#include "device_manager.h"

namespace pcd {

uint32_t packSetValue(uint16_t value, uint16_t fade_ms) {
    return (static_cast<uint32_t>(value) << 16) | fade_ms;
}

uint16_t unpackSetValueTarget(uint32_t param) {
    return static_cast<uint16_t>((param >> 16) & 0xFFFF);
}

uint16_t unpackSetValueFade(uint32_t param) {
    return static_cast<uint16_t>(param & 0xFFFF);
}

DeviceManager::DeviceManager() : count_(0), emitter_(0), emitter_ctx_(0) {}

bool DeviceManager::registerChannel(uint8_t resource, uint8_t channel, ResourceHandler handler,
                                    void *ctx) {
    if (count_ >= CAN_MAX_CHANNELS || handler == 0) {
        return false;
    }
    Channel &entry = channels_[count_++];
    entry.resource = resource;
    entry.channel = channel;
    entry.handler = handler;
    entry.ctx = ctx;
    entry.value = 0.0f;
    entry.start_value = 0.0f;
    entry.target_value = 0.0f;
    entry.flags = DIAG_NONE;
    entry.phase = PHASE_IDLE;
    entry.phase_started = false;
    entry.start_ms = 0;
    entry.duration_ms = 0;
    return true;
}

Channel *DeviceManager::find(uint8_t resource, uint8_t channel) {
    for (uint8_t i = 0; i < count_; ++i) {
        if (channels_[i].resource == resource &&
            (channels_[i].channel == channel || channels_[i].channel == kAnyChannel)) {
            return &channels_[i];
        }
    }
    return 0;
}

const Channel *DeviceManager::find(uint8_t resource, uint8_t channel) const {
    return const_cast<DeviceManager *>(this)->find(resource, channel);
}

void DeviceManager::setStateEmitter(StateEmitter emitter, void *ctx) {
    emitter_ = emitter;
    emitter_ctx_ = ctx;
}

bool DeviceManager::drive(Channel &entry, uint8_t channel, uint8_t action, uint32_t param,
                          float &out_value) {
    float value = entry.value;
    if (!entry.handler(channel, action, param, value, entry.ctx)) {
        return false;
    }
    entry.value = value;
    out_value = value;
    return true;
}

void DeviceManager::cancelPending(uint8_t resource, uint8_t channel) {
    Channel *entry = find(resource, channel);
    if (entry != 0) {
        entry->phase = PHASE_IDLE;
        entry->phase_started = false;
    }
}

bool DeviceManager::apply(uint8_t resource, uint8_t channel, uint8_t action, uint32_t param,
                          float &out_value) {
    Channel *entry = find(resource, channel);
    if (entry == 0) {
        return false;
    }
    entry->phase = PHASE_IDLE;
    entry->phase_started = false;

    if (action == ACT_SET_VALUE) {
        const uint16_t fade_ms = unpackSetValueFade(param);
        if (fade_ms == 0) {
            return drive(*entry, channel, ACT_SET_VALUE, param, out_value);
        }
        /* Rampa no bloqueante: el valor converge dentro de update(). */
        entry->start_value = entry->value;
        entry->target_value = static_cast<float>(unpackSetValueTarget(param));
        entry->duration_ms = fade_ms;
        entry->phase = PHASE_RAMPING;
        out_value = entry->value;
        return true;
    }

    if (!drive(*entry, channel, action, param, out_value)) {
        return false;
    }

    /* param actua como temporizador de apagado automatico en ON / TOGGLE. */
    if (param > 0 && out_value != 0.0f && (action == ACT_ON || action == ACT_TOGGLE)) {
        entry->phase = PHASE_TIMED;
        entry->duration_ms = param;
    }
    return true;
}

void DeviceManager::update(uint32_t now_ms) {
    for (uint8_t i = 0; i < count_; ++i) {
        Channel &entry = channels_[i];
        if (entry.phase == PHASE_IDLE) {
            continue;
        }
        if (!entry.phase_started) {
            entry.phase_started = true;
            entry.start_ms = now_ms;
            continue;
        }

        const uint32_t elapsed = now_ms - entry.start_ms;

        if (entry.phase == PHASE_RAMPING) {
            const bool finished = elapsed >= entry.duration_ms;
            const float ratio =
                finished ? 1.0f
                         : static_cast<float>(elapsed) / static_cast<float>(entry.duration_ms);
            const float value =
                entry.start_value + (entry.target_value - entry.start_value) * ratio;

            float applied = value;
            const uint32_t param = packSetValue(static_cast<uint16_t>(value), 0);
            if (!drive(entry, entry.channel, ACT_SET_VALUE, param, applied)) {
                entry.phase = PHASE_IDLE;
                continue;
            }
            if (finished) {
                entry.phase = PHASE_IDLE;
                if (emitter_ != 0) {
                    emitter_(entry.resource, entry.channel, applied, entry.flags, emitter_ctx_);
                }
            }
            continue;
        }

        if (entry.phase == PHASE_TIMED && elapsed >= entry.duration_ms) {
            float applied = entry.value;
            entry.phase = PHASE_IDLE;
            if (drive(entry, entry.channel, ACT_OFF, 0, applied) && emitter_ != 0) {
                emitter_(entry.resource, entry.channel, applied, entry.flags, emitter_ctx_);
            }
        }
    }
}

void DeviceManager::setFlags(uint8_t resource, uint8_t channel, uint16_t flags) {
    Channel *entry = find(resource, channel);
    if (entry != 0) {
        entry->flags = flags;
    }
}

uint16_t DeviceManager::flags(uint8_t resource, uint8_t channel) const {
    const Channel *entry = find(resource, channel);
    return (entry == 0) ? static_cast<uint16_t>(DIAG_NONE) : entry->flags;
}

bool DeviceManager::value(uint8_t resource, uint8_t channel, float &out_value) const {
    const Channel *entry = find(resource, channel);
    if (entry == 0) {
        return false;
    }
    out_value = entry->value;
    return true;
}

}  // namespace pcd#pragma once

/*
 * Gestor de recursos heterogeneos de un nodo (Device Manager).
 *
 * Un nodo no es "un interruptor": agrupa canales de distinto tipo bajo un mismo
 * Node-ID y el protocolo direcciona la terna (Node-ID, Tipo de Recurso, Canal).
 *
 * Cada canal se administra con una maquina de estados propia y no bloqueante:
 * los temporizadores de apagado y las rampas de dimmer avanzan en update() sin
 * usar delay(). Toda la memoria es estatica (sin malloc/new) para no fragmentar
 * el heap en AVR.
 */

#include <stdint.h>

#include "can_protocol.h"
#include "system_config.h"

namespace pcd {

static const uint8_t kAnyChannel = 0xFF;

#ifndef CAN_MAX_CHANNELS
#define CAN_MAX_CHANNELS CAN_MAX_SUBSCRIPTIONS
#endif

/*
 * Manejador fisico de un canal. Recibe la accion y el parametro ya decodificados
 * y debe aplicar el cambio sobre el hardware, devolviendo en out_value el valor
 * resultante (1.0 rele encendido, 0..100 dimmer, posicion de cortina, ...).
 * Devolver false rechaza el comando y evita la difusion de estado.
 */
typedef bool (*ResourceHandler)(uint8_t channel, uint8_t action, uint32_t param, float &out_value,
                                void *ctx);

/* Emisor de estado usado por el gestor cuando un canal cambia solo (temporizador,
 * rampa de dimmer) y hay que cerrar el lazo de realimentacion. */
typedef void (*StateEmitter)(uint8_t resource, uint8_t channel, float value, uint16_t flags,
                             void *ctx);

enum ChannelPhase : uint8_t {
    PHASE_IDLE = 0,   /* valor estable                                   */
    PHASE_RAMPING,    /* transicion progresiva hacia target_value        */
    PHASE_TIMED       /* valor estable con apagado automatico programado */
};

struct Channel {
    uint8_t resource;
    uint8_t channel;
    ResourceHandler handler;
    void *ctx;

    float value;          /* valor actual del recurso                       */
    float start_value;    /* valor al comenzar la rampa                     */
    float target_value;   /* destino de la rampa en curso                   */
    uint16_t flags;       /* banderas de diagnostico del canal              */
    uint8_t phase;
    bool phase_started;   /* la fase ya tomo su referencia temporal         */
    uint32_t start_ms;    /* instante en que arranco la fase                */
    uint32_t duration_ms; /* duracion de la rampa o del temporizador        */
};

class DeviceManager {
  public:
    DeviceManager();

    /* Registra un canal fisico. channel == kAnyChannel acepta cualquier indice. */
    bool registerChannel(uint8_t resource, uint8_t channel, ResourceHandler handler,
                         void *ctx = 0);

    Channel *find(uint8_t resource, uint8_t channel);
    const Channel *find(uint8_t resource, uint8_t channel) const;

    /*
     * Aplica un comando sobre un canal local.
     *
     *   ACT_ON / ACT_OFF / ACT_TOGGLE : param = temporizador de apagado en ms (0 = sin limite)
     *   ACT_SET_VALUE                 : param = valor << 16 | tiempo de fade en ms
     *
     * Devuelve true si el canal existe y el manejador acepto el comando; en ese
     * caso out_value contiene el valor resultante.
     */
    bool apply(uint8_t resource, uint8_t channel, uint8_t action, uint32_t param,
               float &out_value);

    /* Cancela la rampa o el temporizador pendiente de un canal. */
    void cancelPending(uint8_t resource, uint8_t channel);

    /* Avanza las maquinas de estado (rampas y temporizadores). Emite estado por
     * cada cambio autonomo a traves del StateEmitter registrado. */
    void update(uint32_t now_ms);

    void setStateEmitter(StateEmitter emitter, void *ctx);

    /* Marca banderas de diagnostico de un canal (error de sensor, sobretemperatura). */
    void setFlags(uint8_t resource, uint8_t channel, uint16_t flags);
    uint16_t flags(uint8_t resource, uint8_t channel) const;

    bool value(uint8_t resource, uint8_t channel, float &out_value) const;
    uint8_t count() const { return count_; }
    const Channel &at(uint8_t index) const { return channels_[index]; }

  private:
    bool drive(Channel &entry, uint8_t channel, uint8_t action, uint32_t param, float &out_value);

    Channel channels_[CAN_MAX_CHANNELS];
    uint8_t count_;
    StateEmitter emitter_;
    void *emitter_ctx_;
};

/* Empaqueta valor y tiempo de fade en el parametro de ACT_SET_VALUE. */
uint32_t packSetValue(uint16_t value, uint16_t fade_ms);
uint16_t unpackSetValueTarget(uint32_t param);
uint16_t unpackSetValueFade(uint32_t param);

}  // namespace pcd#pragma once

/*
 * Abstraccion de la capa fisica del bus CAN.
 *
 *   ESP32  -> controlador TWAI integrado
 *   AVR    -> MCP2515 sobre SPI
 *   native -> implementacion en memoria para pruebas unitarias de escritorio
 *
 * Toda la logica del ecosistema depende unicamente de ICanBus, de modo que el
 * mismo codigo de aplicacion compila en cualquiera de las plataformas.
 */

#include <stdint.h>

#include "can_protocol.h"
#include "system_config.h"

namespace pcd {

enum CanStatus : uint8_t {
    CAN_OK = 0,
    CAN_ERR_INIT,
    CAN_ERR_TX_FAIL,
    CAN_ERR_TX_BUSY,
    CAN_ERR_NO_DATA,
    CAN_ERR_BUS_OFF,
    CAN_ERR_NOT_STARTED
};

/*
 * Filtro de aceptacion aplicado sobre el identificador de 29 bits.
 * Se acepta la trama cuando (id & mask) == (match & mask).
 */
struct CanFilter {
    uint32_t match;
    uint32_t mask;

    CanFilter() : match(0), mask(0) {}
    CanFilter(uint32_t m, uint32_t k) : match(m), mask(k) {}

    bool accepts(uint32_t id) const { return (id & mask) == (match & mask); }

    /* Acepta solo tramas dirigidas al nodo indicado y los broadcast. */
    static CanFilter forTarget(uint8_t target) {
        return CanFilter(static_cast<uint32_t>(target & kTargetMask) << kTargetShift,
                         kTargetMask << kTargetShift);
    }

    /* Acepta solo un tipo de mensaje (heartbeat, OTA, estado, ...). */
    static CanFilter forMsgType(uint8_t msg_type) {
        return CanFilter(static_cast<uint32_t>(msg_type & kMsgTypeMask) << kMsgTypeShift,
                         kMsgTypeMask << kMsgTypeShift);
    }

    static CanFilter acceptAll() { return CanFilter(0, 0); }
};

class ICanBus {
  public:
    virtual ~ICanBus() {}

    /* Inicializa el controlador con la velocidad indicada en bits por segundo. */
    virtual CanStatus begin(uint32_t bitrate = CAN_BUS_BITRATE) = 0;
    virtual void end() = 0;

    /* Transmite una trama extendida; timeout_ms = 0 significa no bloqueante. */
    virtual CanStatus send(const CanFrame &frame, uint32_t timeout_ms = 0) = 0;

    /* Extrae la siguiente trama recibida. Devuelve CAN_ERR_NO_DATA si no hay. */
    virtual CanStatus receive(CanFrame &frame, uint32_t timeout_ms = 0) = 0;

    /* Filtro de hardware/software aplicado a la recepcion. */
    virtual void setFilter(const CanFilter &filter) = 0;

    /* true cuando el controlador entro en estado bus-off y requiere recuperacion. */
    virtual bool isBusOff() const = 0;

    /* Intenta recuperar el controlador tras un bus-off. */
    virtual CanStatus recover() = 0;
};

}  // namespace pcd

#if defined(ARDUINO_ARCH_ESP32)
#include "hal/hal_can_esp32.h"
#elif defined(__AVR__)
#include "hal/hal_can_mcp2515.h"
#else
#include "hal/hal_can_native.h"
#endif#include "ota_manager.h"

#include "config_storage.h"

namespace pcd {

OtaManager::OtaManager(uint16_t source, uint8_t target)
    : source_(source),
      target_(target),
      image_(0),
      image_size_(0),
      offset_(0),
      crc_(0xFFFF),
      state_(OTA_STATE_IDLE),
      version_major_(0),
      version_minor_(0),
      hardware_id_(0) {}

bool OtaManager::begin(const uint8_t *image, size_t image_size) {
    if (image == 0 || image_size == 0 || image_size > kMaxImageBytes ||
        !isValidSource(source_) || !isValidTarget(target_)) {
        state_ = OTA_STATE_ABORTED;
        return false;
    }

    image_ = image;
    image_size_ = image_size;
    offset_ = 0;
    crc_ = crc16(image_, static_cast<uint16_t>(image_size_));
    state_ = OTA_STATE_STREAMING;
    return true;
}

bool OtaManager::nextFrame(CanFrame &out) {
    if (state_ != OTA_STATE_STREAMING || offset_ >= image_size_) {
        return false;
    }

    const size_t remaining = image_size_ - offset_;
    const uint8_t chunk_size = static_cast<uint8_t>(
        remaining > kBytesPerFrame ? kBytesPerFrame : remaining);
    const uint8_t sequence = static_cast<uint8_t>(offset_ / kBytesPerFrame);
    out = makeOtaData(source_, target_, sequence, &image_[offset_], chunk_size);
    offset_ += chunk_size;

    if (offset_ == image_size_) {
        state_ = OTA_STATE_COMPLETE;
    }
    return true;
}

void OtaManager::setFirmwareInfo(uint8_t version_major, uint8_t version_minor, uint8_t hardware_id) {
    version_major_ = version_major;
    version_minor_ = version_minor;
    hardware_id_ = hardware_id;
}

CanFrame OtaManager::startFrame() const {
    uint8_t payload[6];
    payload[0] = version_major_;
    payload[1] = version_minor_;
    writeUint32BE(&payload[2], static_cast<uint32_t>(image_size_));
    return makeOtaControl(source_, target_, OTA_START, payload, sizeof(payload));
}

CanFrame OtaManager::metaFrame(uint8_t window_size) const {
    uint8_t payload[6];
    payload[0] = hardware_id_;
    writeUint16BE(&payload[1], crc_);
    writeUint16BE(&payload[3], frameCount());
    payload[5] = window_size;
    return makeOtaControl(source_, target_, OTA_META, payload, sizeof(payload));
}

CanFrame OtaManager::finishFrame() const {
    uint8_t payload[1] = {OTA_STATUS_OK};
    return makeOtaControl(source_, target_, OTA_FINISH, payload, sizeof(payload));
}

CanFrame OtaManager::abortFrame(uint8_t status) const {
    uint8_t payload[1] = {status};
    return makeOtaControl(source_, target_, OTA_ABORT, payload, sizeof(payload));
}

bool OtaManager::applyReadyAck(const CanFrame &frame, uint8_t &status_out,
                              uint8_t &window_size_out) const {
    uint8_t payload[6];
    uint8_t command = 0;
    if (!decodeOtaControl(frame, command, payload) || command != OTA_READY_ACK) {
        return false;
    }
    status_out = payload[0];
    window_size_out = payload[1] == 0 ? 16 : payload[1];
    return true;
}

bool OtaManager::applyWindowAck(const CanFrame &frame, uint8_t &window_out,
                                uint16_t &missing_mask_out) const {
    uint8_t payload[6];
    uint8_t command = 0;
    if (!decodeOtaControl(frame, command, payload) || command != OTA_WINDOW_ACK) {
        return false;
    }
    window_out = payload[0];
    missing_mask_out = readUint16BE(&payload[1]);
    return true;
}

bool OtaManager::applyStatus(const CanFrame &frame, uint8_t &status_out,
                             uint16_t &blocks_received_out) const {
    uint8_t payload[6];
    uint8_t command = 0;
    if (!decodeOtaControl(frame, command, payload) || command != OTA_STATUS) {
        return false;
    }
    status_out = payload[0];
    blocks_received_out = readUint16BE(&payload[1]);
    return true;
}

bool OtaManager::frameAt(uint16_t sequence, CanFrame &out) const {
    if (image_ == 0 || image_size_ == 0) {
        return false;
    }
    const size_t offset = static_cast<size_t>(sequence) * kBytesPerFrame;
    if (offset >= image_size_) {
        return false;
    }
    const size_t remaining = image_size_ - offset;
    const uint8_t chunk_size =
        static_cast<uint8_t>(remaining > kBytesPerFrame ? kBytesPerFrame : remaining);
    out = makeOtaData(source_, target_, static_cast<uint8_t>(sequence), &image_[offset], chunk_size);
    return true;
}

void OtaManager::abort() {
    if (state_ == OTA_STATE_STREAMING) {
        state_ = OTA_STATE_ABORTED;
    }
}

bool OtaManager::active() const {
    return state_ == OTA_STATE_STREAMING;
}

bool OtaManager::complete() const {
    return state_ == OTA_STATE_COMPLETE;
}

OtaState OtaManager::state() const {
    return state_;
}

size_t OtaManager::imageSize() const {
    return image_size_;
}

size_t OtaManager::bytesSent() const {
    return offset_;
}

uint16_t OtaManager::imageCrc() const {
    return crc_;
}

uint16_t OtaManager::frameCount() const {
    if (image_size_ == 0) {
        return 0;
    }
    return static_cast<uint16_t>((image_size_ + kBytesPerFrame - 1) / kBytesPerFrame);
}

}  // namespace pcd#pragma once

/*
 * Orquestador OTA por CAN para el lado emisor (gateway).
 *
 * El manager conserva la imagen en memoria del llamador, calcula el CRC
 * global y produce bloques compatibles con makeOtaData(). Tambien construye
 * las tramas de control de la campana (START, META, FINISH, ABORT) segun la
 * especificacion de la wiki 6 y parsea las respuestas del receptor.
 */

#include <stddef.h>
#include <stdint.h>

#include "can_protocol.h"

namespace pcd {

enum OtaState : uint8_t {
    OTA_STATE_IDLE = 0,
    OTA_STATE_STREAMING = 1,
    OTA_STATE_COMPLETE = 2,
    OTA_STATE_ABORTED = 3
};

class OtaManager {
  public:
    static const size_t kBytesPerFrame = kPayloadSize - 1;
    /* El bloque 0xFF esta reservado como marca de control OTA. */
    static const size_t kMaxFrames = kOtaMaxDataBlocks;
    static const size_t kMaxImageBytes = kBytesPerFrame * kMaxFrames;

    OtaManager(uint16_t source, uint8_t target);

    /* Inicia una campana sobre una imagen que permanece propiedad del llamador. */
    bool begin(const uint8_t *image, size_t image_size);

    /* Version de firmware anunciada y familia de hardware de la imagen. */
    void setFirmwareInfo(uint8_t version_major, uint8_t version_minor, uint8_t hardware_id);

    /* Produce el siguiente OTA_DATA. Devuelve false si no hay más bloques. */
    bool nextFrame(CanFrame &out);

    /* Reconstruye un bloque concreto de la imagen (retransmision por ventana). */
    bool frameAt(uint16_t sequence, CanFrame &out) const;

    /* Tramas de control de la campana. */
    CanFrame startFrame() const;
    CanFrame metaFrame(uint8_t window_size = 16) const;
    CanFrame finishFrame() const;
    CanFrame abortFrame(uint8_t status = OTA_STATUS_OK) const;

    /* Parseo de las respuestas del receptor. */
    bool applyReadyAck(const CanFrame &frame, uint8_t &status_out,
                       uint8_t &window_size_out) const;
    bool applyWindowAck(const CanFrame &frame, uint8_t &window_out,
                        uint16_t &missing_mask_out) const;
    bool applyStatus(const CanFrame &frame, uint8_t &status_out,
                     uint16_t &blocks_received_out) const;

    /* Cancela la campana y evita emitir bloques restantes. */
    void abort();

    bool active() const;
    bool complete() const;
    OtaState state() const;
    size_t imageSize() const;
    size_t bytesSent() const;
    uint16_t imageCrc() const;
    uint16_t frameCount() const;
    uint8_t versionMajor() const { return version_major_; }
    uint8_t versionMinor() const { return version_minor_; }
    uint8_t hardwareId() const { return hardware_id_; }

  private:
    uint16_t source_;
    uint8_t target_;
    const uint8_t *image_;
    size_t image_size_;
    size_t offset_;
    uint16_t crc_;
    OtaState state_;
    uint8_t version_major_;
    uint8_t version_minor_;
    uint8_t hardware_id_;
};

}  // namespace pcd#include "ota_window.h"

namespace pcd {

OtaWindowController::OtaWindowController(OtaManager &manager, uint8_t window_size)
    : manager_(manager),
      window_size_(window_size > 16 ? 16 : window_size),
      window_index_(0),
      frames_in_window_(0),
      pending_mask_(0),
      waiting_ack_(false) {
    if (window_size_ == 0) window_size_ = 1;
}

void OtaWindowController::reset() {
    window_index_ = 0;
    frames_in_window_ = 0;
    pending_mask_ = 0;
    waiting_ack_ = false;
}

bool OtaWindowController::next(CanFrame &out) {
    if (!manager_.active() || waiting_ack_) return false;
    if (!manager_.nextFrame(out)) return false;
    ++frames_in_window_;
    pending_mask_ |= static_cast<uint16_t>(1U << (frames_in_window_ - 1));
    if (frames_in_window_ >= window_size_ || manager_.complete()) waiting_ack_ = true;
    return true;
}

bool OtaWindowController::acknowledge(uint8_t window, uint16_t missing_mask) {
    if (!waiting_ack_ || window != window_index_) return false;
    if (missing_mask != 0) {
        /* Solo los bloques marcados vuelven a emitirse con retryNext(). */
        pending_mask_ = missing_mask;
        return true;
    }
    ++window_index_;
    frames_in_window_ = 0;
    pending_mask_ = 0;
    waiting_ack_ = false;
    return true;
}

bool OtaWindowController::retryNext(CanFrame &out) {
    if (!waiting_ack_ || pending_mask_ == 0) {
        return false;
    }
    const uint16_t base = static_cast<uint16_t>(window_index_) * window_size_;
    for (uint8_t i = 0; i < window_size_; ++i) {
        const uint16_t bit = static_cast<uint16_t>(1U << i);
        if ((pending_mask_ & bit) == 0) {
            continue;
        }
        if (!manager_.frameAt(static_cast<uint16_t>(base + i), out)) {
            pending_mask_ = 0;
            break;
        }
        pending_mask_ = static_cast<uint16_t>(pending_mask_ & ~bit);
        if (pending_mask_ == 0) {
            ++window_index_;
            frames_in_window_ = 0;
            waiting_ack_ = false;
        }
        return true;
    }
    /* Mascara sin bits utiles: la ventana se da por confirmada. */
    pending_mask_ = 0;
    ++window_index_;
    frames_in_window_ = 0;
    waiting_ack_ = false;
    return false;
}

}  // namespace pcd#pragma once

#include <stddef.h>
#include <stdint.h>

#include "ota_manager.h"

namespace pcd {

/*
 * Control local de ventanas OTA: prepara el emisor para ACK/retransmision.
 *
 * Secuencia de la campana:
 *
 *   next()          -> emite los bloques de la ventana hasta completarla
 *   acknowledge()   -> consume el OTA_WINDOW_ACK del receptor; con mascara 0 la
 *                      ventana queda confirmada, con mascara != 0 solo esos
 *                      bloques se retransmiten
 *   retryNext()     -> emite los bloques pendientes de la mascara
 */
class OtaWindowController {
  public:
    explicit OtaWindowController(OtaManager &manager, uint8_t window_size = 16);

    bool next(CanFrame &out);
    bool acknowledge(uint8_t window, uint16_t missing_mask);

    /* Emite el siguiente bloque pendiente de retransmision. Al agotar la
     * mascara la ventana se confirma y avanza a la siguiente. */
    bool retryNext(CanFrame &out);

    void reset();
    uint8_t window() const { return window_index_; }
    uint16_t pendingMask() const { return pending_mask_; }
    bool waitingAck() const { return waiting_ack_; }

  private:
    OtaManager &manager_;
    uint8_t window_size_;
    uint8_t window_index_;
    uint8_t frames_in_window_;
    uint16_t pending_mask_;
    bool waiting_ack_;
};

}  // namespace pcd#pragma once

/*
 * Motor de reglas de vinculacion logica.
 *
 * Es lo que hace al ecosistema realmente descentralizado: las reglas viven en
 * el nodo que ejecuta la accion, se guardan en su memoria no volatil y se
 * evaluan con cada trama recibida. Si el gateway se apaga, la tecla de la pared
 * sigue encendiendo la luz.
 *
 * El motor tambien atiende las tramas SDO (MSG_CONFIG) que permiten programar,
 * borrar y persistir esas reglas desde cualquier punto del bus.
 */

#include <stdint.h>

#include "can_node.h"
#include "config_storage.h"

namespace pcd {

class RuleEngine {
  public:
    RuleEngine(CanNode &node, ConfigStore &config);

    /* Engancha el motor a las tramas entrantes y a los SDO del nodo. */
    void begin();

    /* Evalua una trama contra la tabla de reglas y ejecuta las coincidencias. */
    void evaluate(const CanFrame &frame);

    /* Procesa una trama SDO de configuracion dirigida a este nodo. */
    bool handleConfig(const CanFrame &frame);

    uint8_t pendingSegments() const { return staged_mask_; }

  private:
    static void frameTrampoline(const CanFrame &frame, void *ctx);
    static void configTrampoline(const CanFrame &frame, void *ctx);

    bool matches(const BindingRule &rule, const CanFrame &frame, const CanId &id) const;
    void execute(const BindingRule &rule);
    void sendAck(uint8_t sub_command, uint8_t status);

    CanNode &node_;
    ConfigStore &config_;

    /* Buffer de recepcion segmentada de una regla (4 tramas de 5 bytes). */
    uint8_t staged_[kBindingRuleBytes];
    uint8_t staged_mask_;
    uint8_t staged_index_;
};

