namespace pcd {

/* CRC-16/CCITT-FALSE: barato en AVR y suficiente para bloques de pocos cientos
 * de bytes. */
uint16_t crc16(const uint8_t *data, uint16_t length, uint16_t seed) {
    uint16_t crc = seed;
    for (uint16_t i = 0; i < length; ++i) {
        crc ^= static_cast<uint16_t>(data[i]) << 8;
        for (uint8_t bit = 0; bit < 8; ++bit) {
            crc = (crc & 0x8000) ? static_cast<uint16_t>((crc << 1) ^ 0x1021)
                                 : static_cast<uint16_t>(crc << 1);
        }
    }
    return crc;
}

void ConfigStore::serializeRule(const BindingRule &rule, uint8_t *out) {
    memset(out, 0, kBindingRuleBytes);
    writeUint16BE(&out[0], rule.source_node);
    out[2] = rule.source_resource;
    out[3] = rule.source_channel;
    out[4] = rule.trigger;
    out[5] = rule.event;
    writeFloatBE(&out[6], rule.threshold);
    out[10] = rule.target_resource;
    out[11] = rule.target_channel;
    out[12] = rule.action;
    writeUint32BE(&out[13], rule.param);
}

void ConfigStore::deserializeRule(const uint8_t *in, BindingRule &out) {
    out.source_node = readUint16BE(&in[0]);
    out.source_resource = in[2];
    out.source_channel = in[3];
    out.trigger = in[4];
    out.event = in[5];
    out.threshold = readFloatBE(&in[6]);
    out.target_resource = in[10];
    out.target_channel = in[11];
    out.action = in[12];
    out.param = readUint32BE(&in[13]);
}

ConfigStore::ConfigStore(StorageAdapter &storage)
    : storage_(storage), node_id_(0), node_id_mode_(NODE_ID_MANUAL), rule_count_(0) {}

bool ConfigStore::begin(uint16_t default_node_id) {
    if (!storage_.begin() || storage_.capacity() < kConfigTotalBytes) {
        reset(default_node_id);
        return false;
    }
    if (load()) {
        return true;
    }
    reset(default_node_id);
    return false;
}

void ConfigStore::reset(uint16_t node_id) {
    node_id_ = node_id;
    node_id_mode_ = NODE_ID_MANUAL;
    rule_count_ = 0;
}

bool ConfigStore::load() {
    uint8_t header[kConfigHeaderBytes];
    if (!storage_.read(0, header, 6)) {
        return false;
    }
    if (readUint16BE(&header[0]) != kConfigMagic ||
        (header[2] != 1 && header[2] != kConfigVersion)) {
        return false;
    }
    const uint16_t header_bytes = (header[2] == 1) ? 6 : kConfigHeaderBytes;
    if (header_bytes == kConfigHeaderBytes && !storage_.read(6, &header[6], 1)) {
        return false;
    }
    const uint8_t count = header[3];
    if (count > CAN_MAX_RULES) {
        return false;
    }

    const uint16_t payload_bytes =
        header_bytes + static_cast<uint16_t>(kBindingRuleBytes) * count;
    uint16_t crc = crc16(header, header_bytes);

    uint8_t raw[kBindingRuleBytes];
    BindingRule staged[CAN_MAX_RULES];
    for (uint8_t i = 0; i < count; ++i) {
        const uint16_t offset =
            kConfigHeaderBytes + static_cast<uint16_t>(kBindingRuleBytes) * i;
        if (!storage_.read(offset, raw, kBindingRuleBytes)) {
            return false;
        }
        crc = crc16(raw, kBindingRuleBytes, crc);
        deserializeRule(raw, staged[i]);
    }

    uint8_t stored_crc[2];
    if (!storage_.read(payload_bytes, stored_crc, 2)) {
        return false;
    }
    if (readUint16BE(stored_crc) != crc) {
        return false;
    }

    node_id_ = readUint16BE(&header[4]);
    node_id_mode_ = (header_bytes == kConfigHeaderBytes && header[6] == NODE_ID_AUTOMATIC)
                        ? NODE_ID_AUTOMATIC
                        : NODE_ID_MANUAL;
    rule_count_ = count;
    for (uint8_t i = 0; i < count; ++i) {
        rules_[i] = staged[i];
    }
    return true;
}

bool ConfigStore::save() {
    uint8_t header[kConfigHeaderBytes];
    writeUint16BE(&header[0], kConfigMagic);
    header[2] = kConfigVersion;
    header[3] = rule_count_;
    writeUint16BE(&header[4], node_id_);
    header[6] = node_id_mode_;

    if (!storage_.write(0, header, kConfigHeaderBytes)) {
        return false;
    }
    uint16_t crc = crc16(header, kConfigHeaderBytes);

    uint8_t raw[kBindingRuleBytes];
    for (uint8_t i = 0; i < rule_count_; ++i) {
        serializeRule(rules_[i], raw);
        const uint16_t offset =
            kConfigHeaderBytes + static_cast<uint16_t>(kBindingRuleBytes) * i;
        if (!storage_.write(offset, raw, kBindingRuleBytes)) {
            return false;
        }
        crc = crc16(raw, kBindingRuleBytes, crc);
    }

    uint8_t stored_crc[2];
    writeUint16BE(stored_crc, crc);
    const uint16_t payload_bytes =
        kConfigHeaderBytes + static_cast<uint16_t>(kBindingRuleBytes) * rule_count_;
    if (!storage_.write(payload_bytes, stored_crc, 2)) {
        return false;
    }
    return storage_.commit();
}

bool ConfigStore::addRule(const BindingRule &rule) {
    if (rule_count_ >= CAN_MAX_RULES) {
        return false;
    }
    rules_[rule_count_++] = rule;
    return true;
}

bool ConfigStore::replaceRule(uint8_t index, const BindingRule &rule) {
    if (index >= rule_count_) {
        return false;
    }
    rules_[index] = rule;
    return true;
}

bool ConfigStore::removeRule(uint8_t index) {
    if (index >= rule_count_) {
        return false;
    }
    for (uint8_t i = index; i + 1 < rule_count_; ++i) {
        rules_[i] = rules_[i + 1];
    }
    --rule_count_;
    return true;
}

/* ------------------------------------------------------------------ */

MemoryStorage::MemoryStorage() {
    memset(buffer_, 0xFF, sizeof(buffer_));
}

bool MemoryStorage::begin() {
    return true;
}

bool MemoryStorage::read(uint16_t offset, uint8_t *data, uint16_t length) {
    if (static_cast<uint32_t>(offset) + length > sizeof(buffer_)) {
        return false;
    }
    memcpy(data, &buffer_[offset], length);
    return true;
}

bool MemoryStorage::write(uint16_t offset, const uint8_t *data, uint16_t length) {
    if (static_cast<uint32_t>(offset) + length > sizeof(buffer_)) {
        return false;
    }
    memcpy(&buffer_[offset], data, length);
    return true;
}

bool MemoryStorage::commit() {
    return true;
}

void MemoryStorage::corrupt(uint16_t offset) {
    if (offset < sizeof(buffer_)) {
        buffer_[offset] = static_cast<uint8_t>(~buffer_[offset]);
    }
}

/* ------------------------------------------------------------------ */

#if defined(__AVR__)
EepromStorage::EepromStorage(uint16_t base_address) : base_address_(base_address) {}

bool EepromStorage::begin() {
    return capacity() >= kConfigTotalBytes;
}

bool EepromStorage::read(uint16_t offset, uint8_t *data, uint16_t length) {
    if (static_cast<uint32_t>(offset) + length > capacity()) {
        return false;
    }
    for (uint16_t i = 0; i < length; ++i) {
        data[i] = EEPROM.read(base_address_ + offset + i);
    }
    return true;
}

bool EepromStorage::write(uint16_t offset, const uint8_t *data, uint16_t length) {
    if (static_cast<uint32_t>(offset) + length > capacity()) {
        return false;
    }
    /* EEPROM.update evita ciclos de borrado innecesarios. */
    for (uint16_t i = 0; i < length; ++i) {
        EEPROM.update(base_address_ + offset + i, data[i]);
    }
    return true;
}

bool EepromStorage::commit() {
    return true;
}

uint16_t EepromStorage::capacity() const {
    const uint16_t total = static_cast<uint16_t>(E2END) + 1;
    return (base_address_ >= total) ? 0 : static_cast<uint16_t>(total - base_address_);
}
#endif

/* ------------------------------------------------------------------ */

#if defined(ARDUINO_ARCH_ESP32)
NvsStorage::NvsStorage(const char *nvs_namespace, const char *key)
    : namespace_(nvs_namespace), key_(key), dirty_(false) {
    memset(buffer_, 0xFF, sizeof(buffer_));
}

bool NvsStorage::begin() {
    Preferences prefs;
    if (!prefs.begin(namespace_, true)) {
        return true; /* namespace todavia inexistente: bloque vacio */
    }
    prefs.getBytes(key_, buffer_, sizeof(buffer_));
    prefs.end();
    return true;
}

bool NvsStorage::read(uint16_t offset, uint8_t *data, uint16_t length) {
    if (static_cast<uint32_t>(offset) + length > sizeof(buffer_)) {
        return false;
    }
    memcpy(data, &buffer_[offset], length);
    return true;
}

bool NvsStorage::write(uint16_t offset, const uint8_t *data, uint16_t length) {
    if (static_cast<uint32_t>(offset) + length > sizeof(buffer_)) {
        return false;
    }
    memcpy(&buffer_[offset], data, length);
    dirty_ = true;
    return true;
}

/* El bloque se escribe entero en una sola clave NVS: o se persiste completo o
 * queda el anterior, nunca una mezcla de ambos. */
bool NvsStorage::commit() {
    if (!dirty_) {
        return true;
    }
    Preferences prefs;
    if (!prefs.begin(namespace_, false)) {
        return false;
    }
    const size_t written = prefs.putBytes(key_, buffer_, sizeof(buffer_));
    prefs.end();
    dirty_ = (written != sizeof(buffer_));
    return !dirty_;
}
#endif

}  // namespace pcd#pragma once

/*
 * Persistencia de la "fuente de la verdad" local de cada nodo.
 *
 *   AVR     -> EEPROM interna (<EEPROM.h>)
 *   ESP32   -> NVS a traves de Preferences (blob unico)
 *   native  -> arreglo en RAM para pruebas
 *
 * StorageAdapter expone un acceso por bytes uniforme; ConfigStore construye
 * sobre el un bloque con cabecera, version, Node-ID, reglas de vinculacion y
 * CRC-16, de modo que un corte de energia nunca deja al nodo con reglas
 * parcialmente escritas: si el CRC no valida se cargan los valores por defecto.
 */

#include <stdint.h>

#include "can_protocol.h"
#include "system_config.h"

namespace pcd {

#ifndef CAN_MAX_RULES
#define CAN_MAX_RULES 12
#endif

class StorageAdapter {
  public:
    virtual ~StorageAdapter() {}

    virtual bool begin() = 0;
    virtual bool read(uint16_t offset, uint8_t *data, uint16_t length) = 0;
    virtual bool write(uint16_t offset, const uint8_t *data, uint16_t length) = 0;
    /* Vuelca a memoria no volatil lo escrito (no-op donde la escritura es directa). */
    virtual bool commit() = 0;
    virtual uint16_t capacity() const = 0;
};

/* Operador de disparo de una regla de vinculacion. */
enum RuleTrigger : uint8_t {
    TRIG_EVENT = 0x00,       /* el evento/accion recibido coincide con `event`   */
    TRIG_VALUE_GREATER = 0x01,
    TRIG_VALUE_LESS = 0x02,
    TRIG_VALUE_EQUAL = 0x03,
    TRIG_ANY = 0x04          /* cualquier trama del origen indicado              */
};

/*
 * Regla de vinculacion logica almacenada en el nodo.
 *
 *   "Si el nodo 0x05 informa el evento pulsacion corta en su entrada 1,
 *    conmutar el rele del canal 2 de este nodo"
 */
struct BindingRule {
    uint16_t source_node;     /* 0x0000 = cualquiera            */
    uint8_t source_resource;
    uint8_t source_channel;   /* kAnyChannel = cualquiera       */
    uint8_t trigger;          /* RuleTrigger                    */
    uint8_t event;            /* evento esperado en TRIG_EVENT  */
    float threshold;          /* umbral en los disparos por valor */
    uint8_t target_resource;  /* recurso local a accionar       */
    uint8_t target_channel;
    uint8_t action;           /* ACT_ON / ACT_OFF / ACT_TOGGLE / ACT_SET_VALUE */
    uint32_t param;           /* temporizador o valor + fade    */
};

static const uint8_t kBindingRuleBytes = 20;
static const uint16_t kConfigMagic = 0x5043; /* 'P','C' */
static const uint8_t kConfigVersion = 2;

/* Cabecera + reglas + CRC. Determina el tamano minimo del adaptador. */
static const uint16_t kConfigHeaderBytes = 7;
static const uint16_t kConfigTotalBytes =
    kConfigHeaderBytes + static_cast<uint16_t>(kBindingRuleBytes) * CAN_MAX_RULES + 2;

class ConfigStore {
  public:
    explicit ConfigStore(StorageAdapter &storage);

    /* Inicializa el medio y carga la configuracion. Devuelve false y aplica los
     * valores por defecto si el bloque esta vacio o el CRC no valida. */
    bool begin(uint16_t default_node_id = 0);

    bool load();
    bool save();
    void reset(uint16_t node_id);

    uint16_t nodeId() const { return node_id_; }
    void setNodeId(uint16_t node_id) { node_id_ = node_id; }
    NodeIdMode nodeIdMode() const { return node_id_mode_; }
    void setNodeIdMode(NodeIdMode mode) { node_id_mode_ = mode; }

    uint8_t ruleCount() const { return rule_count_; }
    const BindingRule &rule(uint8_t index) const { return rules_[index]; }
    bool addRule(const BindingRule &rule);
    bool replaceRule(uint8_t index, const BindingRule &rule);
    bool removeRule(uint8_t index);
    void clearRules() { rule_count_ = 0; }

    /* Serializacion explicita en Big-Endian, identica en AVR, ESP32 y STM32. */
    static void serializeRule(const BindingRule &rule, uint8_t *out);
    static void deserializeRule(const uint8_t *in, BindingRule &out);

  private:
    StorageAdapter &storage_;
    uint16_t node_id_;
    NodeIdMode node_id_mode_;
    uint8_t rule_count_;
    BindingRule rules_[CAN_MAX_RULES];
};

uint16_t crc16(const uint8_t *data, uint16_t length, uint16_t seed = 0xFFFF);

/* ------------------------------------------------------------------ */
/* Adaptadores por plataforma                                           */
/* ------------------------------------------------------------------ */

/* Adaptador en RAM: pruebas de escritorio y nodos sin memoria no volatil. */
class MemoryStorage : public StorageAdapter {
  public:
    MemoryStorage();
    bool begin() override;
    bool read(uint16_t offset, uint8_t *data, uint16_t length) override;
    bool write(uint16_t offset, const uint8_t *data, uint16_t length) override;
    bool commit() override;
    uint16_t capacity() const override { return kConfigTotalBytes; }

    /* Simula un corte de energia corrompiendo un byte del bloque. */
    void corrupt(uint16_t offset);

  private:
    uint8_t buffer_[kConfigTotalBytes];
};

#if defined(__AVR__)
class EepromStorage : public StorageAdapter {
  public:
    explicit EepromStorage(uint16_t base_address = 0);
    bool begin() override;
    bool read(uint16_t offset, uint8_t *data, uint16_t length) override;
    bool write(uint16_t offset, const uint8_t *data, uint16_t length) override;
    bool commit() override;
    uint16_t capacity() const override;

  private:
    uint16_t base_address_;
};
#endif

#if defined(ARDUINO_ARCH_ESP32)
class NvsStorage : public StorageAdapter {
  public:
    explicit NvsStorage(const char *nvs_namespace = "pcd", const char *key = "cfg");
    bool begin() override;
    bool read(uint16_t offset, uint8_t *data, uint16_t length) override;
    bool write(uint16_t offset, const uint8_t *data, uint16_t length) override;
    bool commit() override;
    uint16_t capacity() const override { return kConfigTotalBytes; }

  private:
    const char *namespace_;
    const char *key_;
    uint8_t buffer_[kConfigTotalBytes];
    bool dirty_;
};
#endif

}  // namespace pcd#include "rule_engine.h"

#include <string.h>

namespace pcd {

static const uint8_t kSegmentBytes = 5;
static const uint8_t kSegmentCount = kBindingRuleBytes / kSegmentBytes;
static const uint8_t kAllSegments = (1 << kSegmentCount) - 1;
static const uint8_t kAppendIndex = 0xFF;

RuleEngine::RuleEngine(CanNode &node, ConfigStore &config)
    : node_(node), config_(config), staged_mask_(0), staged_index_(kAppendIndex) {
    memset(staged_, 0, sizeof(staged_));
}

void RuleEngine::frameTrampoline(const CanFrame &frame, void *ctx) {
    static_cast<RuleEngine *>(ctx)->evaluate(frame);
}

void RuleEngine::configTrampoline(const CanFrame &frame, void *ctx) {
    static_cast<RuleEngine *>(ctx)->handleConfig(frame);
}

void RuleEngine::begin() {
    node_.setNodeId(config_.nodeId());
    node_.setNodeIdMode(config_.nodeIdMode());
    node_.onAnyFrame(&RuleEngine::frameTrampoline, this);
    node_.onConfig(&RuleEngine::configTrampoline, this);
}

bool RuleEngine::matches(const BindingRule &rule, const CanFrame &frame, const CanId &id) const {
    if (rule.source_node != kAnySource && rule.source_node != id.source) {
        return false;
    }
    if (rule.source_resource != frame.resource()) {
        return false;
    }
    if (rule.source_channel != kAnyChannel && rule.source_channel != frame.channel()) {
        return false;
    }

    switch (rule.trigger) {
        case TRIG_ANY:
            return true;
        case TRIG_EVENT:
            return id.msg_type == MSG_EVENT && frame.data[2] == rule.event;
        case TRIG_VALUE_GREATER:
            return id.msg_type == MSG_STATE && frameValue(frame) > rule.threshold;
        case TRIG_VALUE_LESS:
            return id.msg_type == MSG_STATE && frameValue(frame) < rule.threshold;
        case TRIG_VALUE_EQUAL:
            return id.msg_type == MSG_STATE && frameValue(frame) == rule.threshold;
        default:
            return false;
    }
}

void RuleEngine::execute(const BindingRule &rule) {
    node_.applyLocal(rule.target_resource, rule.target_channel, rule.action, rule.param);
}

void RuleEngine::evaluate(const CanFrame &frame) {
    const CanId id = frame.fields();
    if (id.msg_type != MSG_EVENT && id.msg_type != MSG_STATE) {
        return;
    }
    for (uint8_t i = 0; i < config_.ruleCount(); ++i) {
        const BindingRule &rule = config_.rule(i);
        if (matches(rule, frame, id)) {
            execute(rule);
        }
    }
}

void RuleEngine::sendAck(uint8_t sub_command, uint8_t status) {
    uint8_t payload[2];
    payload[0] = sub_command;
    payload[1] = status;
    node_.sendConfigAck(payload, sizeof(payload));
}

bool RuleEngine::handleConfig(const CanFrame &frame) {
    if (frame.resource() != RES_CONFIG) {
        return false;
    }
    const uint8_t sub_command = frame.channel();
    const uint8_t *payload = &frame.data[2];

    switch (sub_command) {
        case CFG_SET_NODE_ID: {
            const uint16_t new_id = readUint16BE(payload);
            if (!isValidSource(new_id)) {
                sendAck(sub_command, CFG_STATUS_BAD_REQUEST);
                return true;
            }
            config_.setNodeId(new_id);
            config_.setNodeIdMode(NODE_ID_MANUAL);
            node_.setNodeId(new_id);
            node_.setNodeIdMode(NODE_ID_MANUAL);
            sendAck(sub_command, config_.save() ? CFG_STATUS_OK : CFG_STATUS_STORAGE_ERROR);
            return true;
        }

        case CFG_SET_NODE_MODE: {
            if (payload[0] > NODE_ID_AUTOMATIC) {
                sendAck(sub_command, CFG_STATUS_BAD_REQUEST);
                return true;
            }
            const NodeIdMode mode = static_cast<NodeIdMode>(payload[0]);
            config_.setNodeIdMode(mode);
            node_.setNodeIdMode(mode);
            sendAck(sub_command, config_.save() ? CFG_STATUS_OK : CFG_STATUS_STORAGE_ERROR);
            return true;
        }

        case CFG_SUBSCRIBE: {
            const uint16_t source = readUint16BE(payload);
            if (!node_.addListenFilter(source, payload[2], payload[3])) {
                sendAck(sub_command, CFG_STATUS_FULL);
            } else {
                sendAck(sub_command, CFG_STATUS_OK);
            }
            return true;
        }

        case CFG_UNSUBSCRIBE:
            node_.clearListenFilters();
            sendAck(sub_command, CFG_STATUS_OK);
            return true;

        case CFG_CLEAR_SUBSCRIPTIONS:
            node_.clearListenFilters();
            sendAck(sub_command, CFG_STATUS_OK);
            return true;

        case CFG_RULE_BEGIN: {
            memset(staged_, 0, sizeof(staged_));
            staged_mask_ = 0;
            staged_index_ = payload[0];
            sendAck(sub_command, CFG_STATUS_OK);
            return true;
        }

        case CFG_RULE_CHUNK: {
            const uint8_t segment = payload[0];
            if (segment >= kSegmentCount) {
                sendAck(sub_command, CFG_STATUS_BAD_REQUEST);
                return true;
            }
            memcpy(&staged_[segment * kSegmentBytes], &payload[1], kSegmentBytes);
            staged_mask_ |= static_cast<uint8_t>(1 << segment);
            return true;
        }

        case CFG_RULE_COMMIT: {
            if (staged_mask_ != kAllSegments) {
                sendAck(sub_command, CFG_STATUS_BAD_REQUEST);
                return true;
            }
            if (readUint16BE(payload) != crc16(staged_, kBindingRuleBytes)) {
                staged_mask_ = 0;
                sendAck(sub_command, CFG_STATUS_CRC_ERROR);
                return true;
            }

            BindingRule rule;
            ConfigStore::deserializeRule(staged_, rule);
            staged_mask_ = 0;

            bool stored;
            if (staged_index_ < config_.ruleCount()) {
                stored = config_.replaceRule(staged_index_, rule);
            } else {
                stored = config_.addRule(rule);
            }
            if (!stored) {
                sendAck(sub_command, CFG_STATUS_FULL);
                return true;
            }
            sendAck(sub_command, config_.save() ? CFG_STATUS_OK : CFG_STATUS_STORAGE_ERROR);
            return true;
        }

        case CFG_RULE_DELETE: {
            if (!config_.removeRule(payload[0])) {
                sendAck(sub_command, CFG_STATUS_BAD_REQUEST);
                return true;
            }
            sendAck(sub_command, config_.save() ? CFG_STATUS_OK : CFG_STATUS_STORAGE_ERROR);
            return true;
        }

        case CFG_RULE_CLEAR: {
            config_.clearRules();
            sendAck(sub_command, config_.save() ? CFG_STATUS_OK : CFG_STATUS_STORAGE_ERROR);
            return true;
        }

        case CFG_SAVE: {
            sendAck(sub_command, config_.save() ? CFG_STATUS_OK : CFG_STATUS_STORAGE_ERROR);
            return true;
        }

        case CFG_RULE_COUNT: {
            uint8_t response[3];
            response[0] = CFG_RULE_COUNT;
            response[1] = CFG_STATUS_OK;
            response[2] = config_.ruleCount();
            node_.sendConfigAck(response, sizeof(response));
            return true;
        }

        default:
            return false;
    }
}

}  // namespace pcd#pragma once

/*
 * Configuracion global del ecosistema CAN Bus (PCD v1).
 * Todas las caracteristicas se activan con banderas 0/1 para que el compilador
 * elimine por completo el codigo no utilizado en plataformas con poca Flash/RAM.
 */

#ifndef FEATURE_OTA_MANAGER
#define FEATURE_OTA_MANAGER 0
#endif

#ifndef FEATURE_WEB_SERVER
#define FEATURE_WEB_SERVER 0
#endif

#ifndef FEATURE_MQTT_BRIDGE
#define FEATURE_MQTT_BRIDGE 0
#endif

#ifndef FEATURE_MODBUS_BRIDGE
#define FEATURE_MODBUS_BRIDGE 0
#endif

#ifndef FEATURE_MODBUS_TCP
#define FEATURE_MODBUS_TCP 0
#endif

#ifndef FEATURE_TUNNEL_BRIDGE
#define FEATURE_TUNNEL_BRIDGE 0
#endif

/* Nivel de trazas: 0 = produccion (sin strings en Flash), 1 = error, 2 = info, 3 = debug */
#ifndef CAN_LOG_LEVEL
#define CAN_LOG_LEVEL 0
#endif

/* Velocidad nominal del bus CAN en bits por segundo. */
#ifndef CAN_BUS_BITRATE
#define CAN_BUS_BITRATE 500000UL
#endif

/* Periodo de emision del heartbeat de nodo, en milisegundos. */
#ifndef CAN_HEARTBEAT_PERIOD_MS
#define CAN_HEARTBEAT_PERIOD_MS 5000UL
#endif

/* Cantidad maxima de suscripciones y recursos registrables por nodo. */
#ifndef CAN_MAX_SUBSCRIPTIONS
#define CAN_MAX_SUBSCRIPTIONS 16
#endif

/* La libreria base es 100% agnostica al framework: no incluye <Arduino.h>.
 * El reloj, el bloqueo y el diagnostico se inyectan via SystemApi.
 * Los macros LOG_* provienen de system/system_logger.h. */
#include "system/system_api.h"
#include "system/system_logger.h"/*
 * Pruebas del gestor de recursos, la persistencia y el motor de reglas sobre el
 * bus virtual: cubren temporizadores, rampas, CRC, recuperacion ante corrupcion
 * y la programacion de reglas por SDO segmentado.
 */

#include <unity.h>

#include "PCD_CAN.h"

using namespace pcd;

namespace {

struct FakeRelay {
    bool state;
    uint8_t calls;
};

bool relayHandler(uint8_t channel, uint8_t action, uint32_t param, float &out_value, void *ctx) {
    (void)channel;
    (void)param;
    FakeRelay *relay = static_cast<FakeRelay *>(ctx);
    ++relay->calls;
    switch (action) {
        case ACT_OFF: relay->state = false; break;
        case ACT_ON: relay->state = true; break;
        case ACT_TOGGLE: relay->state = !relay->state; break;
        default: return false;
    }
    out_value = relay->state ? 1.0f : 0.0f;
    return true;
}

bool dimmerHandler(uint8_t channel, uint8_t action, uint32_t param, float &out_value, void *ctx) {
    (void)channel;
    float *level = static_cast<float *>(ctx);
    switch (action) {
        case ACT_OFF: *level = 0.0f; break;
        case ACT_ON: *level = 100.0f; break;
        case ACT_SET_VALUE: *level = static_cast<float>(unpackSetValueTarget(param)); break;
        default: return false;
    }
    out_value = *level;
    return true;
}

BindingRule makeShortClickRule() {
    BindingRule rule;
    rule.source_node = 0x0005;
    rule.source_resource = RES_DIGITAL_INPUT;
    rule.source_channel = 0x01;
    rule.trigger = TRIG_EVENT;
    rule.event = EVT_SHORT_CLICK;
    rule.threshold = 0.0f;
    rule.target_resource = RES_RELAY;
    rule.target_channel = 0x02;
    rule.action = ACT_TOGGLE;
    rule.param = 0;
    return rule;
}

}  // namespace

void test_device_manager_registers_and_applies() {
    DeviceManager devices;
    FakeRelay relay = {false, 0};
    TEST_ASSERT_TRUE(devices.registerChannel(RES_RELAY, 0x01, relayHandler, &relay));

    float value = 0.0f;
    TEST_ASSERT_TRUE(devices.apply(RES_RELAY, 0x01, ACT_ON, 0, value));
    TEST_ASSERT_EQUAL_FLOAT(1.0f, value);
    TEST_ASSERT_TRUE(relay.state);

    TEST_ASSERT_FALSE(devices.apply(RES_DIMMER, 0x01, ACT_ON, 0, value));
}

void test_device_manager_auto_off_timer() {
    DeviceManager devices;
    FakeRelay relay = {false, 0};
    devices.registerChannel(RES_RELAY, 0x01, relayHandler, &relay);

    float value = 0.0f;
    TEST_ASSERT_TRUE(devices.apply(RES_RELAY, 0x01, ACT_ON, 1000, value));

    devices.update(10000);
    TEST_ASSERT_TRUE(relay.state);
    devices.update(10500);
    TEST_ASSERT_TRUE(relay.state);
    devices.update(11000);
    TEST_ASSERT_FALSE(relay.state);
}

void test_device_manager_ramp_is_non_blocking() {
    DeviceManager devices;
    float level = 0.0f;
    devices.registerChannel(RES_DIMMER, 0x01, dimmerHandler, &level);

    float value = 0.0f;
    TEST_ASSERT_TRUE(devices.apply(RES_DIMMER, 0x01, ACT_SET_VALUE, packSetValue(100, 1000), value));
    TEST_ASSERT_EQUAL_FLOAT(0.0f, level);

    devices.update(0);
    devices.update(500);
    TEST_ASSERT_EQUAL_FLOAT(50.0f, level);
    devices.update(1000);
    TEST_ASSERT_EQUAL_FLOAT(100.0f, level);
}

void test_config_store_roundtrip_with_crc() {
    MemoryStorage storage;
    ConfigStore config(storage);
    config.begin(0x0016);
    config.setNodeIdMode(NODE_ID_AUTOMATIC);
    TEST_ASSERT_TRUE(config.addRule(makeShortClickRule()));
    TEST_ASSERT_TRUE(config.save());

    ConfigStore reloaded(storage);
    TEST_ASSERT_TRUE(reloaded.begin(0x0001));
    TEST_ASSERT_EQUAL_UINT16(0x0016, reloaded.nodeId());
    TEST_ASSERT_EQUAL_UINT8(NODE_ID_AUTOMATIC, reloaded.nodeIdMode());
    TEST_ASSERT_EQUAL_UINT8(1, reloaded.ruleCount());
    TEST_ASSERT_EQUAL_UINT16(0x0005, reloaded.rule(0).source_node);
    TEST_ASSERT_EQUAL_UINT8(EVT_SHORT_CLICK, reloaded.rule(0).event);
    TEST_ASSERT_EQUAL_UINT8(RES_RELAY, reloaded.rule(0).target_resource);
}

void test_remote_identity_and_listen_filter_configuration(void) {
    VirtualBus wire;
    NativeCanBus controller_bus(&wire);
    NativeCanBus target_bus(&wire);
    CanNode controller(controller_bus, 0x0001);
    CanNode target(target_bus, 0x0016);
    controller.begin();
    target.begin();

    MemoryStorage storage;
    ConfigStore config(storage);
    config.begin(0x0016);
    RuleEngine rules(target, config);
    rules.begin();

    const uint8_t id_payload[2] = {0x00, 0x22};
    TEST_ASSERT_EQUAL_UINT8(CAN_OK,
                             controller.sendConfig(0x16, CFG_SET_NODE_ID, id_payload, 2));
    target.poll(1000);
    TEST_ASSERT_EQUAL_UINT16(0x0022, target.nodeId());
    TEST_ASSERT_EQUAL_UINT8(NODE_ID_MANUAL, target.nodeIdMode());

    const uint8_t mode_payload[1] = {NODE_ID_AUTOMATIC};
    TEST_ASSERT_EQUAL_UINT8(CAN_OK,
                             controller.sendConfig(0x22, CFG_SET_NODE_MODE, mode_payload, 1));
    target.poll(2000);
    TEST_ASSERT_EQUAL_UINT8(NODE_ID_AUTOMATIC, target.nodeIdMode());

    const uint8_t filter_payload[4] = {0x00, 0x05, RES_ENV_SENSOR, 0x01};
    TEST_ASSERT_EQUAL_UINT8(CAN_OK,
                             controller.sendConfig(0x22, CFG_SUBSCRIBE, filter_payload, 4));
    target.poll(3000);
    TEST_ASSERT_EQUAL_UINT8(1, target.listenFilterCount());
}

void test_config_store_rejects_corrupted_block() {
    MemoryStorage storage;
    ConfigStore config(storage);
    config.begin(0x0016);
    config.addRule(makeShortClickRule());
    config.save();

    storage.corrupt(kConfigHeaderBytes + 3);

    ConfigStore reloaded(storage);
    TEST_ASSERT_FALSE(reloaded.begin(0x0007));
    TEST_ASSERT_EQUAL_UINT16(0x0007, reloaded.nodeId());
    TEST_ASSERT_EQUAL_UINT8(0, reloaded.ruleCount());
}

void test_config_store_empty_medium_uses_defaults() {
    MemoryStorage storage;
    ConfigStore config(storage);
    TEST_ASSERT_FALSE(config.begin(0x0020));
    TEST_ASSERT_EQUAL_UINT16(0x0020, config.nodeId());
    TEST_ASSERT_EQUAL_UINT8(0, config.ruleCount());
}

void test_rule_engine_executes_remote_event_locally() {
    VirtualBus wire;
    NativeCanBus bus_a(&wire);
    NativeCanBus bus_b(&wire);

    CanNode sensor(bus_a, 0x0005);
    CanNode actuator(bus_b, 0x0016);
    sensor.begin();
    actuator.begin();

    MemoryStorage storage;
    ConfigStore config(storage);
    config.begin(0x0016);
    config.addRule(makeShortClickRule());

    RuleEngine rules(actuator, config);
    rules.begin();

    FakeRelay relay = {false, 0};
    actuator.registerResource(RES_RELAY, 0x02, relayHandler, &relay);

    sensor.publishInputEvent(0x01, EVT_SHORT_CLICK);
    actuator.poll(1000);

    TEST_ASSERT_TRUE(relay.state);
    TEST_ASSERT_EQUAL_UINT8(1, relay.calls);
}

void test_rule_engine_ignores_other_sources_and_events() {
    VirtualBus wire;
    NativeCanBus bus_a(&wire);
    NativeCanBus bus_b(&wire);

    CanNode other(bus_a, 0x0009);
    CanNode actuator(bus_b, 0x0016);
    other.begin();
    actuator.begin();

    MemoryStorage storage;
    ConfigStore config(storage);
    config.begin(0x0016);
    config.addRule(makeShortClickRule());

    RuleEngine rules(actuator, config);
    rules.begin();

    FakeRelay relay = {false, 0};
    actuator.registerResource(RES_RELAY, 0x02, relayHandler, &relay);

    /* Nodo equivocado. */
    other.publishInputEvent(0x01, EVT_SHORT_CLICK);
    actuator.poll(1000);
    TEST_ASSERT_FALSE(relay.state);
}

void test_rule_engine_threshold_trigger() {
    VirtualBus wire;
    NativeCanBus bus_a(&wire);
    NativeCanBus bus_b(&wire);

    CanNode sensor(bus_a, 0x0005);
    CanNode actuator(bus_b, 0x0016);
    sensor.begin();
    actuator.begin();

    MemoryStorage storage;
    ConfigStore config(storage);
    config.begin(0x0016);

    BindingRule rule = makeShortClickRule();
    rule.source_resource = RES_ENV_SENSOR;
    rule.trigger = TRIG_VALUE_GREATER;
    rule.threshold = 28.0f;
    rule.action = ACT_ON;
    config.addRule(rule);

    RuleEngine rules(actuator, config);
    rules.begin();

    FakeRelay relay = {false, 0};
    actuator.registerResource(RES_RELAY, 0x02, relayHandler, &relay);

    sensor.publishTelemetry(RES_ENV_SENSOR, 0x01, 24.0f);
    actuator.poll(1000);
    TEST_ASSERT_FALSE(relay.state);

    sensor.publishTelemetry(RES_ENV_SENSOR, 0x01, 31.5f);
    actuator.poll(2000);
    TEST_ASSERT_TRUE(relay.state);
}

void test_rule_engine_sdo_programs_and_persists_rule() {
    VirtualBus wire;
    NativeCanBus bus_gw(&wire);
    NativeCanBus bus_node(&wire);

    CanNode gateway(bus_gw, 0x0001);
    CanNode actuator(bus_node, 0x0016);
    gateway.begin();
    actuator.begin();

    MemoryStorage storage;
    ConfigStore config(storage);
    config.begin(0x0016);

    RuleEngine rules(actuator, config);
    rules.begin();

    FakeRelay relay = {false, 0};
    actuator.registerResource(RES_RELAY, 0x02, relayHandler, &relay);

    uint8_t raw[kBindingRuleBytes];
    ConfigStore::serializeRule(makeShortClickRule(), raw);

    const uint8_t target = 0x16;
    uint8_t payload[6];
    payload[0] = 0xFF; /* anexar al final de la tabla */
    gateway.sendConfig(target, CFG_RULE_BEGIN, payload, 1);

    for (uint8_t segment = 0; segment < 4; ++segment) {
        payload[0] = segment;
        for (uint8_t i = 0; i < 5; ++i) {
            payload[1 + i] = raw[segment * 5 + i];
        }
        gateway.sendConfig(target, CFG_RULE_CHUNK, payload, 6);
    }

    writeUint16BE(payload, crc16(raw, kBindingRuleBytes));
    gateway.sendConfig(target, CFG_RULE_COMMIT, payload, 2);

    actuator.poll(1000);
    TEST_ASSERT_EQUAL_UINT8(1, config.ruleCount());

    /* La regla quedo persistida: otra instancia la recupera del mismo medio. */
    ConfigStore reloaded(storage);
    TEST_ASSERT_TRUE(reloaded.begin(0x0000));
    TEST_ASSERT_EQUAL_UINT8(1, reloaded.ruleCount());
    TEST_ASSERT_EQUAL_UINT8(EVT_SHORT_CLICK, reloaded.rule(0).event);
}

void test_rule_engine_sdo_rejects_bad_crc() {
    VirtualBus wire;
    NativeCanBus bus_gw(&wire);
    NativeCanBus bus_node(&wire);

    CanNode gateway(bus_gw, 0x0001);
    CanNode actuator(bus_node, 0x0016);
    gateway.begin();
    actuator.begin();

    MemoryStorage storage;
    ConfigStore config(storage);
    config.begin(0x0016);
    RuleEngine rules(actuator, config);
    rules.begin();

    uint8_t raw[kBindingRuleBytes];
    ConfigStore::serializeRule(makeShortClickRule(), raw);

    const uint8_t target = 0x16;
    uint8_t payload[6];
    payload[0] = 0xFF;
    gateway.sendConfig(target, CFG_RULE_BEGIN, payload, 1);
    for (uint8_t segment = 0; segment < 4; ++segment) {
        payload[0] = segment;
        for (uint8_t i = 0; i < 5; ++i) {
            payload[1 + i] = raw[segment * 5 + i];
        }
        gateway.sendConfig(target, CFG_RULE_CHUNK, payload, 6);
    }
    writeUint16BE(payload, static_cast<uint16_t>(crc16(raw, kBindingRuleBytes) ^ 0x00FF));
    gateway.sendConfig(target, CFG_RULE_COMMIT, payload, 2);

    actuator.poll(1000);
    TEST_ASSERT_EQUAL_UINT8(0, config.ruleCount());
}

void test_node_publishes_state_when_timer_expires() {
    VirtualBus wire;
    NativeCanBus bus_node(&wire);
    NativeCanBus bus_monitor(&wire);

    CanNode node(bus_node, 0x0016);
    CanNode monitor(bus_monitor, 0x0001);
    node.begin();
    monitor.begin();

    FakeRelay relay = {false, 0};
    node.registerResource(RES_RELAY, 0x01, relayHandler, &relay);

    node.applyLocal(RES_RELAY, 0x01, ACT_ON, 500);
    node.poll(1000);
    TEST_ASSERT_TRUE(relay.state);

    node.poll(1600);
    TEST_ASSERT_FALSE(relay.state);

    /* El apagado autonomo se difunde al bus. */
    CanFrame frame;
    bool state_seen = false;
    while (bus_monitor.receive(frame) == CAN_OK) {
        const CanId id = frame.fields();
        if (id.msg_type == MSG_STATE && id.source == 0x0016 && frame.resource() == RES_RELAY) {
            state_seen = (frameValue(frame) == 0.0f);
        }
    }
    TEST_ASSERT_TRUE(state_seen);
}

int main(int, char **) {
    UNITY_BEGIN();
    RUN_TEST(test_device_manager_registers_and_applies);
    RUN_TEST(test_device_manager_auto_off_timer);
    RUN_TEST(test_device_manager_ramp_is_non_blocking);
    RUN_TEST(test_config_store_roundtrip_with_crc);
    RUN_TEST(test_remote_identity_and_listen_filter_configuration);
    RUN_TEST(test_config_store_rejects_corrupted_block);
    RUN_TEST(test_config_store_empty_medium_uses_defaults);
    RUN_TEST(test_rule_engine_executes_remote_event_locally);
    RUN_TEST(test_rule_engine_ignores_other_sources_and_events);
    RUN_TEST(test_rule_engine_threshold_trigger);
    RUN_TEST(test_rule_engine_sdo_programs_and_persists_rule);
    RUN_TEST(test_rule_engine_sdo_rejects_bad_crc);
    RUN_TEST(test_node_publishes_state_when_timer_expires);
    return UNITY_END();
}

void setUp() {}
void tearDown() {}# Futuras mejoras de PCD_CAN

Estado de referencia: **0.7.0**.

## Implementado en 0.6.0

- Expiracion de nodos en `NodeRegistry` despues de tres heartbeats perdidos.
- Politica `TunnelRelayGuard` para segmentar y deduplicar frames durante una ventana configurable.
- Ejemplo LAN completo `examples/CanLanBridgeGateway` con dos gateways simetricos.
- Paginas web de estado, configuracion de peer y simulacion de dispositivos remotos.
- Documentacion de despliegue, anti-loop y limites de seguridad.
- Catalogo extendido de recursos con nombres legibles y perfiles UI.
- Bridges agnosticos CANopen, NMEA2000 y KNX bidireccionales.
- `OtaWindowController` con control de ventana, ACK y mascara de faltantes.
- Contrato `ITunnelAuthenticator` para HMAC/AEAD inyectado por la aplicacion.
- Version explicita de protocolo de tunel.

## Siguiente prioridad

1. Implementar la autenticacion criptografica concreta en la aplicacion usando `ITunnelAuthenticator`.
2. Bootloader receptor OTA para ESP32, ATmega2560 y ATmega328P.
3. Persistencia opcional del inventario `NodeRegistry` y nombre amigable por nodo.
4. Expiracion diferenciada por tipo de nodo y diagnostico de perdida de heartbeat.
5. API web generada desde `NodeRegistry`, con autenticacion, CSRF y control de permisos.
6. Pruebas de interoperabilidad con dos ESP32 fisicos, MCP2515, W5500 y trafico LAN real.
7. Fuzzing de `decodeTunnelFrame()`, `decodeId()` y comandos SDO antes de publicar una release mayor.
8. Perfiles declarativos de recursos para Matter, Zigbee y ESPHome mantenidos fuera de `src/`.
9. Negociacion formal de versionado/compatibilidad de frames de tunel.
10. Herramienta de configuracion de escritorio que use el mismo protocolo CAN, sin USB propietario.
11. Perfiles estandarizados de unidades y escalas para NMEA2000, CANopen y KNX.
12. Generacion automatica de paginas web desde `resourceName()` y `NodeRegistry`.

## Criterio para 1.0.0

La libreria no se considera de produccion mayor hasta tener:

- autenticacion o aislamiento de red documentado para tuneles,
- bootloader OTA receptor probado con rollback o estrategia de recuperacion,
- pruebas de hardware y de perdida/reconexion de red,
- contrato de compatibilidad de protocolo versionado,
- revision de consumo de RAM/flash en cada placa soportada,
- ejemplos LAN y web revisados contra el stack concreto de la aplicacion.

Mientras esos puntos sigan abiertos, las releases `0.x` reflejan correctamente
que el protocolo y el nucleo son utilizables, pero la seguridad y el firmware de
produccion dependen del proyecto que los integra.; Ecosistema domotico/industrial descentralizado sobre CAN Bus 29 bits (PCD v1)
;
;   native          -> pruebas unitarias del protocolo en escritorio (layout A)
;   native_v2       -> pruebas del layout B (segmento + direccion de 8 bits)
;   esp32_gateway   -> gateway / puente multiprotocolo (TWAI)
;   esp32_hmi       -> pantalla tactil CAN
;   atmega2560_node -> nodo de campo de alta densidad (MCP2515)
;   atmega328p_node -> nodo de campo compacto (MCP2515)

[platformio]
default_envs = native

; El arbol tambien es una libreria Arduino/PlatformIO instalable: las cabeceras
; viven junto a las fuentes en src/ y src/main.cpp solo se compila cuando se
; construye un firmware (-DPCD_BUILD_FIRMWARE).

[env]
build_flags =
    -Isrc
    -Wall
    -Wextra

; Pruebas del layout A (por defecto) de todos los modulos. El layout B tiene su
; propio entorno porque cambia los desplazamientos del identificador de 29 bits.
[env:native]
platform = native
test_framework = unity
test_build_src = yes
test_ignore = test_protocol_v2
build_src_filter = +<*> -<main.cpp> -<hal/hal_can_esp32.cpp> -<hal/hal_can_mcp2515.cpp>
build_flags =
    ${env.build_flags}
    -DCAN_LOG_LEVEL=0
    -std=c++11

; Pruebas del layout B (PCD v2): destino 8 bits, origen 8 bits y segmento 5 bits.
[env:native_v2]
platform = native
test_framework = unity
test_build_src = yes
test_filter = test_protocol_v2
build_src_filter = +<*> -<main.cpp> -<hal/hal_can_esp32.cpp> -<hal/hal_can_mcp2515.cpp>
build_flags =
    ${env.build_flags}
    -DCAN_LOG_LEVEL=0
    -DPCD_ID_LAYOUT_V2=1
    -std=c++11

[env:esp32_gateway]
platform = espressif32
board = esp32dev
framework = arduino
monitor_speed = 115200
build_src_filter = +<*> -<.git/> -<hal/hal_can_mcp2515.cpp> -<hal/hal_can_native.cpp>
build_flags =
    ${env.build_flags}
    -DPCD_BUILD_FIRMWARE
    -DCAN_LOG_LEVEL=2
    -DFEATURE_OTA_MANAGER=1
    -DFEATURE_WEB_SERVER=1
    -DFEATURE_MQTT_BRIDGE=1
    -DFEATURE_TUNNEL_BRIDGE=1
    -DFEATURE_MODBUS_BRIDGE=1

[env:esp32_hmi]
platform = espressif32
board = esp32dev
framework = arduino
monitor_speed = 115200
build_src_filter = +<*> -<.git/> -<hal/hal_can_mcp2515.cpp> -<hal/hal_can_native.cpp>
build_flags =
    ${env.build_flags}
    -DPCD_BUILD_FIRMWARE
    -DCAN_LOG_LEVEL=1

[env:atmega2560_node]
platform = atmelavr
board = megaatmega2560
framework = arduino
monitor_speed = 115200
build_src_filter = +<*> -<.git/> -<hal/hal_can_esp32.cpp> -<hal/hal_can_native.cpp>
build_flags =
    ${env.build_flags}
    -DPCD_BUILD_FIRMWARE
    -DCAN_LOG_LEVEL=0

[env:atmega328p_node]
platform = atmelavr
board = uno
framework = arduino
monitor_speed = 115200
build_src_filter = +<*> -<.git/> -<hal/hal_can_esp32.cpp> -<hal/hal_can_native.cpp>
build_flags =
    ${env.build_flags}
    -DPCD_BUILD_FIRMWARE
    -DCAN_LOG_LEVEL=0
    -DCAN_MAX_SUBSCRIPTIONS=8
    -DCAN_MAX_CHANNELS=8
    -DCAN_MAX_RULES=8# 4. Referencia de API

Todo vive en el espacio de nombres `pcd`. Basta con incluir `<PCD_CAN.h>`.

## 4.1 `CanNode`

Capa de aplicacion del protocolo: filtra por destino, despacha comandos a los
recursos locales, difunde estado, mantiene suscripciones y emite el heartbeat.

```cpp
CanNode(ICanBus &bus, uint16_t node_id);

CanStatus begin(uint32_t bitrate = CAN_BUS_BITRATE);
void      poll(uint32_t now_ms);              // llamar en cada loop()
bool      handleFrame(const CanFrame &frame);
```

### Recursos y acciones

```cpp
bool registerResource(uint8_t resource, uint8_t channel,
                      ResourceHandler handler, void *ctx = 0);

bool applyLocal(uint8_t resource, uint8_t channel,
                uint8_t action, uint32_t param = 0);

DeviceManager &devices();
```

`applyLocal()` aplica el comando y difunde el estado resultante: es la forma
correcta de reaccionar a una tecla fisica.

### Emision

```cpp
CanStatus sendCommand(uint8_t target, uint8_t resource, uint8_t channel,
                      uint8_t action, uint32_t param = 0);
CanStatus publishState(uint8_t resource, uint8_t channel, float value,
                       uint16_t flags = DIAG_NONE);
CanStatus publishTelemetry(uint8_t resource, uint8_t channel, float value,
                           uint16_t flags = DIAG_NONE);
CanStatus publishInputEvent(uint8_t channel, uint8_t event);
CanStatus sendConfig(uint8_t target, uint8_t sub_command,
                     const uint8_t *payload, uint8_t payload_len);
CanStatus sendConfigAck(const uint8_t *payload, uint8_t payload_len);
CanStatus sendHeartbeat(uint32_t now_ms);
```

### Escucha

```cpp
bool subscribe(uint16_t source, uint8_t resource, uint8_t channel,
               StateListener listener, void *ctx = 0);   // kAnySource / kAnyChannel
void onConfig(ConfigListener listener, void *ctx = 0);
void onAnyFrame(FrameListener listener, void *ctx = 0);
```

`onAnyFrame()` recibe toda trama ajena: lo usan el motor de reglas, los
registradores y los puentes del gateway.

### Callbacks

```cpp
typedef bool (*ResourceHandler)(uint8_t channel, uint8_t action, uint32_t param,
                                float &out_value, void *ctx);
typedef void (*StateListener)(const CanFrame &frame, float value, void *ctx);
typedef void (*ConfigListener)(const CanFrame &frame, void *ctx);
typedef void (*FrameListener)(const CanFrame &frame, void *ctx);
```

El manejador de recurso devuelve `false` para rechazar un comando: en ese caso no
se difunde estado.

## 4.2 Identidad, descubrimiento y filtros de escucha

El nodo puede trabajar con ID manual o automático:

```cpp
uint16_t id = pcd::deriveAutomaticNodeId(unique_hardware_value);
pcd::CanNode node(bus, id);
node.setNodeIdMode(pcd::NODE_ID_AUTOMATIC);
node.setAutomaticNodeId(unique_hardware_value);
```

`deriveAutomaticNodeId()` produce siempre un valor válido entre `0x0001` y
`0x3FFF` para una misma identidad y semilla. No reemplaza una asignación
centralizada: dos placas con la misma identidad pueden colisionar.

En el primer `poll()` se anuncian el modo de ID y la cantidad de recursos,
seguidos por una trama `DISCOVERY_RESOURCE` por canal. Un gateway puede pedirlo
otra vez con `makeDiscoveryRequest()`.

```cpp
node.publishDiscovery();
node.addListenFilter(pcd::kAnySource, pcd::RES_ENV_SENSOR, pcd::kAnyChannel);
node.subscribe(pcd::kAnySource, pcd::RES_ENV_SENSOR, pcd::kAnyChannel, onSensor);
```

La configuración remota usa `CFG_SET_NODE_ID`, `CFG_SET_NODE_MODE`,
`CFG_SUBSCRIBE` y `CFG_CLEAR_SUBSCRIPTIONS`. El cambio de ID se aplica en
memoria y se persiste; no hace falta reiniciar para que el nodo empiece a usar
el nuevo origen CAN.

## 4.3 `DeviceManager`

Administra los canales heterogeneos del nodo con una maquina de estados por
canal (`PHASE_IDLE`, `PHASE_RAMPING`, `PHASE_TIMED`). `CanNode` ya contiene uno y
lo actualiza dentro de `poll()`.

```cpp
bool registerChannel(uint8_t resource, uint8_t channel,
                     ResourceHandler handler, void *ctx = 0);
bool apply(uint8_t resource, uint8_t channel, uint8_t action,
           uint32_t param, float &out_value);
void update(uint32_t now_ms);
void cancelPending(uint8_t resource, uint8_t channel);
void setFlags(uint8_t resource, uint8_t channel, uint16_t flags);
bool value(uint8_t resource, uint8_t channel, float &out_value) const;
```

Interpretacion del parametro:

| Accion | `param` |
|--------|---------|
| `ACT_ON`, `ACT_TOGGLE` | milisegundos hasta el apagado automatico (0 = sin limite) |
| `ACT_OFF` | ignorado |
| `ACT_SET_VALUE` | `packSetValue(valor, fade_ms)`: valor en los 16 bits altos, tiempo de rampa en los bajos |

Ejemplo: encender una luz de escalera por 2 minutos y llevar un dimmer al 80% en
3 segundos, sin bloquear el `loop()`:

```cpp
node.applyLocal(RES_RELAY,  0x01, ACT_ON,        120000);
node.applyLocal(RES_DIMMER, 0x01, ACT_SET_VALUE, packSetValue(80, 3000));
```

Cuando el temporizador vence o la rampa termina, el gestor difunde el estado por
si mismo (`StateEmitter`), cerrando el lazo de realimentacion.

## 4.4 `ConfigStore` y `StorageAdapter`

Persistencia del Node-ID y de las reglas, con cabecera, version y CRC-16.

```cpp
class StorageAdapter {
    virtual bool begin();
    virtual bool read(uint16_t offset, uint8_t *data, uint16_t length);
    virtual bool write(uint16_t offset, const uint8_t *data, uint16_t length);
    virtual bool commit();
    virtual uint16_t capacity() const;
};
```

Backends incluidos:

| Clase | Plataforma | Medio |
|-------|-----------|-------|
| `MemoryStorage` | escritorio / cualquiera | RAM (pruebas) |
| `EepromStorage` | AVR | EEPROM interna, con `EEPROM.update` |
| `NvsStorage` | ESP32 | NVS via `Preferences`, blob unico |

```cpp
pcd::EepromStorage storage;
pcd::ConfigStore config(storage);

config.begin(0x0016);        // false => bloque vacio o CRC invalido
config.addRule(rule);
config.save();
```

Disposicion del bloque:

```
offset 0  : magic 'PC' (2)  version (1)  cantidad de reglas (1)  node_id (2)
offset 6  : modo de ID (0 manual, 1 automatico)
offset 7  : reglas de 20 bytes cada una, big-endian
final     : CRC-16/CCITT de la cabecera + las reglas (2)
```

Si el CRC no valida, `begin()` devuelve `false` y el nodo arranca con los valores
por defecto en lugar de con reglas a medio escribir.

## 4.5 `RuleEngine` y `BindingRule`

```cpp
struct BindingRule {
    uint16_t source_node;      // 0x0000 = cualquiera
    uint8_t  source_resource;
    uint8_t  source_channel;   // kAnyChannel = cualquiera
    uint8_t  trigger;          // TRIG_EVENT / TRIG_VALUE_* / TRIG_ANY
    uint8_t  event;            // evento esperado en TRIG_EVENT
    float    threshold;        // umbral en los disparos por valor
    uint8_t  target_resource;  // recurso local a accionar
    uint8_t  target_channel;
    uint8_t  action;
    uint32_t param;
};
```

"Si la entrada 1 del nodo 0x0005 informa una pulsacion corta, conmutar el rele
del canal 2 de este nodo":

```cpp
pcd::BindingRule rule;
rule.source_node     = 0x0005;
rule.source_resource = pcd::RES_DIGITAL_INPUT;
rule.source_channel  = 0x01;
rule.trigger         = pcd::TRIG_EVENT;
rule.event           = pcd::EVT_SHORT_CLICK;
rule.target_resource = pcd::RES_RELAY;
rule.target_channel  = 0x02;
rule.action          = pcd::ACT_TOGGLE;
rule.param           = 0;

config.addRule(rule);
config.save();

pcd::RuleEngine rules(node, config);
rules.begin();          // engancha onAnyFrame() y onConfig()
```

La evaluacion ocurre en el propio nodo que ejecuta la accion: no hay gateway en
el camino.

> Cuidado con los lazos: una regla disparada por `MSG_STATE` que produce otro
> `MSG_STATE` puede realimentarse entre dos nodos. Preferir `TRIG_EVENT` sobre
> entradas digitales para las vinculaciones de tecla.

## 4.6 Programacion remota por SDO

Una regla ocupa 20 bytes y no entra en los 6 bytes utiles de una trama, por lo
que se transfiere segmentada. Sub-comandos (byte 1 de un `MSG_CONFIG`):

| Sub-comando | Valor | Payload |
|-------------|------:|---------|
| `CFG_SET_NODE_ID` | 0x01 | nuevo Node-ID (2 bytes BE) |
| `CFG_RULE_BEGIN` | 0x02 | indice a reemplazar, 0xFF = anexar |
| `CFG_RULE_CHUNK` | 0x03 | segmento (0..3) + 5 bytes de la regla |
| `CFG_RULE_COMMIT` | 0x04 | CRC-16 de los 20 bytes |
| `CFG_RULE_DELETE` | 0x05 | indice |
| `CFG_RULE_CLEAR` | 0x06 | - |
| `CFG_SAVE` | 0x07 | - |
| `CFG_RULE_COUNT` | 0x08 | - |
| `CFG_SET_NODE_MODE` | 0x09 | byte 0: `NODE_ID_MANUAL` o `NODE_ID_AUTOMATIC` |
| `CFG_SUBSCRIBE` | 0x0A | origen (2 bytes BE), recurso, canal |
| `CFG_UNSUBSCRIBE` | 0x0B | limpia filtros de escucha |
| `CFG_CLEAR_SUBSCRIPTIONS` | 0x0C | limpia filtros de escucha |
| `CFG_ACK` | 0x7F | sub-comando + codigo de resultado |

La regla solo se aplica y se persiste si llegaron los cuatro segmentos y el CRC
coincide; si no, el nodo responde `CFG_STATUS_CRC_ERROR` y descarta el buffer.

## 4.7 `Gateway` y `NodeRegistry`

`Gateway` mantiene un inventario estático de nodos descubiertos. El registro
consume `MSG_HEARTBEAT`, `DISCOVERY_ANNOUNCE` y `DISCOVERY_RESOURCE` y conserva
Node-ID, modo de identidad, uptime, salud y recursos por canal:

```cpp
const pcd::DiscoveredNode *node = gateway.nodes().find(0x0016);
if (node != 0) {
    for (uint8_t i = 0; i < node->resource_count; ++i) {
        // node->resources[i].resource / channel
    }
}
```

Los límites por defecto son `CAN_MAX_DISCOVERED_NODES=16` y
`CAN_MAX_DISCOVERED_RESOURCES=16`; se pueden sobrescribir con `build_flags`.
El backend web debe serializar este registro en `/api/nodes` y traducir los
tipos de recurso a nombres legibles.

## 4.8 HAL: `ICanBus`

```cpp
CanStatus begin(uint32_t bitrate = CAN_BUS_BITRATE);
void      end();
CanStatus send(const CanFrame &frame, uint32_t timeout_ms = 0);
CanStatus receive(CanFrame &frame, uint32_t timeout_ms = 0);
void      setFilter(const CanFilter &filter);
bool      isBusOff() const;
CanStatus recover();
```

| Implementacion | Constructor |
|----------------|-------------|
| `Esp32TwaiBus` | `Esp32TwaiBus(tx_pin, rx_pin)` |
| `Mcp2515Bus` | `Mcp2515Bus(cs_pin, MCP_CLOCK_16MHZ o MCP_CLOCK_8MHZ, int_pin)` |
| `NativeCanBus` | `NativeCanBus(VirtualBus *bus)` |

Codigos de estado: `CAN_OK`, `CAN_ERR_INIT`, `CAN_ERR_TX_FAIL`, `CAN_ERR_TX_BUSY`,
`CAN_ERR_NO_DATA`, `CAN_ERR_BUS_OFF`, `CAN_ERR_NOT_STARTED`.

## 4.9 Utilidades del protocolo

```cpp
uint32_t encodeId(uint8_t priority, uint8_t msg_type, uint8_t target, uint16_t source);
CanId    decodeId(uint32_t raw_id);

CanFrame makeCommand(...);   CanFrame makeStateBroadcast(...);
CanFrame makeTelemetry(...); CanFrame makeInputEvent(...);
CanFrame makeHeartbeat(...); CanFrame makeConfig(...);
CanFrame makeOtaData(...);

float    frameValue(const CanFrame &frame);
uint16_t frameFlags(const CanFrame &frame);
uint32_t frameParam(const CanFrame &frame);
uint16_t crc16(const uint8_t *data, uint16_t length, uint16_t seed = 0xFFFF);
```

## 4.10 Capa de servicios del sistema (`system_api`)

El nucleo **no** llama a `millis()`, `delay()` ni `Serial` de forma directa.
La aplicacion inyecta estos servicios una vez, tipicamente en `setup()`:

```cpp
struct pcd::SystemApi {
    uint32_t (*millis)();                          // reloj monotono en ms
    void     (*delay_ms)(uint32_t ms);             // bloqueo en ms
    void     (*log)(uint8_t level, const char *fmt, va_list args);
    void     (*lock)();                            // entrar en seccion critica
    void     (*unlock)();                          // salir de seccion critica
};

void pcd::setSystemApi(const pcd::SystemApi *api);  // instalar
const pcd::SystemApi *pcd::systemApi();             // consultar
uint32_t pcd::systemMillis();                       // acceso corto
void     pcd::systemDelay(uint32_t ms);
```

Mapeo tipico por plataforma:

| Plataforma | `millis` | `delay_ms` | `log` |
|-----------|----------|------------|-------|
| Arduino | `millis` | `delay` | `vsnprintf` + `Serial.printf` |
| ESP-IDF | `esp_timer_get_time()/1000` | `vTaskDelay(pdMS_TO_TICKS(ms))` | `ESP_LOGI` / `ESP_LOGV` |
| FreeRTOS | `xTaskGetTickCount()` | `vTaskDelay(pdMS_TO_TICKS(ms))` | `printf` personalizado |
| STM32 Cube | `HAL_GetTick()` | `HAL_Delay()` | `printf` redirigido |
| PC / native | `std::chrono` | `std::this_thread::sleep_for` | `std::printf` |

### Motor de registro inyectable

Los macros `LOG_ERROR` / `LOG_INFO` / `LOG_DEBUG` se enrutan al sumidero
`SystemApi::log`. Con `CAN_LOG_LEVEL=0` el compilador elimina todas las cadenas.

### LockGuard

```cpp
{
    pcd::LockGuard lock;      // entra en seccion critica
    // ... cola, EEPROM, tabla ...
}                             // sale automaticamente
```

Prioridad: si `SystemApi` provee `lock()/unlock()` se usan (semaforo/critical
section). En AVR sin inyeccion cae a `cli()/sei()`. En bare-metal single-thread
no hace nada.

## 4.9 Bucle de eventos asincrono

Desacopla la ISR del procesamiento en el hilo principal:

```cpp
pcd::CanEventLoop loop;
loop.attach(myFrameProcessor, nullptr);

// desde la ISR del controlador CAN:
loop.enqueue(frame);          // ~µs, solo copia

// desde el loop() principal:
loop.tick();                   // drena la cola y llama a process(frame, ctx)
```

Tambien esta `RingBuffer<T, Capacity>`, un buffer SPSC lock-free que usa
`CanEventLoop` internamente.

## 4.10 `CanNodeTmpl<RxDepth>`

Nodo con buffer de RX dimensionado en tiempo de compilacion:

```cpp
pcd::CanNodeTmpl<4>  node(bus, 0x0016);   // ATmega328P
pcd::CanNodeTmpl<64> gateway(bus, 0x0001); // ESP32 gateway
```

Expone la misma interfaz que `CanNode` mas:

```cpp
bool enqueueFrame(const CanFrame &frame);  // desde ISR
void poll(uint32_t now_ms);                // drena el ring buffer, luego service
size_t pendingFrames() const;
```

## 4.11 Tunel CAN sobre IP (`TunnelEngine`)

```cpp
class pcd::ITunnelTransport {
    virtual bool send(uint16_t peer, const uint8_t *data, size_t len) = 0;
    virtual bool receive(uint16_t &peer_out, uint8_t *data, size_t max_len, size_t &len) = 0;
    virtual bool available() const = 0;
};

pcd::TunnelEngine tunnel(transport);
bool tunnel.sendFrame(uint16_t peer, const pcd::CanFrame &frame);
bool tunnel.receiveFrame(uint16_t &peer_out, pcd::CanFrame &frame);
```

Formato del datagrama (16 bytes, little-endian):

```text
[0]    magia 0xA5
[1..4] ID 29-bit, LSB primero
[5]    DLC
[6..13] payload (8 bytes)
[14..15] CRC-16 de los bytes 0..13
```

El transporte de red (UDP/TCP/WiFi/Ethernet) **no** viene con la libreria; lo
implementa la aplicacion (ver `docs/wiki/08-librerias-recomendadas.md`).# Puentes bidireccionales y comunicacion descentralizada

Version de referencia: **0.7.0**.

PCD_CAN sigue siendo una libreria de protocolo CAN personalizada. El bus CAN es el plano de control descentralizado: cada nodo ejecuta recursos y reglas localmente, y un gateway solo traduce protocolos o conecta segmentos.

## Regla de integracion

`src/` contiene contratos, codec y traducciones sin dependencias externas. Los ejemplos usan dependencias concretas solo para enseñar el adaptador:

```text
protocolo externo <-> adaptador de ejemplo <-> IBridge/ITunnelTransport <-> Gateway <-> CAN
```

No agregar `PubSubClient`, Matter, Zigbee, ESPHome, `Ethernet.h`, `WiFi.h`, Modbus ni TFT al manifiesto de la libreria.

## Direccion doble

| Puente | Entrada externa a CAN | Salida CAN a externo |
|---|---|---|
| MQTT | `.../set` -> `MqttBridge::buildCanonical()` | `MSG_STATE` -> `.../state` |
| Modbus | coil/register escrito -> `queueIncoming()` | estado -> coil/register |
| ESP-NOW | callback de paquete -> comando CAN | estado CAN -> `esp_now_send()` |
| Zigbee | atributo/command cluster -> CanonicalFrame | `MSG_STATE` -> atributo |
| Matter | command cluster -> CanonicalFrame | estado -> atributo Matter |
| ESPHome | API command -> CAN | `MSG_STATE` -> entidad |
| UDP/TCP/Ethernet | datagrama -> `TunnelEngine` -> CAN | CAN -> datagrama |
| TFT/SPI | toque -> `sendCommand()` | suscripcion -> pantalla |
| CANopen | PDO/SDO externo -> bridge | estado/comando -> PDO |
| NMEA2000 | PGN externo -> estado canónico | estado -> PGN |
| KNX | GroupValue -> estado canónico | estado -> GroupValue |

## Configuracion de escucha

- `addListenFilter(source, resource, channel)` restringe estados entregados a las suscripciones.
- `CFG_SUBSCRIBE` permite configurar ese filtro desde otro nodo CAN.
- `CFG_CLEAR_SUBSCRIPTIONS` lo elimina.
- `MSG_DISCOVERY_ANNOUNCE` informa modo de ID y cantidad.
- `MSG_DISCOVERY_RESOURCE` informa el tipo de recurso y canal.
- `Gateway::nodes()` mantiene el inventario para interfaces web y puentes.

## Matter y Zigbee

No hay una API universal suficientemente estable entre todos los cores Arduino. Por eso los ejemplos dejan tres funciones claras: publicar estado, recibir comando y convertir recursos. El proyecto debe mapear sus clusters/endpoints a `RES_RELAY`, `RES_DIMMER`, `RES_COVER` y sensores, sin cambiar el protocolo CAN.

## ESPHome

ESPHome puede conectarse por MQTT, API nativa o un componente externo. La opción se elige en el proyecto. El adaptador debe mantener la regla `comando externo -> CAN -> confirmacion MSG_STATE`; no marcar una entidad como activa antes de recibir el estado confirmado.

## Redes CAN

`TunnelEngine` serializa una trama CAN en 16 bytes con CRC. UDP sirve para baja latencia; TCP o Ethernet con W5500 sirven cuando el proyecto exige entrega fiable. Para mantener descentralización, cada gateway debe aplicar filtros, anti-bucle y una lista de peers, sin convertir el gateway en controlador único.

El ejemplo `examples/CanLanBridgeGateway` agrega dos paginas por gateway:
estado (`/`), configuracion del peer (`/config`) y simulacion de dispositivos
remotos (`/simulate`). `TunnelRelayGuard` evita loops y duplicados, pero no
autentica el trafico; para produccion usar una LAN aislada, VPN o agregar
HMAC/AEAD en el proyecto de aplicacion.

## Pantallas

Una TFT/SPI puede ser un nodo más. Debe suscribirse solo a los recursos que muestra y enviar comandos dirigidos al Node-ID correspondiente. No hace falta que conozca MQTT, Modbus ni la topología completa.

## Futuras mejoras recomendadas

1. Agregar autenticación y firma de comandos de configuración/OTA.
2. Implementar ventana ACK y bootloader receptor OTA para AVR/ESP32.
3. Añadir TTL/segment-id al túnel para anti-bucle formal.
4. Crear un `NodeRegistry` con expiración de heartbeat y persistencia opcional.
5. Definir perfiles de recursos para Matter/Zigbee/ESPHome sin acoplar SDKs.
6. Agregar pruebas de interoperabilidad con hardware real y fuzzing de frames.
7. Medir consumo de RAM/flash por bridge y permitir `build_flags` para excluir UI.
8. Incorporar un generador de API web a partir de `Gateway::nodes()`.# Implementacion web del gateway

Este documento describe como convertir los recursos web de `PCD_CAN` en una interfaz real para un ESP32. La libreria entrega la vista HTML y los contratos CAN; el proyecto de firmware elige el servidor HTTP, el filesystem y la autenticacion.

## Recursos incluidos

`src/web/web_pages.h` expone:

- `pcd::webAppHtml()`: aplicacion completa HTML/CSS/JS.
- `pcd::webViewName()`: nombres de las siete vistas.
- `pcd::webViewPath()`: rutas/hash para Resumen, Nodos, Rutas, OTA, Tunel, Diagnostico y Ajustes.

La pagina se sirve como un unico recurso en `/`. El navegador cambia de vista usando `/#nodes`, `/#ota`, etc., evitando duplicar HTML en la flash.

## API HTTP esperada

El ejemplo de interfaz consulta estos endpoints JSON:

| Endpoint | Metodo | Respuesta minima |
|---|---|---|
| `/api/summary` | GET | `nodes`, `frames_per_minute`, `can_status` |
| `/api/nodes` | GET | inventario de node ID, heartbeat y estado |
| `/api/routes` | GET | tabla de rutas y destino |
| `/api/ota/status` | GET | estado, progreso y error |
| `/api/tunnel/status` | GET | transporte, peers y datagramas |
| `/api/diagnostics` | GET | bus-off, errores, uptime y memoria |
| `/api/identity` | GET/POST | modo manual/automático e ID actual |
| `/api/listen-filters` | GET/POST | filtros de origen, recurso y canal |
| `/api/ota/abort` | POST | cancela la campaña OTA |

Los endpoints son un contrato de aplicación, no forman parte del núcleo PCD. Las respuestas pueden crecer sin romper la UI.

## Integracion con `WebServer.h`

```cpp
#include <PCD_CAN.h>
#include <WebServer.h>

WebServer http(80);

void setupWeb() {
    http.on("/", HTTP_GET, []() {
        http.send(200, "text/html; charset=utf-8", pcd::webAppHtml());
    });
    http.on("/api/summary", HTTP_GET, []() {
        http.send(200, "application/json", "{\"nodes\":1,\"frames_per_minute\":0,\"can_status\":\"ok\"}");
    });
    http.begin();
}

void loopWeb() {
    http.handleClient();
}
```

Para `ESPAsyncWebServer`, la ruta equivalente usa `request->send(200, "text/html", pcd::webAppHtml())`. En ambos casos, la autenticacion debe ejecutarse antes de responder a `/api/*`.

`/api/nodes` debe presentar cada nodo descubierto con esta forma mínima:

```json
{
    "nodes": [{
        "id": 22,
        "status": "online",
        "last_heartbeat": 123456,
        "online": true,
        "last_seen_ms": 123456,
        "id_mode": "manual",
        "resources": [{"type": 16, "name": "Rele", "channel": 1}]
    }]
}
```

El nombre visible se deriva del tipo de recurso (`RES_RELAY`, `RES_DIMMER`,
`RES_ENV_SENSOR`, etc.) y no de texto enviado por un nodo, evitando que una
identificación remota inyecte HTML en la pantalla.

## Situaciones cubiertas

- **Operacion:** resumen y actividad del bus.
- **Inventario:** nodos vivos y ultimo heartbeat.
- **Identidad:** selección manual/automática y Node-ID actual.
- **Escucha:** filtros por origen, recurso y canal, configurables vía API y CAN.
- **Enrutamiento:** inspeccion de reglas hacia puentes.
- **Mantenimiento:** progreso y cancelacion OTA.
- **Interconexion:** estado de tunel UDP/TCP.
- **Diagnostico:** bus-off, errores, memoria y uptime.
- **Ajustes:** enlaces al backend de configuracion, sin guardar credenciales en el HTML.

## Seguridad y limites

- No exponer el servidor sin autenticacion y sin TLS fuera de una LAN confiable.
- No insertar valores CAN directamente en HTML sin escapar; preferir JSON.
- El HTML es una UI de referencia, no un reemplazo de la logica de seguridad del proyecto.
- `webAppHtml()` aumenta el uso de flash del firmware; en AVR no se recomienda incluirlo.# Ejemplos PCD_CAN 0.7.0

Todos los ejemplos son sketches de aplicacion. Las librerias de terceros aparecen solo en `examples/` y nunca en `src/` ni en los manifiestos de PCD_CAN.

## Nodos y UI

- `NodoReleBoton`: un rele y un pulsador.
- `NodoMultiRecursos`: dos reles, dos dimmers y cuatro entradas.
- `ReglasPersistentes`: automatizaciones locales persistentes.
- `IdentidadManualAutomatica`: Node-ID manual o derivado de hardware.
- `DescubrimientoYFiltros`: anuncios y filtros de escucha.
- `PantallaTFTSPI`: pantalla TFT/SPI tactil como nodo bidireccional.
- `GatewayWebPCD`: UI web y endpoints del gateway.

## Puentes bidireccionales

- `BridgeMQTTBidireccional`: estados CAN <-> MQTT.
- `BridgeZigbeeBidireccional`: atributos Zigbee <-> CAN.
- `BridgeMatterBidireccional`: clusters Matter <-> CAN.
- `BridgeESPHomeBidireccional`: entidades ESPHome <-> CAN.
- `BridgeESPNowBidireccional`: paquetes ESP-NOW <-> CAN.
- `BridgeCANopenNmeaKnx`: CANopen, NMEA2000 y KNX <-> CAN.
- `CanBusModbusBidireccional`: coils/registers Modbus (TCP para Loxone) <-> CAN.
- `CanBusEntreRedes`: dos buses CAN unidos por UDP/TCP.
- `CanBusEthernetBidireccional`: CAN sobre Ethernet/W5500.
- `CanLanBridgeGateway`: dos redes CAN por LAN, paginas por gateway y simulacion remota.

## Topologia

- `HubArbolEstrella`: hub/star coupler multi-puerto para estrella o arbol, con
  validacion de cableado y reenvio anti-bucle.

Cada puente debe:

1. descubrir recursos mediante `MSG_DISCOVERY`,
2. configurar filtros con `addListenFilter()` o `CFG_SUBSCRIBE`,
3. traducir eventos externos a comandos CAN,
4. traducir `MSG_STATE` a estados externos,
5. evitar inventar estado cuando el nodo CAN no lo confirmó.

Ver `docs/puentes-bidireccionales.md` y `docs/wiki/09-recursos-y-protocolos-estandar.md`.#include "gateway/gateway.h"

#include "bridge/bridge.h"

namespace pcd {

Gateway::Gateway(CanNode &node, RouteTable &table)
    : node_(node),
      table_(table),
      router_(table),
    bridge_count_(0),
    now_ms_(0) {
    for (uint8_t i = 0; i < 4; ++i) {
        bridges_[i] = 0;
    }
}

void Gateway::begin(const GatewayConfig &config) {
    config_ = config;
    router_.attach(node_, config_.node_id);
    node_.onAnyFrame(&Gateway::frameTrampoline, this);
}

void Gateway::frameTrampoline(const CanFrame &frame, void *ctx) {
    static_cast<Gateway *>(ctx)->onCanFrame(frame);
}

void Gateway::onCanFrame(const CanFrame &frame) {
    nodes_.observe(frame, now_ms_);
    /* 1. El enrutador traduce y ejecuta la tabla de rutas. */
    router_.onCanFrame(frame);

    /* 2. Los bridges observan los estados para publicar hacia afuera. */
    const CanId id = frame.fields();
    if (id.msg_type == MSG_STATE) {
        CanonicalFrame canonical = CanonicalFrame::fromCanFrame(frame);
        for (uint8_t i = 0; i < bridge_count_; ++i) {
            if (bridges_[i] != 0) {
                bridges_[i]->process(canonical);
            }
        }
    }
}

bool Gateway::attachBridge(IBridge &bridge) {
    if (bridge_count_ >= 4) {
        return false;
    }
    bridges_[bridge_count_++] = &bridge;
    return true;
}

void Gateway::poll(uint32_t now_ms) {
    now_ms_ = now_ms;
    nodes_.expire(now_ms, CAN_HEARTBEAT_PERIOD_MS * 3UL);
    /* Drena los bridges: recibe entradas externas y las entrega al router. */
    for (uint8_t i = 0; i < bridge_count_; ++i) {
        IBridge *bridge = bridges_[i];
        if (bridge != 0 && bridge->available()) {
            CanonicalFrame incoming;
            if (bridge->buildCanonical(incoming)) {
                router_.process(incoming);
            }
        }
    }
    node_.poll(now_ms);
}

}  // namespace pcd#pragma once

/*
 * Gateway orquestador de alto nivel.
 *
 * Une CanNode + RouteTable + RoutingEngine + puentes en un solo objeto, de
 * modo que la aplicacion solo llame a `gateway.begin()`, `gateway.poll()` y
 * configure las reglas por la tabla (o por Web GUI). El usuario no escribe
 * cientos de lineas: define una `GatewayConfig` y conecta sus librerias de red
 * mediante los callbacks de los puentes.
 *
 * Flujo:
 *
 *   CanNode::onAnyFrame() -> Gateway::onCanFrame() -> RoutingEngine::process()
 *     -> RouteTable.match() -> ejecutar destino (CAN via node, o bridge externo)
 *
 * Los bridges (MQTT, Modbus, KNX, ESP-NOW, IP) se conectan con `attachBridge()`.
 */

#include <stdint.h>

#include "bridge/bridge.h"
#include "can_node.h"
#include "routing/route_table.h"
#include "routing/routing_engine.h"
#include "gateway/node_registry.h"

namespace pcd {

struct GatewayConfig {
    uint16_t node_id;         /* Node-ID del gateway (por convencion 0x0001) */
    uint32_t bitrate;         /* velocidad del bus CAN */
    bool publish_discovery;   /* publicar discovery Home Assistant */

    GatewayConfig()
        : node_id(0x0001), bitrate(CAN_BUS_BITRATE), publish_discovery(false) {}
};

class Gateway {
  public:
    Gateway(CanNode &node, RouteTable &table);

    /* Configura el gateway y engancha el RoutingEngine al CanNode. */
    void begin(const GatewayConfig &config);

    /* Llamar en el loop principal. Procesa el bus y drena los bridges. */
    void poll(uint32_t now_ms);

    /* Procesa una trama CAN (ya enganchada via onAnyFrame). */
    void onCanFrame(const CanFrame &frame);

    /* Registra un puente externo (MQTT, Modbus, KNX, ESP-NOW). */
    bool attachBridge(IBridge &bridge);

    /* Registra el callback de salida de la tabla de rutas hacia bridges. */
    void setSink(RoutingEngine::CanonicalSink sink, void *ctx) {
        router_.setSink(sink, ctx);
    }

    RoutingEngine &router() { return router_; }
    const RouteTable &table() const { return table_; }
    NodeRegistry &nodes() { return nodes_; }
    const NodeRegistry &nodes() const { return nodes_; }

  private:
    static void frameTrampoline(const CanFrame &frame, void *ctx);

    CanNode &node_;
    RouteTable &table_;
    RoutingEngine router_;
    GatewayConfig config_;
    IBridge *bridges_[4];
    uint8_t bridge_count_;
    NodeRegistry nodes_;
    uint32_t now_ms_;
};

}  // namespace pcd#include "can_node.h"

namespace pcd {

CanNode::CanNode(ICanBus &bus, uint16_t node_id)
    : bus_(bus),
      node_id_(node_id),
            node_id_mode_(NODE_ID_MANUAL),
      last_heartbeat_ms_(0),
      boot_ms_(0),
      boot_ms_valid_(false),
      heartbeat_sent_(false),
    discovery_sent_(false),
      subscription_count_(0),
    listen_filter_count_(0),
      config_listener_(0),
      config_ctx_(0),
      frame_listener_(0),
      frame_ctx_(0) {
    devices_.setStateEmitter(&CanNode::emitState, this);
}

void CanNode::setNodeId(uint16_t node_id) {
    if (isValidSource(node_id)) {
        node_id_ = node_id;
        discovery_sent_ = false;
    }
}

void CanNode::setAutomaticNodeId(uint32_t unique_value, uint16_t salt) {
    setNodeId(deriveAutomaticNodeId(unique_value, salt));
    node_id_mode_ = NODE_ID_AUTOMATIC;
}

CanStatus CanNode::begin(uint32_t bitrate) {
    const CanStatus status = bus_.begin(bitrate);
    if (status != CAN_OK) {
        return status;
    }
    bus_.setFilter(CanFilter::acceptAll());
    return CAN_OK;
}

bool CanNode::registerResource(uint8_t resource, uint8_t channel, ResourceHandler handler,
                               void *ctx) {
    return devices_.registerChannel(resource, channel, handler, ctx);
}

void CanNode::emitState(uint8_t resource, uint8_t channel, float value, uint16_t flags,
                        void *ctx) {
    static_cast<CanNode *>(ctx)->publishState(resource, channel, value, flags);
}

bool CanNode::subscribe(uint16_t source, uint8_t resource, uint8_t channel, StateListener listener,
                        void *ctx) {
    if (subscription_count_ >= CAN_MAX_SUBSCRIPTIONS || listener == 0) {
        return false;
    }
    Subscription &entry = subscriptions_[subscription_count_++];
    entry.source = source;
    entry.resource = resource;
    entry.channel = channel;
    entry.listener = listener;
    entry.ctx = ctx;
    return true;
}

bool CanNode::addListenFilter(uint16_t source, uint8_t resource, uint8_t channel) {
    if (listen_filter_count_ >= CAN_MAX_SUBSCRIPTIONS) {
        return false;
    }
    Subscription &entry = listen_filters_[listen_filter_count_++];
    entry.source = source;
    entry.resource = resource;
    entry.channel = channel;
    entry.listener = 0;
    entry.ctx = 0;
    return true;
}

void CanNode::clearListenFilters() {
    listen_filter_count_ = 0;
}

bool CanNode::acceptsListenFilter(const CanFrame &frame) const {
    if (listen_filter_count_ == 0) {
        return true;
    }
    const CanId id = frame.fields();
    for (uint8_t i = 0; i < listen_filter_count_; ++i) {
        const Subscription &filter = listen_filters_[i];
        if ((filter.source == kAnySource || filter.source == id.source) &&
            filter.resource == frame.resource() &&
            (filter.channel == kAnyChannel || filter.channel == frame.channel())) {
            return true;
        }
    }
    return false;
}

void CanNode::onConfig(ConfigListener listener, void *ctx) {
    config_listener_ = listener;
    config_ctx_ = ctx;
}

void CanNode::onAnyFrame(FrameListener listener, void *ctx) {
    frame_listener_ = listener;
    frame_ctx_ = ctx;
}

bool CanNode::isForThisNode(const CanId &id) const {
    return id.target == address() || id.target == kBroadcastTarget;
}

void CanNode::dispatchState(const CanFrame &frame) {
    if (!acceptsListenFilter(frame)) {
        return;
    }
    const CanId id = frame.fields();
    const float value = frameValue(frame);
    for (uint8_t i = 0; i < subscription_count_; ++i) {
        const Subscription &sub = subscriptions_[i];
        if (sub.source != kAnySource && sub.source != id.source) {
            continue;
        }
        if (sub.resource != frame.resource()) {
            continue;
        }
        if (sub.channel != kAnyChannel && sub.channel != frame.channel()) {
            continue;
        }
        sub.listener(frame, value, sub.ctx);
    }
}

bool CanNode::handleFrame(const CanFrame &frame) {
    const CanId id = frame.fields();

    /* Las tramas emitidas por el propio nodo se ignoran. */
    if (id.source == node_id_) {
        return false;
    }

    if (frame_listener_ != 0) {
        frame_listener_(frame, frame_ctx_);
    }

    switch (id.msg_type) {
        case MSG_STATE:
            dispatchState(frame);
            return true;

        case MSG_EVENT: {
            /* Un evento de entrada remota tambien puede alimentar suscripciones. */
            if (frame.resource() == RES_DIGITAL_INPUT && id.target == kBroadcastTarget) {
                dispatchState(frame);
                return true;
            }
            if (!isForThisNode(id)) {
                return false;
            }
            return applyLocal(frame.resource(), frame.channel(), frame.data[2], frameParam(frame));
        }

        case MSG_GROUP: {
            /* Escenas: se aplican sobre los recursos locales coincidentes. */
            return applyLocal(frame.resource(), frame.channel(), frame.data[2], frameParam(frame));
        }

        case MSG_CONFIG: {
            if (!isForThisNode(id) || config_listener_ == 0) {
                return false;
            }
            config_listener_(frame, config_ctx_);
            return true;
        }

        case MSG_DISCOVERY:
            if (frame.data[2] == DISCOVERY_REQUEST && isForThisNode(id)) {
                publishDiscovery();
                return true;
            }
            return frame.data[2] == DISCOVERY_ANNOUNCE || frame.data[2] == DISCOVERY_RESOURCE;

        default:
            return false;
    }
}

bool CanNode::applyLocal(uint8_t resource, uint8_t channel, uint8_t action, uint32_t param) {
    float value = 0.0f;
    if (!devices_.apply(resource, channel, action, param, value)) {
        return false;
    }
    publishState(resource, channel, value, devices_.flags(resource, channel));
    return true;
}

void CanNode::poll(uint32_t now_ms) {
    if (!boot_ms_valid_) {
        boot_ms_ = now_ms;
        boot_ms_valid_ = true;
    }

    CanFrame frame;
    while (bus_.receive(frame) == CAN_OK) {
        handleFrame(frame);
    }

    devices_.update(now_ms);

    if (!discovery_sent_) {
        publishDiscovery();
        discovery_sent_ = true;
    }

    if (bus_.isBusOff()) {
        bus_.recover();
    }

    if (!heartbeat_sent_ || (now_ms - last_heartbeat_ms_) >= CAN_HEARTBEAT_PERIOD_MS) {
        sendHeartbeat(now_ms);
    }
}

CanStatus CanNode::publishDiscovery() {
    CanStatus status = bus_.send(
        makeDiscoveryAnnounce(node_id_, node_id_mode_, devices_.count()));
    if (status != CAN_OK) {
        return status;
    }
    for (uint8_t i = 0; i < devices_.count(); ++i) {
        const Channel &channel = devices_.at(i);
        status = bus_.send(makeDiscoveryResource(node_id_, channel.resource, channel.channel));
        if (status != CAN_OK) {
            return status;
        }
    }
    return CAN_OK;
}

CanStatus CanNode::sendCommand(uint8_t target, uint8_t resource, uint8_t channel, uint8_t action,
                               uint32_t param) {
    return bus_.send(makeCommand(node_id_, target, resource, channel, action, param));
}

CanStatus CanNode::publishState(uint8_t resource, uint8_t channel, float value, uint16_t flags) {
    return bus_.send(makeStateBroadcast(node_id_, resource, channel, value, flags));
}

CanStatus CanNode::publishTelemetry(uint8_t resource, uint8_t channel, float value,
                                    uint16_t flags) {
    return bus_.send(makeTelemetry(node_id_, resource, channel, value, flags));
}

CanStatus CanNode::publishInputEvent(uint8_t channel, uint8_t event) {
    return bus_.send(makeInputEvent(node_id_, channel, event));
}

CanStatus CanNode::sendConfig(uint8_t target, uint8_t sub_command, const uint8_t *payload,
                              uint8_t payload_len) {
    return bus_.send(makeConfig(node_id_, target, sub_command, payload, payload_len));
}

CanStatus CanNode::sendConfigAck(const uint8_t *payload, uint8_t payload_len) {
    return bus_.send(makeConfig(node_id_, kBroadcastTarget, CFG_ACK, payload, payload_len));
}

CanStatus CanNode::sendHeartbeat(uint32_t now_ms) {
    if (!boot_ms_valid_) {
        boot_ms_ = now_ms;
        boot_ms_valid_ = true;
    }
    last_heartbeat_ms_ = now_ms;
    heartbeat_sent_ = true;
    const uint32_t uptime_s = (now_ms - boot_ms_) / 1000UL;
    return bus_.send(makeHeartbeat(node_id_, uptime_s, bus_.isBusOff() ? 1 : 0));
}

}  // namespace pcd#include "can_protocol.h"

#include <string.h>

namespace pcd {

uint32_t encodeId(uint8_t priority, uint8_t msg_type, uint8_t target, uint16_t source) {
    uint32_t id = 0;
    id |= (static_cast<uint32_t>(priority) & kPriorityMask) << kPriorityShift;
    id |= (static_cast<uint32_t>(msg_type) & kMsgTypeMask) << kMsgTypeShift;
    id |= (static_cast<uint32_t>(target) & kTargetMask) << kTargetShift;
    id |= (static_cast<uint32_t>(source) & kSourceMask) << kSourceShift;
#if PCD_ID_LAYOUT_V2
    /* El Node-ID de 16 bits transporta el ramal en los bits 12..8. */
    id |= (static_cast<uint32_t>(source >> 8) & kSegmentMask) << kSegmentShift;
#endif
    return id & kExtendedIdMask;
}

uint32_t encodeId(const CanId &id) {
    return encodeId(id.priority, id.msg_type, id.target, id.source);
}

CanId decodeId(uint32_t raw_id) {
    CanId id;
    id.priority = static_cast<uint8_t>((raw_id >> kPriorityShift) & kPriorityMask);
    id.msg_type = static_cast<uint8_t>((raw_id >> kMsgTypeShift) & kMsgTypeMask);
    id.target = static_cast<uint8_t>((raw_id >> kTargetShift) & kTargetMask);
    const uint16_t address = static_cast<uint16_t>((raw_id >> kSourceShift) & kSourceMask);
#if PCD_ID_LAYOUT_V2
    id.segment = static_cast<uint8_t>((raw_id >> kSegmentShift) & kSegmentMask);
#else
    id.segment = 0;
#endif
    id.source = static_cast<uint16_t>(((id.segment & kSegmentMask) << 8) | address);
    return id;
}

uint16_t makeNodeId(uint8_t segment, uint8_t address) {
    return static_cast<uint16_t>(((segment & kSegmentMask) << 8) | (address & kSourceMask));
}

uint8_t nodeIdSegment(uint16_t node_id) {
    return static_cast<uint8_t>((node_id >> 8) & kSegmentMask);
}

uint8_t nodeIdAddress(uint16_t node_id) {
    return static_cast<uint8_t>(node_id & kSourceMask);
}

bool isValidTarget(uint8_t target) {
    return target <= kMaxTarget;
}

bool isValidSource(uint16_t source) {
    if (source == 0 || source > kMaxSource) {
        return false;
    }
#if PCD_ID_LAYOUT_V2
    /* La direccion dentro del ramal no puede ser 0: 0xXX00 es reservado. */
    return nodeIdAddress(source) != 0;
#else
    return true;
#endif
}

uint16_t deriveAutomaticNodeId(uint32_t unique_value, uint16_t salt) {
    uint32_t hash = unique_value ^ (static_cast<uint32_t>(salt) << 16);
    hash ^= hash >> 16;
    hash *= 0x45D9F3BUL;
    hash ^= hash >> 16;
#if PCD_ID_LAYOUT_V2
    /* Direccion 1..255 y ramal 0..31 derivados del mismo entero unico. */
    const uint8_t address = static_cast<uint8_t>((hash % kSourceMask) + 1);
    const uint8_t segment = static_cast<uint8_t>((hash >> 16) & kSegmentMask);
    return makeNodeId(segment, address);
#else
    return static_cast<uint16_t>((hash % kMaxSource) + 1);
#endif
}

const char *resourceName(uint8_t resource) {
    switch (resource) {
        case RES_RELAY: return "relay";
        case RES_DIMMER: return "dimmer";
        case RES_DIGITAL_INPUT: return "digital_input";
        case RES_ENV_SENSOR: return "environment";
        case RES_GAS_SENSOR: return "gas";
        case RES_POWER_SENSOR: return "power";
        case RES_COVER: return "cover";
        case RES_BUTTON: return "button";
        case RES_BINARY_SENSOR: return "binary_sensor";
        case RES_LIGHT: return "light";
        case RES_FAN: return "fan";
        case RES_LOCK: return "lock";
        case RES_VALVE: return "valve";
        case RES_WATER_LEAK: return "water_leak";
        case RES_SMOKE: return "smoke";
        case RES_PRESSURE_SENSOR: return "pressure";
        case RES_HUMIDITY_SENSOR: return "humidity";
        case RES_CO2_SENSOR: return "co2";
        case RES_AIR_QUALITY: return "air_quality";
        case RES_GPS: return "gps";
        case RES_VIBRATION_SENSOR: return "vibration";
        case RES_DALI_LIGHT: return "dali_light";
        case RES_KNX_GROUP: return "knx_group";
        case RES_VOLTAGE_SENSOR: return "voltage";
        case RES_CURRENT_SENSOR: return "current";
        case RES_FREQUENCY_SENSOR: return "frequency";
        case RES_ENERGY_SENSOR: return "energy";
        case RES_BATTERY: return "battery";
        case RES_CONFIG: return "config";
        case RES_SYSTEM: return "system";
        default: return "custom";
    }
}

void writeUint16BE(uint8_t *dst, uint16_t value) {
    dst[0] = static_cast<uint8_t>((value >> 8) & 0xFF);
    dst[1] = static_cast<uint8_t>(value & 0xFF);
}

void writeUint32BE(uint8_t *dst, uint32_t value) {
    dst[0] = static_cast<uint8_t>((value >> 24) & 0xFF);
    dst[1] = static_cast<uint8_t>((value >> 16) & 0xFF);
    dst[2] = static_cast<uint8_t>((value >> 8) & 0xFF);
    dst[3] = static_cast<uint8_t>(value & 0xFF);
}

void writeFloatBE(uint8_t *dst, float value) {
    uint32_t bits = 0;
    memcpy(&bits, &value, sizeof(bits));
    writeUint32BE(dst, bits);
}

uint16_t readUint16BE(const uint8_t *src) {
    return static_cast<uint16_t>((static_cast<uint16_t>(src[0]) << 8) | src[1]);
}

uint32_t readUint32BE(const uint8_t *src) {
    return (static_cast<uint32_t>(src[0]) << 24) | (static_cast<uint32_t>(src[1]) << 16) |
           (static_cast<uint32_t>(src[2]) << 8) | static_cast<uint32_t>(src[3]);
}

float readFloatBE(const uint8_t *src) {
    uint32_t bits = readUint32BE(src);
    float value = 0.0f;
    memcpy(&value, &bits, sizeof(value));
    return value;
}

static CanFrame makeFrame(uint8_t priority, uint8_t msg_type, uint16_t source, uint8_t target,
                          uint8_t resource, uint8_t channel) {
    CanFrame frame;
    frame.id = encodeId(priority, msg_type, target, source);
    frame.dlc = kPayloadSize;
    frame.data[0] = resource;
    frame.data[1] = channel;
    return frame;
}

CanFrame makeCommand(uint16_t source, uint8_t target, uint8_t resource, uint8_t channel,
                     uint8_t action, uint32_t param) {
    CanFrame frame = makeFrame(PRIO_REALTIME, MSG_EVENT, source, target, resource, channel);
    frame.data[2] = action;
    writeUint32BE(&frame.data[3], param);
    return frame;
}

CanFrame makeStateBroadcast(uint16_t source, uint8_t resource, uint8_t channel, float value,
                            uint16_t flags) {
    CanFrame frame =
        makeFrame(PRIO_REALTIME, MSG_STATE, source, kBroadcastTarget, resource, channel);
    writeFloatBE(&frame.data[2], value);
    writeUint16BE(&frame.data[6], flags);
    return frame;
}

CanFrame makeTelemetry(uint16_t source, uint8_t resource, uint8_t channel, float value,
                       uint16_t flags) {
    CanFrame frame =
        makeFrame(PRIO_TELEMETRY, MSG_STATE, source, kBroadcastTarget, resource, channel);
    writeFloatBE(&frame.data[2], value);
    writeUint16BE(&frame.data[6], flags);
    return frame;
}

CanFrame makeInputEvent(uint16_t source, uint8_t channel, uint8_t event) {
    CanFrame frame = makeFrame(PRIO_REALTIME, MSG_EVENT, source, kBroadcastTarget,
                               RES_DIGITAL_INPUT, channel);
    frame.data[2] = event;
    return frame;
}

CanFrame makeHeartbeat(uint16_t source, uint32_t uptime_s, uint8_t health) {
    CanFrame frame =
        makeFrame(PRIO_TELEMETRY, MSG_HEARTBEAT, source, kBroadcastTarget, RES_SYSTEM, 0x00);
    frame.data[2] = health;
    writeUint32BE(&frame.data[3], uptime_s);
    return frame;
}

CanFrame makeHealthReport(uint16_t source, const NodeHealth &health) {
    CanFrame frame = makeFrame(PRIO_TELEMETRY, MSG_STATE, source, kBroadcastTarget, RES_SYSTEM,
                               kHealthChannelReport);
    frame.data[2] = health.flags;
    frame.data[3] = health.heap_percent > 100 ? 100 : health.heap_percent;
    frame.data[4] = static_cast<uint8_t>(static_cast<int16_t>(health.temperature_c) + 40);
    frame.data[5] = health.brownout_count;
    frame.data[6] = health.tec;
    frame.data[7] = health.rec;
    return frame;
}

bool decodeHeartbeat(const CanFrame &frame, uint32_t &uptime_s, uint8_t &health_flags) {
    const CanId id = frame.fields();
    if (id.msg_type != MSG_HEARTBEAT || frame.resource() != RES_SYSTEM || frame.dlc < 7) {
        return false;
    }
    health_flags = frame.data[2];
    uptime_s = readUint32BE(&frame.data[3]);
    return true;
}

bool decodeHealthReport(const CanFrame &frame, NodeHealth &out) {
    const CanId id = frame.fields();
    if (id.msg_type != MSG_STATE || frame.resource() != RES_SYSTEM ||
        frame.channel() != kHealthChannelReport || frame.dlc < kPayloadSize) {
        return false;
    }
    out.flags = frame.data[2];
    out.heap_percent = frame.data[3] > 100 ? 100 : frame.data[3];
    out.temperature_c = static_cast<int8_t>(static_cast<int16_t>(frame.data[4]) - 40);
    out.brownout_count = frame.data[5];
    out.tec = frame.data[6];
    out.rec = frame.data[7];
    return true;
}

CanFrame makeDiscoveryRequest(uint16_t source, uint8_t target) {
    CanFrame frame = makeFrame(PRIO_CONFIG, MSG_DISCOVERY, source, target, RES_SYSTEM, 0);
    frame.data[2] = DISCOVERY_REQUEST;
    return frame;
}

CanFrame makeDiscoveryAnnounce(uint16_t source, uint8_t id_mode, uint8_t resource_count) {
    CanFrame frame = makeFrame(PRIO_CONFIG, MSG_DISCOVERY, source, kBroadcastTarget,
                               RES_SYSTEM, 0);
    frame.data[2] = DISCOVERY_ANNOUNCE;
    frame.data[3] = id_mode;
    frame.data[4] = resource_count;
    return frame;
}

CanFrame makeDiscoveryResource(uint16_t source, uint8_t resource, uint8_t channel) {
    CanFrame frame = makeFrame(PRIO_CONFIG, MSG_DISCOVERY, source, kBroadcastTarget,
                               resource, channel);
    frame.data[2] = DISCOVERY_RESOURCE;
    return frame;
}

CanFrame makeConfig(uint16_t source, uint8_t target, uint8_t sub_command, const uint8_t *payload,
                    uint8_t payload_len) {
    CanFrame frame = makeFrame(PRIO_CONFIG, MSG_CONFIG, source, target, RES_CONFIG, sub_command);
    const uint8_t capacity = kPayloadSize - 2;
    if (payload != NULL && payload_len > 0) {
        const uint8_t copied = payload_len > capacity ? capacity : payload_len;
        memcpy(&frame.data[2], payload, copied);
    }
    return frame;
}

CanFrame makeOtaData(uint16_t source, uint8_t target, uint8_t sequence, const uint8_t *chunk,
                     uint8_t chunk_len) {
    CanFrame frame;
    frame.id = encodeId(PRIO_BACKGROUND, MSG_OTA, target, source);
    frame.data[0] = sequence;
    const uint8_t capacity = kPayloadSize - 1;
    const uint8_t copied = (chunk == NULL) ? 0 : (chunk_len > capacity ? capacity : chunk_len);
    if (copied > 0) {
        memcpy(&frame.data[1], chunk, copied);
    }
    frame.dlc = static_cast<uint8_t>(1 + copied);
    return frame;
}

CanFrame makeOtaControl(uint16_t source, uint8_t target, uint8_t command, const uint8_t *payload,
                        uint8_t payload_len) {
    CanFrame frame;
    frame.id = encodeId(PRIO_BACKGROUND, MSG_OTA, target, source);
    frame.data[0] = kOtaControlMarker;
    frame.data[1] = command;
    const uint8_t capacity = kPayloadSize - 2;
    const uint8_t copied = (payload == NULL) ? 0 : (payload_len > capacity ? capacity : payload_len);
    if (copied > 0) {
        memcpy(&frame.data[2], payload, copied);
    }
    frame.dlc = static_cast<uint8_t>(2 + copied);
    return frame;
}

bool isOtaControlFrame(const CanFrame &frame) {
    return frame.fields().msg_type == MSG_OTA && frame.dlc > 0 &&
           frame.data[0] == kOtaControlMarker;
}

bool decodeOtaControl(const CanFrame &frame, uint8_t &command, uint8_t *payload_out) {
    if (!isOtaControlFrame(frame) || frame.dlc < 2) {
        return false;
    }
    command = frame.data[1];
    if (payload_out != 0) {
        for (uint8_t i = 0; i < kPayloadSize - 2; ++i) {
            payload_out[i] = (i + 2 < frame.dlc) ? frame.data[i + 2] : 0;
        }
    }
    return true;
}

float frameValue(const CanFrame &frame) {
    return readFloatBE(&frame.data[2]);
}

uint16_t frameFlags(const CanFrame &frame) {
    return readUint16BE(&frame.data[6]);
}

uint32_t frameParam(const CanFrame &frame) {
    return readUint32BE(&frame.data[3]);
}

}  // namespace pcd#pragma once

/*
 * PCD - Protocolo de Comunicacion Descentralizado sobre CAN 2.0B (29 bits).
 *
 * Distribucion del identificador extendido (layout A, por defecto, PCD v1):
 *
 *   bits 28..26 (3)  Prioridad   0 = critico ... 7 = trafico de fondo
 *   bits 25..21 (5)  Tipo        heartbeat, evento, SDO, OTA, escena, estado
 *   bits 20..14 (7)  Destino     0x01..0x7E, 0x00 = broadcast / grupo
 *   bits 13..0  (14) Origen      0x0001..0x3FFF
 *
 * Layout B (opt-in, -DPCD_ID_LAYOUT_V2=1, PCD v2 para topologias en arbol):
 *
 *   bits 28..26 (3)  Prioridad   0 = critico ... 7 = trafico de fondo
 *   bits 25..21 (5)  Tipo
 *   bits 20..13 (8)  Destino     0x00 = broadcast, 0x01..0xFF direccion de nodo
 *   bits 12..5  (8)  Origen      0x01..0xFF direccion dentro del segmento
 *   bits 4..0   (5)  Segmento    0..31 (ramal / sub-bus de un hub en arbol)
 *
 * En el layout B el Node-ID publico sigue siendo de 16 bits:
 *
 *   node_id = (segmento << 8) | direccion        -> segmento: 5 bits, dir: 8 bits
 *
 * de modo que encodeId()/decodeId() aceptan la misma firma en ambos layouts y
 * el enrutamiento por ramal se resuelve con el campo segmento sin aprender la
 * topologia. Un nodo de la rama 3 con direccion 0x16 es el Node-ID 0x0316.
 *
 * Payload estandar de 8 bytes:
 *
 *   byte 0      Tipo de recurso (rele, dimmer, entrada, sensor, ...)
 *   byte 1      Indice de canal dentro del nodo
 *   bytes 2..7  Comando (accion + parametros) o telemetria (float BE + flags)
 */

#include <stddef.h>
#include <stdint.h>

namespace pcd {

/* ------------------------------------------------------------------ */
/* Layout del identificador de 29 bits                                  */
/* ------------------------------------------------------------------ */

#ifndef PCD_ID_LAYOUT_V2
#define PCD_ID_LAYOUT_V2 0
#endif

static const uint8_t kPriorityShift = 26;
static const uint8_t kMsgTypeShift = 21;

static const uint32_t kPriorityMask = 0x07UL;   /* 3 bits  */
static const uint32_t kMsgTypeMask = 0x1FUL;    /* 5 bits  */
static const uint32_t kExtendedIdMask = 0x1FFFFFFFUL;

static const uint8_t kBroadcastTarget = 0x00;
static const uint8_t kPayloadSize = 8;

#if PCD_ID_LAYOUT_V2

static const uint8_t kTargetShift = 13;         /* 8 bits: 20..13 */
static const uint8_t kSourceShift = 5;          /* 8 bits: 12..5  */
static const uint8_t kSegmentShift = 0;         /* 5 bits: 4..0   */

static const uint32_t kTargetMask = 0xFFUL;
static const uint32_t kSourceMask = 0xFFUL;
static const uint32_t kSegmentMask = 0x1FUL;

static const uint8_t kMaxTarget = 0xFF;
static const uint8_t kMaxSegment = 0x1F;

/* node_id = (segmento << 8) | direccion. */
static const uint16_t kMaxSource = static_cast<uint16_t>((kSegmentMask << 8) | kSourceMask);

/* Segmento por defecto del tronco (backbone) de un hub en arbol. */
static const uint8_t kBackboneSegment = 0x00;

#else

static const uint8_t kTargetShift = 14;         /* 7 bits: 20..14 */
static const uint8_t kSourceShift = 0;          /* 14 bits: 13..0 */

static const uint32_t kTargetMask = 0x7FUL;
static const uint32_t kSourceMask = 0x3FFFUL;
static const uint32_t kSegmentMask = 0x00UL;

static const uint8_t kMaxTarget = 0x7E;
static const uint8_t kMaxSegment = 0x00;

static const uint16_t kMaxSource = 0x3FFF;

static const uint8_t kBackboneSegment = 0x00;

#endif

enum Priority : uint8_t {
    PRIO_CRITICAL = 0,    /* paro de emergencia, alarma termica o de fuego */
    PRIO_REALTIME = 2,    /* control en tiempo real                        */
    PRIO_CONFIG = 4,      /* transacciones SDO / configuracion             */
    PRIO_TELEMETRY = 6,   /* estado y telemetria periodica                 */
    PRIO_BACKGROUND = 7   /* bloques de datos OTA y trafico de fondo       */
};

enum MsgType : uint8_t {
    MSG_HEARTBEAT = 0x01,
    MSG_EVENT = 0x02,      /* PDO: comando / accion            */
    MSG_CONFIG = 0x03,     /* SDO: configuracion y vinculacion */
    MSG_OTA = 0x04,
    MSG_GROUP = 0x05,      /* broadcast de grupo / escenas     */
    MSG_STATE = 0x06,      /* respuesta de estado / ACK        */
    MSG_DISCOVERY = 0x07   /* identidad y capacidades del nodo */
};

enum ResourceType : uint8_t {
    RES_RELAY = 0x10,
    RES_DIMMER = 0x20,
    RES_DIGITAL_INPUT = 0x30,
    RES_ENV_SENSOR = 0x40,
    RES_GAS_SENSOR = 0x50,
    RES_POWER_SENSOR = 0x60,
    RES_COVER = 0x70,
    RES_BUTTON = 0x71,
    RES_BINARY_SENSOR = 0x72,
    RES_LIGHT = 0x73,
    RES_FAN = 0x74,
    RES_LOCK = 0x75,
    RES_VALVE = 0x76,
    RES_WATER_LEAK = 0x77,
    RES_SMOKE = 0x78,
    RES_PRESSURE_SENSOR = 0x80,
    RES_HUMIDITY_SENSOR = 0x81,
    RES_CO2_SENSOR = 0x82,
    RES_AIR_QUALITY = 0x83,
    RES_GPS = 0x84,
    RES_VIBRATION_SENSOR = 0x85,
    /* Bus externos encapsulados por una Extension (0x86..0x8F libre).
     * El canal transporta la direccion corta del dispositivo externo. */
    RES_DALI_LIGHT = 0x86,
    RES_KNX_GROUP = 0x87,
    RES_VOLTAGE_SENSOR = 0x90,
    RES_CURRENT_SENSOR = 0x91,
    RES_FREQUENCY_SENSOR = 0x92,
    RES_ENERGY_SENSOR = 0x93,
    RES_BATTERY = 0x94,
    RES_CONFIG = 0xE0,
    RES_SYSTEM = 0xF0
};

enum Action : uint8_t {
    ACT_OFF = 0x00,
    ACT_ON = 0x01,
    ACT_TOGGLE = 0x02,
    ACT_SET_VALUE = 0x03,
    /* Escena: `param` lleva el numero de escena. Se usa en MSG_GROUP y en los
     * recursos de bus externos que tienen escenas propias (DALI, KNX). */
    ACT_SCENE = 0x10
};

/* Eventos generados por entradas digitales (byte 2 de una trama MSG_EVENT). */
enum InputEvent : uint8_t {
    EVT_RELEASED = 0x10,
    EVT_SHORT_CLICK = 0x11,
    EVT_DOUBLE_CLICK = 0x12,
    EVT_LONG_PRESS = 0x13
};

/*
 * Sub-comandos SDO (byte 1 de una trama MSG_CONFIG).
 *
 * Una regla de vinculacion no entra en los 6 bytes utiles de una trama, por lo
 * que se transfiere segmentada: BEGIN, cuatro CHUNK de 5 bytes y COMMIT con el
 * CRC-16 del conjunto. Hasta que el CRC valida, la regla no se aplica ni se
 * persiste.
 */
enum ConfigCommand : uint8_t {
    CFG_SET_NODE_ID = 0x01,
    CFG_RULE_BEGIN = 0x02,
    CFG_RULE_CHUNK = 0x03,
    CFG_RULE_COMMIT = 0x04,
    CFG_RULE_DELETE = 0x05,
    CFG_RULE_CLEAR = 0x06,
    CFG_SAVE = 0x07,
    CFG_RULE_COUNT = 0x08,
    CFG_ACK = 0x7F,
    CFG_SET_NODE_MODE = 0x09,
    CFG_SUBSCRIBE = 0x0A,
    CFG_UNSUBSCRIBE = 0x0B,
    CFG_CLEAR_SUBSCRIPTIONS = 0x0C
};

enum NodeIdMode : uint8_t {
    NODE_ID_MANUAL = 0x00,
    NODE_ID_AUTOMATIC = 0x01
};

enum DiscoveryCommand : uint8_t {
    DISCOVERY_REQUEST = 0x01,
    DISCOVERY_ANNOUNCE = 0x02,
    DISCOVERY_RESOURCE = 0x03
};

/* Codigos de resultado devueltos en un CFG_ACK. */
enum ConfigStatus : uint8_t {
    CFG_STATUS_OK = 0x00,
    CFG_STATUS_BAD_REQUEST = 0x01,
    CFG_STATUS_CRC_ERROR = 0x02,
    CFG_STATUS_FULL = 0x03,
    CFG_STATUS_STORAGE_ERROR = 0x04
};

/*
 * Sesion OTA (MSG_OTA).
 *
 * Una trama de datos lleva el numero de secuencia en el byte 0 y hasta 7 bytes
 * de firmware. Un numero de secuencia 0xFF se reserva como marca de control:
 *
 *   byte 0      kOtaControlMarker (0xFF)
 *   byte 1      OtaCommand (START, META, READY_ACK, WINDOW_ACK, FINISH, ...)
 *   bytes 2..7  campos del sub-comando (documentados en la wiki 6)
 *
 * Por eso el numero maximo de bloques de datos es kOtaMaxDataBlocks (254).
 */
static const uint8_t kOtaControlMarker = 0xFF;
static const uint16_t kOtaMaxDataBlocks = 0x00FE;

enum OtaCommand : uint8_t {
    OTA_START = 0x01,      /* version + tamano de la imagen            */
    OTA_READY_ACK = 0x02,  /* el receptor acepta la campana            */
    OTA_DATA = 0x03,       /* (solo en la documentacion: sin cabecera) */
    OTA_WINDOW_ACK = 0x04, /* numero de ventana + mapa de faltantes    */
    OTA_FINISH = 0x05,     /* fin de transferencia: el nodo verifica   */
    OTA_ABORT = 0x06,      /* cancela la campana                       */
    OTA_STATUS = 0x07,     /* progreso o diagnostico del receptor      */
    OTA_META = 0x08        /* familia de hardware, CRC-16 y bloques    */
};

/* Resultado devuelto por el receptor en READY_ACK, STATUS, FINISH y ABORT. */
enum OtaStatus : uint8_t {
    OTA_STATUS_OK = 0x00,
    OTA_STATUS_BAD_REQUEST = 0x01,
    OTA_STATUS_WRONG_TARGET = 0x02,
    OTA_STATUS_HW_MISMATCH = 0x03,
    OTA_STATUS_NO_SPACE = 0x04,
    OTA_STATUS_CRC_ERROR = 0x05,
    OTA_STATUS_FLASH_ERROR = 0x06,
    OTA_STATUS_SEQUENCE_ERROR = 0x07,
    OTA_STATUS_TIMEOUT = 0x08,
    OTA_STATUS_NOT_READY = 0x09
};

/* Banderas de diagnostico transportadas en los bytes 6..7 de telemetria. */
enum DiagFlag : uint16_t {
    DIAG_NONE = 0x0000,
    DIAG_SENSOR_ERROR = 0x0001,
    DIAG_OVERTEMPERATURE = 0x0002,
    DIAG_UNDERVOLTAGE = 0x0004,
    DIAG_OVERCURRENT = 0x0008,
    DIAG_CALIBRATING = 0x0010
};

/*
 * Banderas de salud del nodo (byte 2 de MSG_HEARTBEAT y byte 2 del reporte de
 * salud). Se mantienen enmascaradas para que el mapa de bits sea estable.
 */
enum HealthFlag : uint8_t {
    HEALTH_OK = 0x00,
    HEALTH_BUS_OFF = 0x01,
    HEALTH_LOW_HEAP = 0x02,
    HEALTH_OVER_TEMP = 0x04,
    HEALTH_BROWNOUT = 0x08,
    HEALTH_BUS_ERRORS = 0x10,
    HEALTH_SENSOR_FAULT = 0x20,
    HEALTH_CONFIG_LOST = 0x40,
    HEALTH_SERVICE_MODE = 0x80
};

/* Canal del reporte de salud dentro de RES_SYSTEM (MSG_STATE). */
static const uint8_t kHealthChannelReport = 0x02;

/*
 * Estado de salud extendido de un nodo. El heartbeat de 8 bytes solo puede
 * transportar uptime y las banderas de salud, por lo que el resto de las
 * metricas viaja en una trama MSG_STATE con RES_SYSTEM y canal
 * kHealthChannelReport (makeHealthReport()).
 */
struct NodeHealth {
    uint8_t flags;          /* HealthFlag                */
    uint8_t heap_percent;   /* 0..100, heap/RAM libre    */
    int8_t temperature_c;   /* -40..125 grados celsius   */
    uint8_t brownout_count; /* saturado en 255           */
    uint8_t tec;            /* transmit error counter    */
    uint8_t rec;            /* receive error counter     */

    NodeHealth()
        : flags(HEALTH_OK),
          heap_percent(100),
          temperature_c(25),
          brownout_count(0),
          tec(0),
          rec(0) {}
};

/* ------------------------------------------------------------------ */
/* Identificador                                                        */
/* ------------------------------------------------------------------ */

struct CanId {
    uint8_t priority;
    uint8_t msg_type;
    uint8_t target;
    uint16_t source;
    uint8_t segment;   /* layout B: ramal del Node-ID (0 en el layout A) */

    CanId()
        : priority(PRIO_TELEMETRY),
          msg_type(MSG_STATE),
          target(kBroadcastTarget),
          source(0),
          segment(0) {}

    CanId(uint8_t prio, uint8_t type, uint8_t dst, uint16_t src)
        : priority(prio),
          msg_type(type),
          target(dst),
          source(src),
          segment(static_cast<uint8_t>((src >> 8) & kSegmentMask)) {}

    /* Direccion dentro del segmento (los 8 bits bajos del Node-ID). */
    uint8_t address() const { return static_cast<uint8_t>(source & kSourceMask); }

    /* Node-ID completo: segmento y direccion. */
    uint16_t nodeId() const {
        return static_cast<uint16_t>(((segment & kSegmentMask) << 8) | address());
    }
};

/* Empaqueta los cuatro campos en un identificador extendido de 29 bits. */
uint32_t encodeId(const CanId &id);
uint32_t encodeId(uint8_t priority, uint8_t msg_type, uint8_t target, uint16_t source);

/* Descompone un identificador extendido en sus campos. */
CanId decodeId(uint32_t raw_id);

/* Valida rangos de nodo (destino <= kMaxTarget, origen 0x0001..kMaxSource). */
bool isValidTarget(uint8_t target);
bool isValidSource(uint16_t source);
uint16_t deriveAutomaticNodeId(uint32_t unique_value, uint16_t salt = 0x51A7);
const char *resourceName(uint8_t resource);

/* Compone y descompone un Node-ID de 16 bits (segmento << 8 | direccion). */
uint16_t makeNodeId(uint8_t segment, uint8_t address);
uint8_t nodeIdSegment(uint16_t node_id);
uint8_t nodeIdAddress(uint16_t node_id);

/* ------------------------------------------------------------------ */
/* Trama completa                                                       */
/* ------------------------------------------------------------------ */

struct CanFrame {
    uint32_t id;                  /* identificador extendido de 29 bits */
    uint8_t dlc;                  /* bytes validos en data (0..8)       */
    uint8_t data[kPayloadSize];

    CanFrame() : id(0), dlc(0) {
        for (uint8_t i = 0; i < kPayloadSize; ++i) {
            data[i] = 0;
        }
    }

    CanId fields() const { return decodeId(id); }
    uint8_t resource() const { return data[0]; }
    uint8_t channel() const { return data[1]; }
};

/* ------------------------------------------------------------------ */
/* Constructores de tramas                                              */
/* ------------------------------------------------------------------ */

/* Comando dirigido (MSG_EVENT). param se envia en los bytes 3..7. */
CanFrame makeCommand(uint16_t source, uint8_t target, uint8_t resource, uint8_t channel,
                     uint8_t action, uint32_t param = 0);

/* Difusion de estado tras la conmutacion efectiva (MSG_STATE, broadcast). */
CanFrame makeStateBroadcast(uint16_t source, uint8_t resource, uint8_t channel, float value,
                            uint16_t flags = DIAG_NONE);

/* Telemetria periodica de un sensor (MSG_STATE, broadcast, prioridad baja). */
CanFrame makeTelemetry(uint16_t source, uint8_t resource, uint8_t channel, float value,
                       uint16_t flags = DIAG_NONE);

/* Evento local de una entrada digital (MSG_EVENT en broadcast). */
CanFrame makeInputEvent(uint16_t source, uint8_t channel, uint8_t event);

/* Heartbeat de nodo: uptime en segundos y estado de salud. */
CanFrame makeHeartbeat(uint16_t source, uint32_t uptime_s, uint8_t health = 0);

/*
 * Reporte de salud extendido (MSG_STATE, RES_SYSTEM, canal
 * kHealthChannelReport). Acompana al heartbeat y transporta las metricas que
 * no caben en sus 8 bytes: heap libre, temperatura, brown-outs y contadores
 * de error TEC/REC.
 */
CanFrame makeHealthReport(uint16_t source, const NodeHealth &health);

/* Lectura de las tramas de salud. Devuelven false si el formato no coincide. */
bool decodeHeartbeat(const CanFrame &frame, uint32_t &uptime_s, uint8_t &health_flags);
bool decodeHealthReport(const CanFrame &frame, NodeHealth &out);

CanFrame makeDiscoveryRequest(uint16_t source, uint8_t target = kBroadcastTarget);
CanFrame makeDiscoveryAnnounce(uint16_t source, uint8_t id_mode, uint8_t resource_count);
CanFrame makeDiscoveryResource(uint16_t source, uint8_t resource, uint8_t channel);

/* Trama SDO de configuracion / vinculacion logica. */
CanFrame makeConfig(uint16_t source, uint8_t target, uint8_t sub_command, const uint8_t *payload,
                    uint8_t payload_len);

/* Bloque de datos OTA: indice de secuencia + 7 bytes de firmware. */
CanFrame makeOtaData(uint16_t source, uint8_t target, uint8_t sequence, const uint8_t *chunk,
                     uint8_t chunk_len);

/*
 * Trama de control OTA: byte 0 = kOtaControlMarker, byte 1 = OtaCommand y los
 * 6 bytes restantes con los campos del sub-comando (hasta 6 bytes de payload).
 */
CanFrame makeOtaControl(uint16_t source, uint8_t target, uint8_t command, const uint8_t *payload,
                        uint8_t payload_len);

/* Extrae el sub-comando y copia los 6 bytes de campos en payload_out (puede ser 0). */
bool decodeOtaControl(const CanFrame &frame, uint8_t &command, uint8_t *payload_out = 0);

/* true cuando la trama MSG_OTA es de control (no un bloque de firmware). */
bool isOtaControlFrame(const CanFrame &frame);

/* ------------------------------------------------------------------ */
/* Codificacion de la carga util                                        */
/* ------------------------------------------------------------------ */

void writeUint16BE(uint8_t *dst, uint16_t value);
void writeUint32BE(uint8_t *dst, uint32_t value);
void writeFloatBE(uint8_t *dst, float value);

uint16_t readUint16BE(const uint8_t *src);
uint32_t readUint32BE(const uint8_t *src);
float readFloatBE(const uint8_t *src);

/* Valor y banderas de una trama de estado o telemetria. */
float frameValue(const CanFrame &frame);
uint16_t frameFlags(const CanFrame &frame);

/* Parametro (bytes 3..6) de una trama de comando. */
uint32_t frameParam(const CanFrame &frame);

}  // namespace pcd#include <unity.h>

#include "can_node.h"
#include "can_protocol.h"
#include "hal/hal_can_native.h"

using namespace pcd;

/* ------------------------------------------------------------------ */
/* Identificador de 29 bits                                            */
/* ------------------------------------------------------------------ */

void test_id_roundtrip(void) {
    const uint32_t raw = encodeId(PRIO_REALTIME, MSG_EVENT, 0x16, 0x0005);
    const CanId id = decodeId(raw);
    TEST_ASSERT_EQUAL_UINT8(PRIO_REALTIME, id.priority);
    TEST_ASSERT_EQUAL_UINT8(MSG_EVENT, id.msg_type);
    TEST_ASSERT_EQUAL_UINT8(0x16, id.target);
    TEST_ASSERT_EQUAL_UINT16(0x0005, id.source);
}

void test_id_field_layout(void) {
    /* prioridad 5, tipo 0x03, destino 0x7E, origen 0x3FFF */
    const uint32_t raw = encodeId(5, 0x03, 0x7E, 0x3FFF);
    const uint32_t expected = (5UL << 26) | (0x03UL << 21) | (0x7EUL << 14) | 0x3FFFUL;
    TEST_ASSERT_EQUAL_HEX32(expected, raw);
    TEST_ASSERT_EQUAL_HEX32(0, raw & ~kExtendedIdMask);
}

void test_id_fields_do_not_overflow(void) {
    /* Los valores fuera de rango se recortan al ancho de su campo. */
    const uint32_t raw = encodeId(0xFF, 0xFF, 0xFF, 0xFFFF);
    const CanId id = decodeId(raw);
    TEST_ASSERT_EQUAL_UINT8(0x07, id.priority);
    TEST_ASSERT_EQUAL_UINT8(0x1F, id.msg_type);
    TEST_ASSERT_EQUAL_UINT8(0x7F, id.target);
    TEST_ASSERT_EQUAL_UINT16(0x3FFF, id.source);
}

void test_priority_dominates_arbitration(void) {
    /* Menor identificador numerico gana el arbitraje del bus. */
    const uint32_t critical = encodeId(PRIO_CRITICAL, MSG_EVENT, 0x10, 0x3FFF);
    const uint32_t background = encodeId(PRIO_BACKGROUND, MSG_EVENT, 0x01, 0x0001);
    TEST_ASSERT_TRUE(critical < background);
}

void test_address_validation(void) {
    TEST_ASSERT_TRUE(isValidTarget(kBroadcastTarget));
    TEST_ASSERT_TRUE(isValidTarget(0x7E));
    TEST_ASSERT_FALSE(isValidTarget(0x7F));
    TEST_ASSERT_FALSE(isValidSource(0x0000));
    TEST_ASSERT_TRUE(isValidSource(0x3FFF));
}

